export const firefighterQuestions = [

    {
        id: 'fir_001',
        text: {
            en: '🔥 The Rookie\'s First Blaze: You are the first on the nozzle at a raging house fire. Flames are rolling out the front window. A frantic mother screams that her child is in the back bedroom. Your lieutenant orders"Defensive attack only! It’s too fully involved!"The roof looks sagging. What do you do?',
            th: '🔥 ไฟไหม้ครั้งแรกของมือใหม่: คุณเป็นคนถือหัวฉีดคนแรกที่บ้านที่ไฟกำลังลุกโชน เปลวไฟพุ่งออกมาจากหน้าต่างด้านหน้า แม่ที่ตื่นตระหนกกรีดร้องว่าลูกของเธออยู่ในห้องนอนด้านหลัง ผู้หมวดของคุณสั่ง"โจมตีแบบป้องกันเท่านั้น! มันลุกไหม้รุนแรงเกินไป!"หลังคาดูเหมือนกำลังจะถล่ม คุณจะทำอย่างไร?',
            zh: '🔥 新手的第一次火灾：你是一场猛烈房屋火灾中的第一个水枪手。火焰正从前窗卷出。一位疯狂的母亲尖叫着说她的孩子在后面的卧室里。你的中尉命令“只能进行防御性攻击！火势太猛了！”屋顶看起来摇摇欲坠。你会怎么做？'
        },
        options: [
            { id: 'A', text: { en: '🏃 Disobey and Dive In:"I\'m going in! I can\'t let a kid die!"You charge through the front door alone, dragging the line.', th: '🏃 ฝ่าฝืนคำสั่งแล้วลุยเข้าไป:"ฉันจะเข้าไป! ฉันปล่อยให้เด็กตายไม่ได้!"คุณพุ่งผ่านประตูหน้าเข้าไปคนเดียวพร้อมลากสายฉีดน้ำ', zh: '🏃 违抗命令冲进去：“我要进去！我不能让孩子死掉！”你独自拖着水带冲进前门。' }, consequence: { en: '⚠️ Near Miss Tragedy! You find the child, but the roof collapses behind you, trapping you both. RIT team has to rescue you. You saved the kid, but you suffered 2nd-degree burns and endangered your whole team. You face suspension for insubordination.', th: '⚠️ เกือบเป็นโศกนาฏกรรม! คุณเจอเด็ก แต่หลังคาถล่มลงมาด้านหลังคุณ ทำให้คุณทั้งคู่ติดอยู่ ทีม RIT ต้องเข้ามาช่วยคุณ คุณช่วยเด็กได้ แต่คุณถูกไฟลวกระดับ 2 และทำให้ทั้งทีมตกอยู่ในอันตราย คุณถูกพักงานฐานขัดคำสั่ง', zh: '⚠️ 险些酿成悲剧！你找到了孩子，但在你需要撤退时屋顶塌了，将你们俩困住。快速干预小组（RIT）必须营救你。你救了孩子，但遭受了二级烧伤并危及了整个团队。你因不服从命令面临停职。' }, stats: { competence: 15, ethics: 40, leadership: -30, innovation: 10 } },
            { id: 'B', text: { en: '🛡️ Follow Orders (Defensive):"Copy that, Lieutenant."You stay outside and hit the main body of fire from the yard. It feels terrible ignoring the mother.', th: '🛡️ ทำตามคำสั่ง (ป้องกัน):"รับทราบครับผู้หมวด"คุณอยู่ข้างนอกและฉีดน้ำใส่กองไฟหลักจากสนาม มันรู้สึกแย่มากที่ต้องเพิกเฉยต่อแม่', zh: '🛡️ 服从命令（防御性）：“收到，中尉。”你留在外面，从院子里打击主体火势。无视那位母亲的感觉糟透了。' }, consequence: { en: '😔 Tragically Correct. The roof collapses 30 seconds later. If you had gone in, you would be dead. The child sadly perishes. It’s a gut-wrenching lesson: sometimes you can\'t save everyone, and safety protocols are written in blood.', th: '😔 ถูกต้องอย่างน่าเศร้า หลังคาถล่มลงมาใน 30 วินาทีถัดมา ถ้าคุณเข้าไป คุณคงตายไปแล้ว เด็กเสียชีวิตอย่างน่าเศร้า เป็นบทเรียนที่เจ็บปวด: บางครั้งคุณไม่สามารถช่วยทุกคนได้ และกฎความปลอดภัยเขียนขึ้นจากเลือด', zh: '😔 悲剧性的正确。30秒后屋顶倒塌。如果你进去了，你已经死了。孩子不幸丧生。这是一个令人心碎的教训：有时你无法拯救所有人，安全规程是用鲜血写成的。' }, stats: { competence: 30, ethics: 10, leadership: 20, innovation: 0 } },
            { id: 'C', text: { en: '💡 The VES Tactic:"Lieutenant, I\'m going for Vent-Enter-Search via the back bedroom window! It’s safer than the front!"', th: '💡 กลยุทธ์ VES:"ผู้หมวด ผมจะทำ Vent-Enter-Search ผ่านหน้าต่างห้องนอนด้านหลัง! ปลอดภัยกว่าด้านหน้า!"', zh: '💡 VES战术：“中尉，我要通过后卧室窗户进行通风-进入-搜索（VES）！这比从前面进去更安全！”' }, consequence: { en: '✅ Textbook Rescue! You flank the fire. Enter directly into the bedroom, grab the kid, and bail out before the flashover takes the hallway. Lieutenant praises your situational awareness. Kid survives.', th: '✅ การช่วยเหลือตามตำรา! คุณอ้อมไปด้านข้างของไฟ เข้าไปในห้องนอนโดยตรง คว้าตัวเด็ก และกระโดดออกมาก่อนที่ flashover จะกลืนกินโถงทางเดิน ผู้หมวดชมเชยการรับรู้สถานการณ์ของคุณ เด็ก รอดชีวิต', zh: '✅ 教科书般的救援！你侧翼包抄火势。直接进入卧室，抓住孩子，在轰燃吞没走廊之前跳出。中尉称赞你的情境意识。孩子幸存。' }, stats: { competence: 50, ethics: 45, leadership: 30, innovation: 40 } },
            { id: 'D', text: { en: '💦 The Transitional Attack:"Hitting it hard from the outside to reset the fire, then going in!"You blast the ceiling through the window for 10 seconds.', th: '💦 การโจมตีแบบเปลี่ยนผ่าน:"ฉีดอัดหนักๆ จากข้างนอกเพื่อรีเซ็ตไฟ แล้วค่อยเข้าไป!"คุณฉีดน้ำอัดเพดานผ่านหน้าต่างเป็นเวลา 10 วินาที', zh: '💦 过渡性攻击：“从外面猛烈打击以重置火势，通过窗户猛轰天花板10秒，然后进去！”' }, consequence: { en: '⚖️ Effective Compromise. You cool the fire enough to enter safely. You find the kid, but they have severe smoke inhalation due to the delay. They survive but are in critical condition. Good tactics, but seconds mattered.', th: '⚖️ การประนีประนอมที่มีประสิทธิภาพ คุณลดความร้อนของไฟได้พอที่จะเข้าไปอย่างปลอดภัย คุณเจอเด็ก แต่พวกเขาสูดควันเข้าไปมากเนื่องจากความล่าช้า พวกเขารอดแต่ยังอยู่ในอาการวิกฤต กลยุทธ์ดี แต่วินาทีนั้นสำคัญ', zh: '⚖️ 有效的折衷。你将火势冷却到足以安全进入。你找到了孩子，但由于延误，他们严重吸入烟雾。他们幸存下来但情况危急。战术不错，但分秒必争。' }, stats: { competence: 40, ethics: 30, leadership: 25, innovation: 30 } }
        ]
    },

    {
        id: 'fir_002',
        text: {
            en: '🚑 The Frequent Flyer: You respond to a"chest pain"call at 3 AM for a resident who has called 50 times this year for minor issues. They are clearly intoxicated and just want a ride to the hospital for a sandwich. Your partner says,"Let\'s just leave them, we have real emergencies."',
            th: '🚑 ผู้ป่วยขาประจำ: คุณตอบรับสาย"เจ็บหน้าอก"ตอนตี 3 สำหรับผู้พักอาศัยที่โทรมา 50 ครั้งปีนี้ด้วยเรื่องเล็กน้อย พวกเขาเมาชัดเจนและแค่อยากติดรถไปโรงพยาบาลเพื่อกินแซนด์วิช คู่หูของคุณพูดว่า"ทิ้งเขาไว้เถอะ เรามีเหตุฉุกเฉินจริงที่ต้องทำ"',
            zh: '🚑 常客：你在凌晨3点响应一个“胸痛”的呼叫，这就是那个今年为了小事打了50次电话的居民。他们显然喝醉了，只是想搭便车去医院吃个三明治。你的搭档说，“别管他们了，我们还有真正的紧急情况。”'
        },
        options: [
            { id: 'A', text: { en: '🩺 Full Assessment Protocol:"We treat every patient like it\'s the real deal. Assume nothing."You do a full 12-lead ECG and vitals check.', th: '🩺 ขั้นตอนการประเมินเต็มรูปแบบ:"เรารักษาผู้ป่วยทุกคนเหมือนเป็นเรื่องจริง ไม่ตั้งสมมติฐาน"คุณทำ ECG 12 ลีดและตรวจสัญญาณชีพเต็มรูปแบบ', zh: '🩺 全面评估规程：“我们像对待真正的紧急情况一样对待每一位病人。不作任何假设。”你进行了完整的12导联心电图和生命体征检查。' }, consequence: { en: '✅ A Life Saved! The ECG shows a massive STEMI (Heart Attack) disguised by the alcohol symptoms. If you left, they would have died. Your partner apologizes profusely. You reinforce the"Duty to Act"ethic.', th: '✅ ช่วยชีวิตได้! ECG แสดงให้เห็น STEMI (หัวใจวาย) ขนาดใหญ่ที่ถูกอาการเมาบดบัง ถ้าคุณทิ้งไป เขาคงตาย คู่หูของคุณขอโทษอย่างมาก คุณเน้นย้ำจริยธรรม"หน้าที่ในการปฏิบัติ"', zh: '✅ 挽救了一条生命！心电图显示大规模STEMI（心脏病发作），被酒精症状掩盖了。如果你离开，他们就会死。你的搭档不停道歉。你强化了“行动义务”的道德准则。' }, stats: { competence: 45, ethics: 50, leadership: 30, innovation: 10 } },
            { id: 'B', text: { en: '🗣️ The Stern Lecture:"Sir, emergency services are for emergencies. Stop wasting our time."You refuse transport and clear the scene.', th: '🗣️ การเทศนาที่เข้มงวด:"คุณครับ บริการฉุกเฉินมีไว้สำหรับเหตุฉุกเฉิน หยุดทำให้เราเสียเวลา"คุณปฏิเสธการส่งตัวและเคลียร์พื้นที่', zh: '🗣️ 严厉的训斥：“先生，紧急服务是为了紧急情况。别再浪费我们的时间了。”你拒绝转运并离开现场。' }, consequence: { en: '💀 Negligence Liability. He dies of a heart attack 2 hours later. The family sues the department. You lose your EMT license and face potential manslaughter charges. Complacency kills.', th: '💀 ความรับผิดฐานละเลย เขาเสียชีวิตด้วยโรคหัวใจวายในอีก 2 ชั่วโมงต่อมา ครอบครัวฟ้องกรม คุณเสียใบอนุญาต EMT และเผชิญข้อหาฆ่าคนตายโดยไม่เจตนา ความชะล่าใจฆ่าคนได้', zh: '💀 疏忽责任。2小时后他死于心脏病发作。家属起诉部门。你失去了EMT执照并面临潜在的过失杀人指控。自满会杀人。' }, stats: { competence: -20, ethics: -50, leadership: -20, innovation: 0 } },
            { id: 'C', text: { en: '🚕 Cab Voucher Tactic:"We aren\'t a taxi, but I\'ll call you one."You pay for their Uber to the hospital out of pocket.', th: '🚕 กลยุทธ์คูปองแท็กซี่:"เราไม่ใช่แท็กซี่ แต่ฉันจะเรียกให้คุณ"คุณจ่ายค่า Uber ไปโรงพยาบาลให้พวกเขาด้วยเงินส่วนตัว', zh: '🚕 出租车券策略：“我们不是出租车，但我会帮你叫一辆。”你自掏腰包给他们叫了Uber去医院。' }, consequence: { en: '⚠️ Grey Area Solution. You solved the immediate problem without using an ambulance, but you exposed yourself to liability if something happened in the Uber. The Chief warns you against"private transport arrangements."', th: '⚠️ ทางแก้พื้นที่สีเทา คุณแก้ปัญหาเฉพาะหน้าโดยไม่ใช้รถพยาบาล แต่คุณเสี่ยงต่อความรับผิดหากเกิดอะไรขึ้นใน Uber หัวหน้าเตือนคุณเรื่อง"การจัดเตรียมการขนส่งส่วนตัว"', zh: '⚠️ 灰色地带解决方案。你解决了眼前的问题，没有占用救护车，但如果在Uber上发生意外，你将面临责任。局长警告你不要搞“私人交通安排”。' }, stats: { competence: 20, ethics: 20, leadership: 20, innovation: 30 } },
            { id: 'D', text: { en: '🏥 Quick Transport:"Load him up. No lights/sirens. Just get him there and clear fast."Minimum paperwork.', th: '🏥 ส่งตัวด่วน:"พาเขาขึ้นรถ ไม่ต้องเปิดไฟ/ไซเรน แค่พาไปให้ถึงแล้วรีบจบงาน"เอกสารน้อยที่สุด', zh: '🏥 快速转运：“把他弄上去。不开灯/警报。只要把他送到那里并快速离开。”最少的文书工作。' }, consequence: { en: '⏳ System Strain. You wasted 45 minutes on a taxi run. While you were dropping him off, a cardiac arrest call came in 2 blocks from your station. The next unit was 10 minutes away. That patient didn\'t make it.', th: '⏳ ความตึงเครียดของระบบ คุณเสียเวลา 45 นาทีกับการขับแท็กซี่ ในขณะที่คุณกำลังส่งเขา มีสายหัวใจหยุดเต้นเข้ามาห่างจากสถานีคุณ 2 บล็อก หน่วยถัดไปอยู่ห่างไป 10 นาที ผู้ป่วยคนนั้นไม่รอด', zh: '⏳ 系统压力。你在出租车任务上浪费了45分钟。当你把他放下时，距你警局2有两个街区的地方发出了心脏骤停的呼叫。下一个单位在10分钟路程外。那个病人没能挺过来。' }, stats: { competence: 30, ethics: 30, leadership: 10, innovation: 0 } }
        ]
    },

    {
        id: 'fir_003',
        text: {
            en: '⛓️ The Extraction Puzzle: A drunk driver heavily impacted a concrete pillar. The car is crushed like a soda can. The driver is pinned by the dashboard, conscious but bleeding heavily. Fuel is leaking nearby. It will take 20 minutes to cut him out properly, but he might bleed out in 10.',
            th: '⛓️ ปริศนาการกู้ภัย: คนเมาขับรถชนเสาคอนกรีตอย่างจัง รถบุบเหมือนกระป๋องน้ำอัดลม คนขับถูกคอนโซลหน้ารถอัดติด รู้สึกตัวแต่เลือดออกมาก น้ำมันกำลังรั่วไหลอยู่ใกล้ๆ ต้องใช้เวลา 20 นาทีในการตัดถางอย่างถูกวิธี แต่เขาอาจเลือดหมดตัวใน 10 นาที',
            zh: '⛓️ 破拆难题：一名醉酒司机猛烈撞击了混凝土柱。汽车像苏打罐一样被压碎。司机被仪表盘压住，神志清醒但大量出血。附近有燃油泄漏。正确切割需要20分钟，但他可能在10分钟内流光血。'
        },
        options: [
            { id: 'A', text: { en: '🚜 Rapid"Dash Roll": Use the hydraulic spreaders aggressively to roll the dash ASAP, ignoring some vehicle stabilization steps.', th: '🚜"Dash Roll"แบบเร่งด่วน: ใช้เครื่องถ่างไฮดรอลิกอย่างรุนแรงเพื่อม้วนคอนโซลหน้าออกให้เร็วที่สุด โดยข้ามขั้นตอนการทำให้รถมั่นคงบางอย่าง', zh: '🚜 快速“仪表盘翻转”：猛烈使用液压扩张器尽快翻转仪表盘，忽略一些车辆稳定步骤。' }, consequence: { en: '⚡ High Risk, High Reward. The car shifted dangerously, almost crushing your partner\'s hand. BUT, you got the driver out in 6 minutes. The trauma surgeon says he had 2 minutes left. You saved him, but it was reckless.', th: '⚡ ความเสี่ยงสูง ผลตอบแทนสูง รถขยับอย่างน่ากลัว เกือบจะทับมือคู่หูของคุณ แต่คุณเอาคนขับออกมาได้ใน 6 นาที ศัลยแพทย์อุบัติเหตุบอกว่าเขาเหลือเวลาอีก 2 นาที คุณช่วยชีวิตเขาได้ แต่มันบ้าระห่ำ', zh: '⚡ 高风险，高回报。汽车发生了危险的移位，差点压碎你搭档的手。但是，你在6分钟内把司机救了出来。创伤外科医生说他还剩2分钟。你救了他，但这很鲁莽。' }, stats: { competence: 40, ethics: 20, leadership: 30, innovation: 30 } },
            { id: 'B', text: { en: '🛡️ By The Book Stabilization:"Stabilize properly first! We can\'t help him if the car crushes us."cribbing, struts, then cut.', th: '🛡️ การทำให้มั่นคงตามตำรา:"ทำให้มั่นคงก่อน! เราช่วยเขาไม่ได้ถ้ารถทับเรา"ไม้หมอน ค้ำยัน แล้วค่อยตัด', zh: '🛡️ 按章程稳定：“先正确固定！如果车压到我们，就帮不了他了。”垫木，支撑，然后切割。' }, consequence: { en: '😔 Too Safe, Too Late. The extraction was text-book perfect and safe. However, the driver went into cardiac arrest just as you freed his legs. He died on scene. You followed protocol, but lost the life.', th: '😔 ปลอดภัยเกินไป สายเกินไป การกู้ภัยสมบูรณ์แบบตามตำราและปลอดภัย อย่างไรก็ตาม คนขับหัวใจหยุดเต้นในขณะที่คุณเพิ่งจะปล่อยขาเขาได้ เขาเสียชีวิตในที่เกิดเหตุ คุณทำตามขั้นตอน แต่เสียชีวิต', zh: '😔 太安全，太晚了。破拆过程教科书般完美且安全。然而，就在你释放他的双腿时，司机心脏骤停。他当场死亡。你遵循了规程，但失去了生命。' }, stats: { competence: 20, ethics: 30, leadership: 10, innovation: 0 } },
            { id: 'C', text: { en: '💉 Field Amputation Call:"We can\'t get the legs free in time. Dispatch, request a trauma doctor for field amputation."', th: '💉 การตัดอวัยวะในพื้นที่:"เราเอาขาออกไม่ทัน ศูนย์ ขอแพทย์อุบัติเหตุเพื่อตัดอวัยวะในพื้นที่"', zh: '💉 现场截肢呼叫：“我们无法及时把腿弄出来。调度，请求创伤医生进行现场截肢。”' }, consequence: { en: '⚖️ Brutal Reality. The doctor arrives and amputates the leg on the highway. The driver lives but is permanently disabled. The family is grateful he is alive, but the mental toll on your crew is immense. You made the hard call.', th: '⚖️ ความจริงที่โหดร้าย หมอมาถึงและตัดขาบนทางหลวง คนขับรอดแต่พิการถาวร ครอบครัวขอบคุณที่เขารอด แต่ผลกระทบทางจิตใจต่อทีมของคุณนั้นมหาศาล คุณตัดสินใจเรื่องยาก', zh: '⚖️ 残酷的现实。医生赶到并在高速公路上截肢。司机活了下来，但永久残疾。家人感激他还活着，但对你的队员造成的精神打击是巨大的。你做出了艰难的决定。' }, stats: { competence: 35, ethics: 20, leadership: 40, innovation: 20 } },
            { id: 'D', text: { en: '⛓️ Chain Pull Method:"Hook the chains to the fire truck and PULL blocking steering column!"An old-school, disallowed technique.', th: '⛓️ วิธีดึงโซ่:"เอาโซ่เกี่ยวรถดับเพลิงแล้วดึงแกนพวงมาลัยที่ขวางอยู่!"เทคนิคแบบเก่าที่ถูกห้ามใช้', zh: '⛓️ 链条牵引法：“把链条钩在消防车上，拉开阻挡的转向柱！”一种老派的、被禁止的技术。' }, consequence: { en: '🚫 Equipment Failure. The chain snaps under tension and whips back, shattering the windshield and embedding in the seat rest. Nobody hurt, but extraction delayed by 15 mins. Driver dies. You are reprimanded for using banned dangerous tactics.', th: '🚫 อุปกรณ์ล้มเหลว โซ่ขาดด้วยแรงดึงและดีดกลับ กระจกหน้าแตกและฝังในพนักพิง ไม่มีใครเจ็บ แต่การกู้ภัยล่าช้าไป 15 นาที คนขับเสียชีวิต คุณถูกตำหนิฐานใช้กลยุทธ์อันตรายที่ถูกแบน', zh: '🚫 设备故障。链条在拉力下断裂并弹回，击碎了挡风玻璃并嵌入座椅靠背。无人受伤，但破拆延误了15分钟。司机死亡。你因使用被禁止的危险战术而受到训斥。' }, stats: { competence: -10, ethics: 10, leadership: -20, innovation: -10 } }
        ]
    },

    {
        id: 'fir_004',
        text: {
            en: '🚒 The Sleep Deprivation Test: Your station has run 15 calls in 24 hours. You haven\'t slept in 22 hours. A call comes in for a structure fire. You are the driver (Engineer). Your eyes are literally burning and blurring. Do you drive?',
            th: '🚒 บททดสอบการอดนอน: สถานีของคุณออกปฏิบัติงาน 15 สายใน 24 ชั่วโมง คุณไม่ได้นอนมา 22 ชั่วโมง มีสายแจ้งไฟไหม้อาคารเข้ามา คุณเป็นคนขับ (วิศวกร) ตาของคุณแสบและพร่ามัว คุณจะขับไหม?',
            zh: '🚒 睡眠剥夺测试：你的警局在24小时内接了15次电话。你已经22小时没睡了。这时来了一个结构火灾的电话。你是司机（工程师）。你的眼睛简直在燃烧和模糊。你开车吗？'
        },
        options: [
            { id: 'A', text: { en: '☕ Power Through:"I\'m good, Cap!"Chug an energy drink and slap your face. The team needs you.', th: '☕ ฝืนทำต่อ:"ผมไหวครับหัวหน้า!"กระดกเครื่องดื่มชูกำลังแล้วตบหน้าตัวเอง ทีมต้องการคุณ', zh: '☕ 强撑：“我没事，队长！”灌下一罐能量饮料，拍拍脸。团队需要你。' }, consequence: { en: '⚠️ Delayed Reaction. You drive, but you clip a parked car mirror on a tight turn and almost miss the hydrant at the scene. Your pump operation is sluggish. No one died, but you were a liability. Tired driving is drunk driving.', th: '⚠️ ปฏิกิริยาช้าลง คุณขับรถ แต่คุณเฉี่ยวกระจกรถที่จอดอยู่ตรงทางเลี้ยวแคบและเกือบพลาดหัวรับน้ำในที่เกิดเหตุ การทำงานของปั๊มของคุณช้า ไม่มีใครตาย แต่คุณเป็นภาระ การขับรถตอนเหนื่อยเท่ากับการเมาแล้วขับ', zh: '⚠️ 反应迟钝。你开车了，但在急转弯时刮到了停在路边的汽车后视镜，差点错过了现场的消防栓。你的泵操作迟缓。没人死，但你是个累赘。疲劳驾驶就是酒后驾驶。' }, stats: { competence: 20, ethics: 20, leadership: 10, innovation: 0 } },
            { id: 'B', text: { en: '🛑 Tap Out:"Captain, I\'m unsafe to drive. My vision is blurring."Admit defeat.', th: '🛑 ยอมแพ้:"หัวหน้าครับ ผมขับไม่ไหว ตาผมพร่ามัว"ยอมรับความพ่ายแพ้', zh: '🛑 退出：“队长，我开车不安全。我的视力模糊。”承认失败。' }, consequence: { en: '✅ Responsible Courage. The Captain drives instead. You ride bucket (passenger). It slows response by 30 seconds to switch seats, but you arrive safely. The Captain respects your honesty and self-awareness. Safety culture starts with speaking up.', th: '✅ ความกล้าหาญที่รับผิดชอบ หัวหน้าขับแทน คุณนั่งที่นั่งผู้โดยสาร มันทำให้การตอบสนองช้าลง 30 วินาทีเพื่อเปลี่ยนที่นั่ง แต่คุณไปถึงอย่างปลอดภัย หัวหน้าเคารพความซื่อสัตย์และการรู้ตัวเองของคุณ วัฒนธรรมความปลอดภัยเริ่มจากการกล้าพูด', zh: '✅负责任的勇气。队长代替开车。你坐副驾。换座位耽误了30秒响应时间，但你们安全抵达。队长尊重你的诚实和自知之明。安全文化始于大胆直言。' }, stats: { competence: 30, ethics: 50, leadership: 30, innovation: 0 } },
            { id: 'C', text: { en: '💊 Stimulants: Take"Alertness pills"(caffeine/ephedrine) that you keep in your locker for this exact moment.', th: '💊 ยากระตุ้น: กิน"ยาตื่นตัว"(คาเฟอีน/อีเฟดรีน) ที่คุณเก็บไว้ในตู้ล็อคเกอร์สำหรับเวลาแบบนี้โดยเฉพาะ', zh: '💊 兴奋剂：服用你在储物柜里专门为这一刻准备的“清醒药丸”（咖啡因/麻黄碱）。' }, consequence: { en: '⚡ Jittery Danger. You are wide awake but your hands are shaking. You over-pressurize the lines, causing a hose to burst dangeroulsy near the attack team. Your heart rate is 180 sitting still. This is unsustainable and dangerous.', th: '⚡ อันตรายจากการสั่น คุณตื่นเต็มที่แต่มือสั่น คุณเพิ่มแรงดันในสายมากเกินไป ทำให้สายฉีดน้ำระเบิดอย่างอันตรายใกล้ทีมโจมตี อัตราการเต้นของหัวใจคุณคือ 180 ขณะนั่งเฉยๆ นี่ไม่ยั่งยืนและอันตราย', zh: '⚡ 颤抖的危险。你完全清醒但手在发抖。你给管线过度加压，导致攻击小组附近的一根软管危险爆裂。你静坐时的心率是180。这是不可持续且危险的。' }, stats: { competence: 10, ethics: -10, leadership: -20, innovation: -10 } },
            { id: 'D', text: { en: '🏎️ Speed Demon:"Adrenaline will wake me up!"You drive faster than usual to compensate for your fatigue.', th: '🏎️ ปีศาจความเร็ว:"อะดรีนาลีนจะปลุกฉันเอง!"คุณขับเร็วกว่าปกติเพื่อชดเชยความเหนื่อยล้า', zh: '🏎️ 速度恶魔：“肾上腺素会唤醒我！”你开得比平时快以弥补你的疲劳。' }, consequence: { en: '😱 Crash! You blow a red light you didn\'t register. You T-bone a minivan. The fire crew is injured, civilians are critical. You go to jail for vehicular negligence. Career over.', th: '😱 ชน! คุณฝ่าไฟแดงที่คุณมองไม่เห็น คุณชนรถมินิแวนเข้ากลางลำ ทีมดับเพลิงได้รับบาดเจ็บ ประชาชนอาการสาหัส คุณติดคุกฐานขับรถประมาท จบอาชีพ', zh: '😱 车祸！你闯了一个你没注意到的红灯。你拦腰撞上了一辆小型货车。消防员受伤，平民垂危。你因车辆过失入狱。职业生涯结束。' }, stats: { competence: -50, ethics: -50, leadership: -50, innovation: 0 } }
        ]
    },

    {
        id: 'fir_005',
        text: {
            en: '💵 The"Gratitude"Gift: After saving a wealthy family\'s mansion from a wildfire, the owner approaches you privately. He hands you a thick envelope."This is $5,000 cash for you and your crew. No one needs to know. Just a thank you."',
            th: '💵 ของขวัญ"ความกตัญญู": หลังจากช่วยคฤหาสน์ของครอบครัวร่ำรวยจากไฟป่า เจ้าของเข้ามาหาคุณเป็นการส่วนตัว เขายื่นซองหนาให้"นี่คือเงินสด $5,000 สำหรับคุณและทีมของคุณ ไม่มีใครต้องรู้ แค่คำขอบคุณ"',
            zh: '💵 “感谢”礼物：在从野火中拯救了一个富裕家庭的豪宅后，主人私下走近你。他递给你一个厚厚的信封。“这是给你和你队员的5000美元现金。没人需要知道。只是一点心意。”'
        },
        options: [
            { id: 'A', text: { en: '💰 Accept and Split:"Thank you, sir. The beers are on you tonight."You distribute it among the 4 crew members.', th: '💰 รับและแบ่ง:"ขอบคุณครับท่าน คืนนี้เบียร์ฟรี"คุณแบ่งเงินให้ลูกทีม 4 คน', zh: '💰 接受并平分：“谢谢您，先生。今晚啤酒算您的。”你在4名队员中分发了这笔钱。' }, consequence: { en: '⚠️ Corruption Rooted. The crew is happy, but you\'ve compromised your integrity. Six months later, that owner expects you to ignore code violations at his business."Remember the envelope?"You are now owned.', th: '⚠️ รากเหง้าคอร์รัปชัน ทีมมีความสุข แต่คุณเสียความซื่อสัตย์ หกเดือนต่อมา เจ้าของคนนั้นคาดหวังให้คุณเพิกเฉยต่อการละเมิดกฎที่ธุรกิจของเขา"จำซองนั้นได้ไหม?"ตอนนี้คุณเป็นของเขาแล้ว', zh: '⚠️ 腐败生根。队员很高兴，但你损害了你的正直。六个月后，那个主人期望你忽略他企业的违规行为。“还记得那个信封吗？”你现在被收买了。' }, stats: { competence: 10, ethics: -40, leadership: -20, innovation: 0 } },
            { id: 'B', text: { en: '🙅 Polite Refusal:"Thank you, but our taxes pay our salary. We were just doing our job."You walk away.', th: '🙅 ปฏิเสธอย่างสุภาพ:"ขอบคุณครับ แต่ภาษีของเราจ่ายเงินเดือนเราแล้ว เราแค่ทำหน้าที่ของเรา"คุณเดินจากไป', zh: '🙅 礼貌拒绝：“谢谢，但纳税人付了我们薪水。我们只是在做我们的工作。”你走开了。' }, consequence: { en: '✅ Professional Standard. The owner respects you more. He later makes a large public donation to the Firefighter\'s Widows & Orphans Fund instead. Values upheld.', th: '✅ มาตรฐานมืออาชีพ เจ้าของเคารพคุณมากขึ้น ภายหลังเขาบริจาคเงินจำนวนมากให้กับกองทุนแม่หม้ายและเด็กกำพร้าของนักดับเพลิงแทน รักษาคุณค่าไว้ได้', zh: '✅ 专业标准。主人更尊重你了。后来他向消防员遗孀和孤儿基金会做了一大笔公开捐款。价值观得以坚持。' }, stats: { competence: 20, ethics: 50, leadership: 30, innovation: 0 } },
            { id: 'C', text: { en: '🤝 Donation Redirect:"We can\'t take cash, sir. But our station needs a new thermal camera. If you want to buy that for the department, we\'d be grateful."', th: '🤝 เปลี่ยนทิศทางเงินบริจาค:"เรารับเงินสดไม่ได้ครับท่าน แต่สถานีของเราต้องการกล้องตรวจจับความร้อนใหม่ ถ้าท่านอยากซื้อให้กรม เราจะขอบคุณมาก"', zh: '🤝 捐赠重定向：“我们不能收现金，先生。但我们警局需要一个新的热成像仪。如果您想为部门买那个，我们将不胜感激。”' }, consequence: { en: '✨ Resourceful Win. He buys the $5,000 camera. You get new gear legally and ethically. The department praises your initiative in securing resources.', th: '✨ ชัยชนะที่ชาญฉลาด เขาซื้อกล้องราคา $5,000 ให้ คุณได้อุปกรณ์ใหม่ถูกต้องตามกฎหมายและจริยธรรม กรมชมเชยความคิดริเริ่มของคุณในการหาทรัพยากร', zh: '✨ 足智多谋的胜利。他买了那台5000美元的相机。你在法律和道德上都得到了新装备。部门赞扬你在争取资源方面的主动性。' }, stats: { competence: 30, ethics: 40, leadership: 40, innovation: 20 } },
            { id: 'D', text: { en: '🍺"Just buy us dinner":"Keep the cash, but send 50 pizzas to the station."A minor perk.', th: '🍺"แค่เลี้ยงข้าวเราก็พอ":"เก็บเงินไว้เถอะครับ แต่ส่งพิซซ่า 50 ถาดไปที่สถานีนะ"ผลประโยชน์เล็กน้อย', zh: '🍺 “只请我们吃晚饭”：“钱你留着，但送50个披萨到警局。”小恩小惠。' }, consequence: { en: '⚖️ Acceptable Grey Area. Most departments overlook food gifts. The crew enjoys the feast. No major harm done, but slippery slope.', th: '⚖️ พื้นที่สีเทาที่ยอมรับได้ แผนกส่วนใหญ่ไม่ถือสากับของขวัญที่เป็นอาหาร ทีมมีความสุขกับงานเลี้ยง ไม่มีความเสียหายใหญ่หลวง แต่ก็เป็นทางลาดที่ลื่น', zh: '⚖️ 可接受的灰色地带。大多数部门都会忽略食物礼物。队员们享受了盛宴。没有造成大害，但这是滑坡效应。' }, stats: { competence: 10, ethics: 10, leadership: 20, innovation: 0 } }
        ]
    },

    // SECTION 2: OPERATIONAL TACTICS & LEADERSHIP (Questions 6-15),

    {
        id: 'fir_006',
        text: {
            en: '🏢 The Hoarder House: You enter a structure fire and find it packed floor-to-ceiling with trash ("Collyer\'s Mansion"condition). Pathways are narrow tunnnels. Heavy smoke. You lose contact with the hose line. You are disoriented and your low-air alarm whistles. 5 minutes of air left.',
            th: '🏢 บ้านนักสะสมขยะ: คุณเข้าไปในบ้านที่ไฟไหม้และพบว่ามันเต็มไปด้วยขยะจากพื้นจรดเพดาน (สภาพ"Collyer\'s Mansion") ทางเดินเป็นอุโมงค์แคบๆ ควันหนาทึบ คุณหลุดการติดต่อกับสายฉีดน้ำ คุณหลงทางและสัญญาณเตือนอากาศต่ำดังขึ้น เหลืออากาศ 5 นาที',
            zh: '🏢 囤积屋：你进入一个着火的建筑物，发现里面从地板到天花板都堆满了垃圾（“科利尔大厦”状况）。通道是狭窄的隧道。浓烟。你与水带失去联系。你迷失了方向，低气压警报响起。还剩5分钟空气。'
        },
        options: [
            { id: 'A', text: { en: '📻 MAYDAY Call:"MAYDAY, MAYDAY, MAYDAY. Engine 4 firefighter lost, low air, floor 1."Stay put and activate PASS device.', th: '📻 เรียก MAYDAY:"MAYDAY, MAYDAY, MAYDAY นักดับเพลิง Engine 4 หลงทาง อากาศต่ำ ชั้น 1"อยู่กับที่และเปิดใช้อุปกรณ์ PASS', zh: '📻 求救呼叫：“五月天（MAYDAY），五月天，五月天。4号引擎消防员迷路，低气压，1楼。”原地待命并启动PASS装置。' }, consequence: { en: '✅ Survival! It swallows your pride to call Mayday, but RIT finds you in 3 minutes because they heard your PASS alarm. You get out alive. Investigated for getting lost, but praised for following survival doctrine.', th: '✅ รอดชีวิต! มันกลืนศักดิ์ศรีของคุณที่จะเรียก Mayday แต่ RIT เจอคุณใน 3 นาทีเพราะพวกเขาได้ยินเสียงสัญญาณ PASS ของคุณ คุณรอดชีวิต ถูกสอบสวนเรื่องการหลงทาง แต่ได้รับคำชมที่ทำตามหลักการเอาชีวิตรอด', zh: '✅求生！呼叫Mayday让你自尊受挫，但这让快速干预小组（RIT）在3分钟内找到了你，因为他们听到了你的PASS警报。你活着出来了。因迷路被调查，但因遵循生存条令而受到表扬。' }, stats: { competence: 40, ethics: 30, leadership: 20, innovation: 0 } },
            { id: 'B', text: { en: '🏃 Crawl and Pray:"I can find my way out. I remember the turns."You panic-crawl through the trash tunnels trying to find a window.', th: '🏃 คลานและภาวนา:"ฉันหาทางออกได้ ฉันจำทางเลี้ยวได้"คุณคลานผ่านอุโมงค์ขยะด้วยความตื่นตระหนกพยายามหาหน้าต่าง', zh: '🏃 爬行并祈祷：“我能找到出路。我记得转弯处。”你在垃圾隧道中恐慌地爬行，试图找到窗户。' }, consequence: { en: '💀 Disorientation Death. In hoarder houses, layouts make no sense. You crawl deeper into a dead end. You run out of air and asphyxiate. RIT finds your body 2 hours later under a pile of newspapers.', th: '💀 ความตายจากการหลงทาง ในบ้านนักสะสมขยะ แผนผังไม่มีเหตุผล คุณคลานลึกเข้าไปในทางตัน อากาศหมดและขาดอากาศหายใจ RIT พบศพคุณในอีก 2 ชั่วโมงต่อมาใต้กองหนังสือพิมพ์', zh: '💀 迷失方向死亡。在囤积屋里，布局毫无章法。你爬进了一条死胡同。你耗尽空气窒息而死。RIT在2小时后在一堆报纸下发现了你的尸体。' }, stats: { competence: -30, ethics: 0, leadership: -30, innovation: 0 } },
            { id: 'C', text: { en: '🔫 Hose Stream Breaching:"Follow the hose?"No, you lost it. You use your Halligan bar to smash through a nearby wall, hoping it leads outside.', th: '🔫 การเจาะผนัง:"ตามสายฉีดน้ำ?"ไม่ คุณทำมันหาย คุณใช้แท่ง Halligan ทุบผนังใกล้ๆ หวังว่าจะนำไปสู่ภายนอก', zh: '🔫 水流破拆：“跟着水带？”不，你把它弄丢了。你用哈利根撬棍砸穿附近的墙壁，希望它通向外面。' }, consequence: { en: '🎲 Lucky Break. You breach into the kitchen, which has a door. You stumble out with 30 seconds of air left. It was a desperate move that worked, but relying on luck isn\'t a strategy.', th: '🎲 โชคดี คุณเจาะเข้าไปในครัวซึ่งมีประตู คุณสะดุดออกมาโดยเหลืออากาศ 30 วินาที เป็นการกระทำที่สิ้นหวังแต่ได้ผล แต่การพึ่งโชคไม่ใช่กลยุทธ์', zh: '🎲 侥幸逃脱。你闯进了厨房，那是有一扇门。你在还剩30秒空气时跌跌撞撞地跑了出来。这是孤注一掷的一招，奏效了，但依靠运气不是策略。' }, stats: { competence: 20, ethics: 20, leadership: 10, innovation: 20 } },
            { id: 'D', text: { en: '🌬️ Filter Breather:"Disconnect regulator and breath the air near the floor."(The old toxic method).', th: '🌬️ หายใจผ่านตัวกรอง:"ถอดเรกูเลเตอร์แล้วหายใจอากาศใกล้พื้น"(วิธีเก่าที่มีพิษ)', zh: '🌬️ 过滤呼吸：“断开调节器，呼吸地板附近的空气。”（古老的有毒方法）。' }, consequence: { en: '⚠️ Toxic Injury. Modern fires burn plastics/cyanide. Breathing"floor air"burns your lungs chemically. You pass out and are dragged out by RIT. You survive but have permanent lung damage and retire on disability.', th: '⚠️ การบาดเจ็บจากสารพิษ ไฟสมัยใหม่เผาพลาสติก/ไซยาไนด์ การหายใจ"อากาศที่พื้น"เผาปอดคุณด้วยสารเคมี คุณหมดสติและถูกลากออกมาโดย RIT คุณรอดแต่ปอดเสียหายถาวรและต้องเกษียณเพราะพิการ', zh: '⚠️ 中毒受伤。现代火灾燃烧塑料/氰化物。呼吸“地板空气”会化学灼伤你的肺。你昏倒了，被RIT拖了出来。你活了下来，但肺部永久受损，因残疾退休。' }, stats: { competence: -10, ethics: 10, leadership: -10, innovation: -20 } }
        ]
    },

    {
        id: 'fir_007',
        text: {
            en: '🐱 The"Cat in Tree"PR Stunt: The Mayor calls your Chief. A donor\'s cat is stuck up a tree. It\'s not an emergency, but the Chief orders your truck to go"make the donor happy."As you set up the ladder, a"Code Blue"(Cardiac Arrest) usually in your district drops nearby. You are committed to the cat.',
            th: '🐱 การประชาสัมพันธ์"แมวบนต้นไม้": นายกเทศมนตรีโทรหาหัวหน้าของคุณ แมวของผู้บริจาคติดอยู่บนต้นไม้ ไม่ใช่เรื่องฉุกเฉิน แต่หัวหน้าสั่งให้รถของคุณไป"ทำให้ผู้บริจาคมีความสุข"ในขณะที่คุณตั้งบันได"Code Blue"(หัวใจหยุดเต้น) ซึ่งปกติอยู่ในเขตของคุณก็ดังขึ้นใกล้ๆ คุณกำลังติดพันกับแมว',
            zh: '🐱 “树上的猫”公关噱头：市长打电话给你的局长。一位捐赠者的猫困在了树上。这不是紧急情况，但局长命令你的消防车去“让捐赠者高兴”。当你架起梯子时，你辖区附近通常会发生“蓝色代码”（心脏骤停）。你正忙着救猫。'
        },
        options: [
            { id: 'A', text: { en: '🚀 Abandon Cat, Go to CPR:"Pack up! We have a dying human! Sorry about the cat!"You speed off to the cardiac call.', th: '🚀 ทิ้งแมว ไป CPR:"เก็บของ! เรามีคนกำลังจะตาย! ขอโทษเรื่องแมวด้วย!"คุณรีบซิ่งไปที่เหตุหัวใจ', zh: '🚀 放弃猫，去心肺复苏：“收拾东西！我们有个垂死的人！对不起那只猫！”你飞驰去响应心脏急救。' }, consequence: { en: '✅ Moral Victory, Political Heat. You arrive in time and revive the patient. The Mayor is furious about the"insulted donor"and writes you up. But the patient\'s family writes a letter to the paper praising you. You sleep well at night.', th: '✅ ชัยชนะทางศีลธรรม ความร้อนแรงทางการเมือง คุณมาถึงทันเวลาและช่วยชีวิตผู้ป่วย นายกเทศมนตรีโกรธเรื่อง"ผู้บริจาคที่ถูกดูหมิ่น"และลงโทษคุณ แต่ครอบครัวผู้ป่วยเขียนจดหมายถึงหนังสือพิมพ์ชมเชยคุณ คุณนอนหลับสบาย', zh: '✅ 道德胜利，政治压力。你及时赶到并救活了病人。市长对“受辱的捐赠者”感到愤怒并给你记过。但病人家属给报社写信表扬你。你晚上睡得很香。' }, stats: { competence: 50, ethics: 50, leadership: 40, innovation: 0 } },
            { id: 'B', text: { en: '😿 Stick to Orders:"We save the cat. Another unit will get the heart attack."You finish the cat rescue slowly.', th: '😿 ทำตามคำสั่ง:"เราช่วยแมว หน่วยอื่นจะไปดูหัวใจวายเอง"คุณช่วยแมวเสร็จอย่างช้าๆ', zh: '😿 坚持命令：“我们救猫。另一个单位回去处理心脏病发作。”你慢慢完成了救猫任务。' }, consequence: { en: '💀 Delayed Response. The next ambulance takes 12 minutes to reach the cardiac patient. They die. The news runs a split screen story:"Firefighters save cat while grandfather dies 2 blocks away."The department looks incompetent.', th: '💀 การตอบสนองล่าช้า รถพยาบาลคันถัดไปใช้เวลา 12 นาทีในการไปถึงผู้ป่วยหัวใจ พวกเขาเสียชีวิต ข่าวออแบบจอแยก:"นักดับเพลิงช่วยแมวในขณะที่ปู่ตายห่างไป 2 บล็อก"กรมดูไร้ความสามารถ', zh: '💀 延迟响应。下一辆救护车花了12分钟才到达心脏病患者那里。他们死了。新闻播放了分屏故事：“消防员救猫，祖父在两个街区外去世。”部门看起来很无能。' }, stats: { competence: -10, ethics: -40, leadership: -20, innovation: 0 } },
            { id: 'C', text: { en: '🏎️ Split Crew:"Driver and Medic, take the Medical Car to the CPR! I\'ll stay with the rookie and get the cat!"', th: '🏎️ แยกทีม:"คนขับและแพทย์ เอารถแพทย์ไป CPR! ฉันจะอยู่กับน้องใหม่ช่วยแมว!"', zh: '🏎️ 分队：“司机和医护人员，开医疗车去心肺复苏！我和新人留下来救猫！”' }, consequence: { en: '✨ Creative Solution. Your medic arrives just in time to start CPR. You finish the cat rescue solo. You stressed your resources, but managed to satisfy both the Mayor\'s ego and the duty to save lives. Stressful but effective.', th: '✨ ทางแก้ที่สร้างสรรค์ แพทย์ของคุณมาถึงทันเวลาเริ่ม CPR คุณช่วยแมวเสร็จคนเดียว คุณใช้ทรัพยากรตึงเครียด แต่จัดการตอบสนองทั้งอัตตาของนายกเทศมนตรีและหน้าที่ช่วยชีวิต เครียดแต่ได้ผล', zh: '✨ 创造性解决方案。你的医护人员正好赶到开始心肺复苏。你独自完成了救猫任务。你的资源很紧张，但设法既满足了市长的自尊心，又履行了救死扶伤的职责。压力很大但有效。' }, stats: { competence: 40, ethics: 30, leadership: 50, innovation: 40 } },
            { id: 'D', text: { en: '🤥 Fake Mechanics:"Radio dispatch: Truck 4 has a mechanical failure, ladder won\'t retract. We are stuck."Force them to send another unit immediately.', th: '🤥 แกล้งรถเสีย:"วิทยุบอกศูนย์: Truck 4 เครื่องยนต์ขัดข้อง บันไดเก็บไม่ได้ เราติดอยู่"บังคับให้พวกเขาส่งหน่วยอื่นทันที', zh: '🤥 假装机械故障：“无线电调度：4号卡车机械故障，梯子收不回来。我们被卡住了。”迫使他们立即派遣另一个单位。' }, consequence: { en: '⚖️ Manipulative Good. Dispatch sends another unit instantly knowing you are OOS. You saved the department not making the hard choice, but lying on radio is a firing offense if caught.', th: '⚖️ ความดีแบบบิดเบือน ศูนย์ส่งหน่วยอื่นทันทีเพราะรู้ว่าคุณ OOS คุณช่วยกรมไม่ต้องเลือกยาก แต่การโกหกทางวิทยุเป็นความผิดที่ไล่ออกได้ถ้าถูกจับได้', zh: '⚖️ 操纵性的好意。调度员知道你停止服务（OOS）后立即派遣了另一个单位。你挽救了部门不必做出艰难选择，但无线电撒谎如果被抓到会被开除。' }, stats: { competence: 20, ethics: -10, leadership: 10, innovation: 20 } }
        ]
    },

    {
        id: 'fir_008',
        text: {
            en: '⚡ The "Silent" Voltage: You are venting a roof during a house fire. You notice a large solar panel array. The main power is cut, but the panels are still generating 600V DC. Smoke is coming from the attic directly under them. Your captain orders you to "cut a hole right there!"',
            th: '⚡ แรงดันไฟฟ้าที่เงียบงัน: คุณกำลังระบายอากาศบนหลังคาระหว่างเกิดเหตุไฟไหม้บ้าน คุณสังเกตเห็นแผงโซลาร์เซลล์จำนวนมาก ไฟหลักถูกตัดแล้ว แต่แผงยังคงผลิตไฟฟ้ากระแสตรง 600V ควันกำลังออกมาจากห้องใต้หลังคาใต้แผงเหล่านั้นโดยตรง หัวหน้าสั่งให้คุณ "เจาะรูตรงนั้นเลย!"',
            zh: '⚡ “静默”电压：你在火灾期间正在楼顶排烟。你发现了一个太阳能电池板阵列。虽然主电源已断开，但电池板仍在产生600V直流电。它们正下方的阁楼正在冒烟。你的队长命令你“就在那儿切个洞！”'
        },
        options: [
            { id: 'A', text: { en: '🪓 Cut Anyway: "Orders are orders! I\'ll be careful."', th: '🪓 เจาะเลย: "คำสั่งคือคำสั่ง! ฉันจะระวัง"', zh: '🪓 照常切割：“命令就是命令！我会小心的。”' }, consequence: { en: '😱 Electrocution. Your saw blade hits the high-voltage lines. You receive a massive shock, throwing you off the roof. You survive but with permanent nerve damage. Solar panels are "always on." Never cut through them.', th: '😱 ไฟฟ้าช็อต! ใบเลื่อยของคุณโดนสายไฟแรงสูง คุณถูกช็อตอย่างรุนแรงจนกระเด็นตกจากหลังคา คุณรอดมาได้แต่มีความเสียหายทางประสาทถาวร แผงโซลาร์เซลล์คือ "เปิดตลอดเวลา" ห้ามตัดผ่านเด็ดขาด', zh: '😱 电击。你的锯片碰到了高压线。你遭到了剧烈的电击，被从房顶甩了下来。你活了下来，但留下了永久性的神经损伤。太阳能电池板是“常通电”的。绝不要切过它们。' }, stats: { competence: 10, ethics: 20, leadership: 10, innovation: 0 } },
            { id: 'B', text: { en: '🛑 Refuse and Relocate: "Captain, those panels are live! I\'m moving 10 feet to the left where it\'s clear."', th: '🛑 ปฏิเสธและเปลี่ยนจุด: "หัวหน้าครับ แผงพวกนั้นยังมีไฟ! ผมจะขยับไปทางซ้าย 10 ฟุตตรงที่ไม่มีแผง"', zh: '🛑 拒绝并换地：“队长，那些板子带电！我要往左移动10英尺到空地去。”' }, consequence: { en: '✅ Expert Safety. You cut the hole safely away from the panels. The attic vents, and the interior teams can see again. You saved the house without getting fried. The Captain thanks you for the catch.', th: '✅ ความปลอดภัยระดับผู้เชี่ยวชาญ คุณเจาะรูห่างจากแผงอย่างปลอดภัย ห้องใต้หลังคาระบายอากาศได้ และทีมข้างในมองเห็นอีกครั้ง คุณช่วยบ้านไว้ได้โดยไม่โดนไฟดูด หัวหน้าขอบคุณที่คุณทักท้วง', zh: '✅ 专业安全性。你在远离电池板的安全地带切开了洞。阁楼排烟后，内部队员恢复了视线。你保住了房子而没有触电。队长感谢你的提醒。' }, stats: { competence: 50, ethics: 40, leadership: 40, innovation: 20 } },
            { id: 'C', text: { en: '🌊 Foam it First: "Cover the panels with foam to block the sun, then cut."', th: '🌊 ฉีดโฟมก่อน: "คลุมแผงด้วยโฟมเพื่อบังแดดแล้วค่อยเจาะ"', zh: '🌊 先喷泡沫：“用泡沫覆盖电池板以遮挡阳光，然后切割。”' }, consequence: { en: '⚠️ Creative but Flawed. The foam blocks some light, but infrared still generates current. It\'s better, but still dangerous. You got lucky and didn\'t hit a line, but it was a risky tactic.', th: '⚠️ สร้างสรรค์แต่มีข้อบกพร่อง โฟมบังแสงได้บางส่วน แต่รังสีอินฟราเรดยังคงผลิตกระแสไฟฟ้าได้ มันดีขึ้นแต่ยังอันตราย คุณโชคดีที่ไม่โดนสายไฟ แต่มันเป็นกลยุทธ์ที่เสี่ยง', zh: '⚠️ 有创意但有缺陷。泡沫遮挡了一些光线，但红外线仍在产生电流。虽有改善但依然危险。你运气好没碰到电线，但这依然是冒险的战术。' }, stats: { competence: 30, ethics: 30, leadership: 20, innovation: 50 } },
            { id: 'D', text: { en: '🪜 Vent via Eaves: "Too risky to cut the roof. I\'ll vent from the gables instead."', th: '🪜 ระบายทางชายคา: "เจาะหลังคาเสี่ยงไป ผมจะระบายทางหน้าจั่วแทน"', zh: '🪜 从檐口排烟：“切割房顶太危险了。我要改从山墙排烟。”' }, consequence: { en: '⚖️ Safe but Ineffective. The gable vent is too small. The attic heat builds up, and the roof eventually collapses anyway. You stayed 100% safe, but the house was lost due to insufficient ventilation.', th: '⚖️ ปลอดภัยแต่ไม่ได้ผล ช่องระบายที่หน้าจั่วเล็กเกินไป ความร้อนสะสมในห้องใต้หลังคา และสุดท้ายหลังคาก็ถล่มลงมาอยู่ดี คุณปลอดภัย 100% แต่บ้านเสียหายเพราะการระบายอากาศไม่พอ', zh: '⚖️ 安全但无效。山墙通风口太小了。阁楼热量积聚，屋顶最终还是塌了。虽然你100%安全，但由于通风不足，房子被毁了。' }, stats: { competence: 25, ethics: 20, leadership: 20, innovation: 0 } }
        ]
    },

    {
        id: 'fir_009',
        text: {
            en: '🚢 The Marine Fire: A container ship in the harbor is reporting fire in the hold. You arrive and smell sweet almonds (Cyanide gas). The ship\'s captain wants you to spray water into the hold immediately. Your computer shows the containers are full of Magnesium. What do you do?',
            th: '🚢 ไฟไหม้บนเรือ: เรือบรรทุกคอนเทนเนอร์ในท่าเรือรายงานว่ามีไฟไหม้ในระวางเรือ คุณถึงที่หมายและได้กลิ่นเหมือนอัลมอนด์หวาน (ก๊าซไซยาไนด์) กัปตันเรือต้องการให้คุณฉีดน้ำเข้าไปในระวางเรือทันที คอมพิวเตอร์ของคุณแสดงว่าคอนตเนเนอร์เต็มไปด้วยแมกนีเซียม คุณจะทำอย่างไร?',
            zh: '🚢 船舶火灾：港口的一艘集装箱船报告货舱着火。你到达后闻到一股甜杏仁味（氰化氢气体）。船长要求你立即向货舱喷水。你的电脑显示集装箱里装满了镁。你会怎么做？'
        },
        options: [
            { id: 'A', text: { en: '💦 Spray Massive Water:"Drown it! High volume deck guns now!"You follow the Captain\'s request.', th: '💦 ฉีดน้ำมหาศาล:"จมมันซะ! ใช้ปืนฉีดน้ำแรงดันสูงเดี๋ยวนี้!"คุณทำตามคำขอของกัปตัน', zh: '💦 大规模喷水：“淹没它！立即使用高流量甲板炮！”你遵循了船长的要求。' }, consequence: { en: '😱 Catastrophic Explosion. Magnesium reacts violently with water, creating hydrogen gas. The entire ship hold explodes, injuring dozens. The cyanide gas is dispersed into the city air. Total disaster. You ignored common chemical knowledge.', th: '😱 การระเบิดที่หายนะ แมกนีเซียมทำปฏิกิริยารุนแรงกับน้ำ สร้างก๊าซไฮโดรเจน ระวางเรือทั้งลำระเบิด ทำให้มีผู้บาดเจ็บหลายสิบคน ก๊าซไซยาไนด์ฟุ้งกระจายไปในอากาศของเมือง หายนะโดยสมบูรณ์ คุณละเลยความรู้พื้นฐานทางเคมี', zh: '😱 灾难性的爆炸。镁与水发生剧烈反应，产生氢气。整个船舱爆炸，导致数十人受伤。氰化氢气体扩散到城市空气中。彻头彻尾的灾难。你忽略了基本的化学常识。' }, stats: { competence: -50, ethics: 10, leadership: -30, innovation: 0 } },
            { id: 'B', text: { en: '🧪 Specialized Suppressant:"Stop! No water! We need massive Class D Dry Powder or CO2 flooding!"You call for specialized marine firefighting assets.', th: '🧪 สารดับไฟเฉพาะทาง:"หยุด! ห้ามใช้น้ำ! เราต้องการผงเคมีแห้ง Class D หรือก๊าซ CO2 จำนวนมาก!"คุณเรียกใช้ทรัพยากรดับเพลิงทางน้ำเฉพาะทาง', zh: '🧪 专门灭火剂：“停！不能用水！我们需要大量的D类干粉或二氧化碳淹没！”你要求调集专门的船舶消防物资。' }, consequence: { en: '✅ Disaster Averted. It takes 30 minutes longer, but the chemical fire is smothered safely. You educate the ship\'s captain on the danger. The port is saved from a massive toxic leak and explosion. You are a hazmat hero.', th: '✅ เลี่ยงหายนะได้สำเร็จ ใช้เวลานานขึ้น 30 นาที แต่ไฟไหม้เคมีถูกดับอย่างปลอดภัย คุณให้ความรู้กัปตันเรือเกี่ยวกับอันตราย ท่าเรือรอดพ้นจากการรั่วไหลของสารพิษและการระเบิดครั้งใหญ่ คุณคือฮีโร่ด้านสารอันตราย', zh: '✅ 避免灾难。虽然多花了30分钟，但化学火灾被安全扑灭。你告知了船长其中的危险。港口免于大规模的有毒泄漏和爆炸。你是防化英雄。' }, stats: { competence: 50, ethics: 40, leadership: 40, innovation: 30 } },
            { id: 'C', text: { en: '🛑 Seal and Abandon:"It\'s too dangerous. Close the hold covers and let it burn out. Evacuate the ship."', th: '🛑 ปิดและทิ้ง:"มันอันตรายเกินไป ปิดฝาระวางเรือแล้วปล่อยให้ไหม้จนหมด อพยพคนออกจากเรือ"', zh: '🛑 密封并放弃：“太危险了。关上舱盖，让它烧光。疏散全船。”' }, consequence: { en: '⚠️ Containment Win. The fire is contained, but the ship is a total loss ($200M value). Shipping industry is unhappy with the economic loss, but no one died. A conservative, safe, but expensive choice.', th: '⚠️ ชนะด้วยการกักกัน ไฟถูกกักไว้ได้ แต่เรือเสียหายโดยสิ้นเชิง (มูลค่า 200 ล้านดอลลาร์) อุตสาหกรรมการขนส่งไม่พอใจกับความสูญเสียทางเศรษฐกิจ แต่ไม่มีใครตาย เป็นทางเลือกที่อนุรักษนิยม ปลอดภัย แต่แพง', zh: '⚠️ 遏制胜利。火势得到了控制，但船只全损（价值2亿美元）。航运业对经济损失感到不满，但无人死亡。这是一个保守、安全但代价昂贵的选择。' }, stats: { competence: 30, ethics: 30, leadership: 30, innovation: 10 } },
            { id: 'D', text: { en: '🔍 Internal Recon:"I\'m going in with a thermal camera to see exact locations of Magnesium before we decide."', th: '🔍 สำรวจภายใน:"ฉันจะเข้าไปพร้อมกล้องตรวจจับความร้อนเพื่อดูตำแหน่งที่แน่นอนของแมกนีเซียมก่อนที่เราจะตัดสินใจ"', zh: '🔍 内部勘察：“我要带着热成像仪进去，在做决定之前先看看镁的确切位置。”' }, consequence: { en: '💀 Poisoned. You enter a hold filled with colorless, odorless concentrated cyanide because your detector failed or you didn\'t trust it. You collapse before you see the fire. Your partner tries to save you; you both die. Never enter unknown toxic atmospheres without a plan.', th: '💀 ได้รับสารพิษ คุณเข้าไปในระวางเรือที่เต็มไปด้วยไซยาไนด์เข้มข้นที่ไม่มีสีและไม่มีกลิ่น เนื่องจากเครื่องตรวจจับเสียหรือคุณไม่เชื่อมัน คุณหมดสติก่อนจะเห็นไฟ คู่หูของคุณพยายามช่วยคุณ คุณทั้งคู่ตาย อย่าเข้าสู่บรรยากาศที่เป็นพิษโดยไม่มีแผน', zh: '💀 中毒。你进入了一个充满无色无味浓缩氰化氢的货舱，因为你的探测器失灵了或者你不信任它。还没看到火你就晕倒了。你的搭档试图救你；你们都死了。绝不要在没有计划的情况下进入未知的有毒环境。' }, stats: { competence: -20, ethics: 20, leadership: -20, innovation: 10 } }
        ]
    },

    {
        id: 'fir_010',
        text: {
            en: '🏢 The Warehouse Collapse: You are searching for a missing child in a burning furniture warehouse. Suddenly, a massive"crack"echoes. A 40-foot storage rack collapses 10 feet behind you, blocking your only exit. Fire is growing. The child\'s cries are coming from further in. You have 10 minutes of air.',
            th: '🏢 โกดังถล่ม: คุณกำลังตามหาเด็กที่หายไปในโกดังเฟอร์นิเจอร์ที่กำลังไฟไหม้ ทันใดนั้น เสียง"แคร็ก"ดังลั่น ชั้นวางของสูง 40 ฟุตถล่มลงมาด้านหลังคุณ 10 ฟุต ปิดกั้นทางออกเดียวของคุณ ไฟกำลังขยายตัว เสียงร้องของเด็กมาจากด้านในลึกขึ้นไปอีก คุณเหลืออากาศ 10 นาที',
            zh: '🏢 仓库坍塌：你正在着火的家具仓库中寻找失踪的孩子。突然，一声巨大的“咔嚓”声响起。一个40英尺高的储物架在你身后10英尺处坍塌，堵住了你唯一的出口。火势正在蔓延。孩子的哭声从里面传来。你还有10分钟的空气。'
        },
        options: [
            { id: 'A', text: { en: '🏃 Double Down:"I\'m already trapped, might as well get the kid!"You charge toward the voice.', th: '🏃 ทุ่มสุดตัว:"ฉันก็ติดอยู่แล้วนี่นา อย่างน้อยก็ขอช่วยเด็กให้ได้!"คุณพุ่งไปยังทิศทางของเสียง', zh: '🏃 孤注一掷：“反正都被困住了，不如先把孩子救了！”你冲向声音传来的方向。' }, consequence: { en: '✅ Miracle Save. You find the child. You use a forklift nearby to ram through a loading dock door that was locked from the outside. You burst out into the fresh air as the roof caves in. Legendary Bravery, but you ignored"self-preservation"rules.', th: '✅ การช่วยชีวิตที่ปาฏิหาริย์ คุณเจอเด็ก คุณใช้รถโฟล์คลิฟท์ที่อยู่ใกล้ๆ พุ่งชนประตูท่าโหลดสินค้าที่ล็อกจากข้างนอก คุณพุ่งออกมาสู่อากาศบริสุทธิ์ขณะที่หลังคาถล่มลงมา ความกล้าหาญระดับตำนาน แต่คุณละเลยกฎ"การรักษาชีวิตตัวเอง"', zh: '✅ 奇迹般的救援。你找到了孩子。你利用附近的叉车撞开了从外面锁上的装卸码头门。就在屋顶塌陷时，你冲到了新鲜空气中。传奇般的英勇，但你忽略了“自保”规则。' }, stats: { competence: 40, ethics: 50, leadership: 20, innovation: 45 } },
            { id: 'B', text: { en: '📻 MAYDAY and Wait:"MAYDAY! Exit blocked by rack collapse. I\'m searching for a child."You stay near the collapse point so RIT can find you.', th: '📻 เรียก MAYDAY และรอ:"MAYDAY! ทางออกถูกปิดกั้นโดยชั้นวางของถล่ม ฉันกำลังตามหาเด็ก"คุณอยู่ใกล้จุดที่ถล่มเพื่อให้ RIT หาคุณเจอ', zh: '📻 呼救并等待：“五月天！货架坍塌堵住了出口。我正在搜救孩子。”你留在坍塌点附近，以便RIT能找到你。' }, consequence: { en: '💀 Tragic Outcome. RIT spends 15 minutes cutting through the rack. By the time they reach you, you are out of air and unconscious. They never found the child in time. Following Mayday protocol is good, but in high-heat warehouse fires, minutes mean death.', th: '💀 ผลลัพธ์ที่น่าเศร้า RIT ใช้เวลา 15 นาทีในการตัดชั้นวางของ เมื่อพวกเขามาถึงคุณ คุณหมดอากาศและหมดสติ พวกเขาหาเด็กไม่พบทันเวลา การทำตามขั้นตอน Mayday เป็นเรื่องดี แต่ในไฟไหม้โกดังที่มีความร้อนสูง ทุกนาทีคือความตาย', zh: '💀 悲剧性的结果。RIT花了15分钟切割货架。当他们找到你时，你已经耗尽空气并失去知觉。他们没能及时找到孩子。遵循Mayday流程是对的，但在高温仓库火灾中，分钟就意味着死亡。' }, stats: { competence: 20, ethics: 30, leadership: 10, innovation: 0 } },
            { id: 'C', text: { en: '🧱 Breaching Wall:"I\'m not waiting."You use your axe to breach a cinder block exterior wall. It\'s slow, but it\'s a direct exit.', th: '🧱 ทลายผนัง:"ฉันไม่รอแล้ว"คุณใช้ขวานทลายผนังภายนอกที่เป็นคอนกรีตบล็อก มันช้า แต่มันเป็นทางออกโดยตรง', zh: '🧱 破墙：“我不等了。”你用斧头劈开混凝土外墙。虽然慢，但这是一个直接的出路。' }, consequence: { en: '⚠️ Escape but Loss. You manage to break through a small hole and escape just as the building flashes over. You survived, but you left the child behind. You are hailed as a"survivor"but live with the crushing guilt of the loss.', th: '⚠️ หนีรอดแต่สูญเสีย คุณจัดการพังรูเล็กๆ และหนีออกมาได้ทันเวลาที่ตัวอาคารเกิด flashover คุณรอดชีวิต แต่คุณทิ้งเด็กไว้ข้างหลัง คุณได้รับการขนานนามว่าเป็น"ผู้รอดชีวิต"แต่ต้องอยู่กับความรู้สึกผิดที่รุนแรงจากการสูญเสีย', zh: '⚠️ 逃生但有损失。就在建筑发生轰燃时，你设法打穿一个小洞逃了出来。你活了下来，但把孩子留在了后面。你被誉为“幸存者”，但却生活在失去生命的沉重愧疚感中。' }, stats: { competence: 35, ethics: 10, leadership: 15, innovation: 20 } },
            { id: 'D', text: { en: '🔦 Systematic Search:"I have 10 minutes. 2 minutes to find the kid, 8 minutes to find another way out."You stay calm and methodical.', th: '🔦 การค้นหาอย่างเป็นระบบ:"ฉันมี 10 นาที 2 นาทีสำหรับหาเด็ก 8 นาทีสำหรับหาทางออกอื่น"คุณรักษาสติและทำอย่างเป็นขั้นตอน', zh: '🔦 系统搜救：“我有10分钟。2分钟找孩子，8分钟找别的出路。”你保持冷静，有条不紊。' }, consequence: { en: '✅ Professional Peak. You find the child quickly. You remember seeing a skylight 30 feet away. You use a ladder from a rack to reach it, smash the glass, and lift the child to safety as external crews assist. Incredible composure under life-threatening stress.', th: '✅ จุดสูงสุดของมืออาชีพ คุณเจอเด็กอย่างรวดเร็ว คุณจำได้ว่าเห็นช่องแสงห่างออกไป 30 ฟุต คุณใช้บันไดจากชั้นวางของปีนขึ้นไป ทุบกระจก และส่งตัวเด็กขึ้นไปสู่ความปลอดภัยโดยมีทีมข้างนอกช่วย ความสุขุมที่เหลือเชื่อภายใต้ความเครียดที่คุกคามชีวิต', zh: '✅ 专业的顶峰。你很快找到了孩子。你记得在30英尺外看到一个天窗。你利用货架上的梯子够到天窗，打碎玻璃，在外部救援人员的协助下将孩子托举到安全地带。在危及生命的压力下表现出惊人的沉着。' }, stats: { competence: 50, ethics: 45, leadership: 40, innovation: 35 } }
        ]
    },

    {
        id: 'fir_011',
        text: {
            en: '🧪 The Laboratory Spill: A chemistry lab at the university has a"mixing error."A yellow cloud is forming. One professor is unconscious inside. The placard says"Water Reactive"and"Oxidizer."Your captain orders you to put out the small fire near the chemicals with water. What do you do?',
            th: '🧪 สารเคมีรั่วไหลในห้องแล็บ: ห้องแล็บเคมีที่มหาวิทยาลัยเกิด"ความผิดพลาดในการผสม"เมฆสีเหลืองกำลังก่อตัว ศาสตราจารย์คนหนึ่งหมดสติอยู่ข้างใน ป้ายระบุว่า"ไวต่อปฏิกิริยากับน้ำ"และ"สารออกซิไดซ์"หัวหน้าสั่งให้คุณดับไฟเล็กๆ ใกล้สารเคมีด้วยน้ำ คุณจะทำอย่างไร?',
            zh: '🧪 实验室泄漏：大学的一个化学实验室发生了“混合错误”。一团黄色的云雾正在形成。一名教授在里面昏迷不醒。标牌上写着“遇水反应”和“氧化剂”。你的队长命令你用水扑灭化学品附近的火。你会怎么做？'
        },
        options: [
            { id: 'A', text: { en: '🚫 Refuse and Explain:"Captain, that placard says Water Reactive. If I use water, we make a bomb. I recommend CO2 or Met-L-X powder."', th: '🚫 ปฏิเสธและอธิบาย:"หัวหน้าครับ ป้ายบอกว่าไวต่อปฏิกิริยากับน้ำ ถ้าผมใช้น้ำ เรากำลังสร้างระเบิด ผมแนะนำ CO2 หรือผง Met-L-X ครับ"', zh: '🚫 拒绝并解释：“队长，标牌上写着遇水反应。如果我用水，就是造炸弹。我建议使用二氧化碳或Met-L-X粉末。”' }, consequence: { en: '✅ Expert Command. The Captain realizes the mistake. You use the correct agent, save the professor, and prevent a massive explosion. You are recommended for a commendation. Chemistry knowledge is as important as a fire axe.', th: '✅ การสั่งการที่เชี่ยวชาญ หัวหน้าตระหนักถึงความผิดพลาด คุณใช้สารดับไฟที่ถูกต้อง ช่วยชีวิตศาสตราจารย์ และป้องกันระเบิดครั้งใหญ่ คุณได้รับคำแนะนำให้รับรางวัลเชิดชูเกียรติ ความรู้ทางเคมีสำคัญพอๆ กับขวานดับเพลิง', zh: '✅ 专家指挥。队长意识到错误。你使用了正确的药剂，救了教授，并防止了大爆炸。你被推荐嘉奖。化学知识和消防斧一样重要。' }, stats: { competence: 50, ethics: 40, leadership: 45, innovation: 25 } },
            { id: 'B', text: { en: '🛡️ Follow the Captain:"Yes, sir!"You open the nozzle and blast the yellow cloud with a 1.75 inch fog stream.', th: '🛡️ ทำตามหัวหน้า:"ครับผม!"คุณเปิดหัวฉีดและฉีดละอองน้ำหมอกขนาด 1.75 นิ้วใส่เมฆสีเหลือง', zh: '🛡️ 服从队长：“是，先生！”你打开水枪，用1.75英寸的喷雾流冲击黄色云雾。' }, consequence: { en: '😱 Chemical Reaction! The water hits the chemicals, creating a massive exothermic reaction. A fireball erupts, throwing you back 20 feet. You suffer 3rd degree burns. The lab is leveled. The Captain is demoted, but your career is over due to injury."Just following orders"is not a defense for poor tactics.', th: '😱 ปฏิกิริยาเคมี! น้ำปะทะสารเคมี สร้างปฏิกิริยาคายความร้อนมหาศาล ลูกไฟพุ่งเข้าใส่คุณจนคุณกระเด็นไป 20 ฟุต คุณถูกไฟลวกระดับ 3 ห้องแล็บพังราบ หัวหน้าถูกลดตำแหน่ง แต่อาชีพคุณจบลงเนื่องจากการบาดเจ็บ การ"แค่ทำตามคำสั่ง"ไม่ใช่ข้ออ้างสำหรับกลยุทธ์ที่แย่', zh: '😱 化学反应！水接触到化学品，产生了巨大的放热反应。火球喷发，将你击退20英尺。你遭受三级烧伤。实验室被夷为平地。队长被降职，但你的职业生涯因伤结束。“只是服从命令”不能成为战术错误的辩护。' }, stats: { competence: -40, ethics: 20, leadership: -30, innovation: 0 } },
            { id: 'C', text: { en: '🏃 Rescue First:"Forget the fire, I\'m grabbing the professor!"You run in without a line to drag the victim out.', th: '🏃 ช่วยชีวิตก่อน:"ลืมเรื่องไฟไปก่อน ผมจะไปคว้าตัวศาสตราจารย์!"คุณวิ่งเข้าไปโดยไม่มีสายฉีดน้ำเพื่อลากเหยื่อออกมา', zh: '🏃 营救优先：“管它什么火，我要去救教授！”你没带水线就冲进去拖出受害者。' }, consequence: { en: '⚖️ High Risk Win. You get the professor out, but the toxic smoke from the chemical fire enters your gear. You suffer minor chemical pneumonia. The professor lives. You are hailed as a hero but criticized by safety officers for"freelancing"without a line.', th: '⚖️ ชนะด้วยความเสี่ยงสูง คุณช่วยชีวิตศาสตราจารย์ออกมาได้ แต่ควันพิษจากไฟไหม้เคมีซึมเข้าชุดของคุณ คุณเจ็บป่วยด้วยโรคปอดอักเสบจากสารเคมีเล็กน้อย ศาสตราจารย์รอด คุณได้รับการเชิดชูเป็นฮีโร่แต่ถูกวิจารณ์จากเจ้าหน้าที่ความปลอดภัยเรื่อง"ฉายเดี่ยว"โดยไม่มีสายฉีดน้ำ', zh: '⚖️ 高风险获胜。你救出了教授，但化学火灾产生的有毒烟雾进入了你的装备。你患上了轻微的化学性肺炎。教授活了下来。你被誉为英雄，但因在没有水线的情况下“擅自行动”而受到安全官员的批评。' }, stats: { competence: 30, ethics: 40, leadership: 10, innovation: 10 } },
            { id: 'D', text: { en: '🚁 Call the Hazmat Team:"It\'s out of our league. Evacuate 3 blocks and wait for the specialist team."', th: 'D ขอกำลังหน่วย Hazmat:"มันเกินระดับเราแล้ว อพยพคนในรัศมี 3 บล็อกแล้วรอหน่วยเฉพาะทาง"', zh: '呼叫防化队：“这超出了我们的处理范围。疏散三个街区，等待专家小组。”' }, consequence: { en: '⚠️ Safety but Delay. The Hazmat team arrives in 25 minutes. By then, the professor has died from toxic inhalation and the fire has spread to the floor above. You followed standard safety rules, but your lack of specialized suppression knowledge cost a life today.', th: '⚠️ ปลอดภัยแต่ล่าช้า หน่วย Hazmat มาถึงใน 25 นาที เมื่อถึงตอนนั้น ศาสตราจารย์เสียชีวิตจากการสูดสารพิษและไฟลามไปชั้นบน คุณทำตามกฎความปลอดภัยมาตรฐาน แต่การขาดความรู้เรื่องสารดับไฟเฉพาะทางทำให้เสียชีวิตในวันนี้', zh: '⚠️ 安全但延误。防化队在25分钟后到达。到那时，教授已经死于有毒气体吸入，火势已经蔓延到上一层。你遵循了标准安全规则，但你由于缺乏专业灭火知识今天导致了一条生命的逝去。' }, stats: { competence: 20, ethics: 30, leadership: 20, innovation: 0 } }
        ]
    },

    {
        id: 'fir_012',
        text: {
            en: '🚁 The Smokejumper Choice: You are dropping into a remote forest fire. The wind shifts suddenly, and the"fire front"is heading toward a research station with 3 scientists. You have two choices: drop directly on the station to defend it (High risk), or drop on the"safe ridge"2 miles away and hike in (Low risk, late arrival).',
            th: '🚁 ทางเลือกของ Smokejumper: คุณกำลังกระโดดร่มลงไปในไฟป่าที่ห่างไกล ลมเปลี่ยนทิศทางกะทันหัน และ"หน้าแนวไฟ"กำลังพุ่งไปยังสถานีวิจัยที่มีนักวิทยาศาสตร์ 3 คน คุณมีสองทางเลือก: กระโดดลงที่สถานีโดยตรงเพื่อป้องกัน (ความเสี่ยงสูง) หรือกระโดดลงที่"สันเขาที่ปลอดภัย"ห่างออกไป 2 ไมล์แล้วเดินเท้าเข้าไป (ความเสี่ยงต่ำ มาถึงช้า)',
            zh: '🚁 空降消防员的选择：你正空降到偏远的森林火场。风向突然转变，火头正向着有3名科学家的研究站推进。你有两个选择：直接空降到该站进行保卫（高风险），或者空降到2英里外的“安全山脊”然后徒步进入（低风险，到达较晚）。'
        },
        options: [
            { id: 'A', text: { en: '🚀 High Risk Target:"Drop us on the station roof! We don\'t leave people behind!"You jump into the smoke.', th: '🚀 เป้าหมายความเสี่ยงสูง:"ปล่อยพวกเราบนหลังคาสถานี! เราไม่ทิ้งใครไว้ข้างหลัง!"คุณกระโดดเข้าหากลุ่มควัน', zh: '🚀 高风险目标：“把我们空降到站房房顶！我们不抛弃任何人！”你跳入烟雾中。' }, consequence: { en: '🔥 Desperate Defense. You land on the roof, but the heat is so intense your parachute melts. You are trapped with the scientists. You manage to clear a fire break around the shack with chainsaws just in time. You all survive, but your crew suffers severe smoke inhalation. You are a legend in the service.', th: '🔥 การป้องกันที่สิ้นหวัง คุณลงจอดบนหลังคา แต่ความร้อนรุนแรงมากจนร่มชูชีพของคุณละลาย คุณติดอยู่กับนักวิทยาศาสตร์ คุณจัดการเคลียร์แนวกันไฟรอบกระท่อมด้วยเลื่อยยนต์ได้ทันเวลา ทุกคนรอดชีวิต แต่ทีมของคุณสูดควันเข้าไปมาก คุณกลายเป็นตำนานในกองกำลัง', zh: '🔥 拼死保卫。你降落在屋顶上，但热度太高，你的降落伞融化了。你和科学家们被困在了一起。你及时用电锯在棚屋周围清理出了一条防火隔离带。你们都活了下来，但你的队员由于严重吸入烟雾。你成为了消防部门的传奇。' }, stats: { competence: 40, ethics: 50, leadership: 30, innovation: 20 } },
            { id: 'B', text: { en: '🛡️ Safe Ridge Drop:"We can\'t jump into 40ft flames. Drop on the ridge. We\'ll hike down and flank the fire."', th: '🛡️ ลงจอดที่สันเขาที่ปลอดภัย:"เราไม่สามารถโดดลงไปในเปลวไฟสูง 40 ฟุตได้ ปล่อยบนสันเขา เราจะเดินลงไปและอ้อมแนวไฟ"', zh: '🛡️ 安全山脊空降：“我们不能跳进40英尺高的火焰。空降到山脊。我们徒步下山并包抄火势。”' }, consequence: { en: '😔 Too Late. The hike takes 45 minutes through thick brush. By the time you arrive, the research station is ash. The scientists are gone. You followed the"Safe Jump"doctrine, but the loss of life haunts you. You wonder if you should have pushed harder.', th: '😔 สายเกินไป การเดินเท้าใช้เวลา 45 นาทีผ่านพุ่มไม้หนาทึบ เมื่อคุณไปถึง สถานีวิจัยกลายเป็นเถ้าถ่าน นักวิทยาศาสตร์เสียชีวิต คุณทำตามหลักการ"กระโดดปลอดภัย"แต่การสูญเสียชีวิตตามหลอนคุณ คุณสงสัยว่าคุณควรจะผลักดันให้มากกว่านี้ไหม', zh: '😔 太晚了。穿过茂密的灌木丛徒步花了45分钟。当你到达时，研究站已化为灰烬。科学家们遇难了。你遵循了“安全跳伞”准则，但生命的逝去令你久久难平。你自问是否本该更有进取心一些。' }, stats: { competence: 25, ethics: 10, leadership: 20, innovation: 0 } },
            { id: 'C', text: { en: '🚁 Request Slurry Drop:"Don\'t jump yet. Have the lead plane drop fire retardant on the station first to cool it down, then drop us."', th: '🚁 ขอการทิ้งสารดับไฟ:"อย่าเพิ่งโดด ให้เครื่องบินนำทิ้งสารหน่วงไฟบนสถานีก่อนเพื่อลดความร้อน แล้วค่อยปล่อยพวกเรา"', zh: '🚁 请求泥浆喷洒：“先别跳。让领航飞机先向工作站喷洒阻燃剂降温，然后再空降我们。”' }, consequence: { en: '✅ Strategic Brilliance. The slurry coats the station and knocks down the heat. You jump in 2 minutes later safely. You protect the station with minimal damage. This perfectly coordinated air-ground attack is used as a training case study later.', th: '✅ อัจฉริยะทางกลยุทธ์ สารทิ้งเคลือบสถานีและลดความร้อนลง คุณกระโดดร่มลงไปหลังจากนั้น 2 นาทีอย่างปลอดภัย คุณปกป้องสถานีโดยมีความเสียหายเพียงเล็กน้อย การโจมตีประสานงานทางอากาศ-ภาคพื้นดินที่สมบูรณ์แบบนี้ถูกนำไปใช้เป็นกรณีศึกษาในการฝึกอบรมภายหลัง', zh: '✅ 卓越的战略建议。泥浆覆盖了工作站并降低了热量。2分钟后你安全降落。你以最小的损失保护了工作站。这种完美的空地协同攻击后来被用作训练案例研究。' }, stats: { competence: 50, ethics: 35, leadership: 40, innovation: 50 } },
            { id: 'D', text: { en: '📻 Evacuation Guidance:"Radio the scientists. Tell them to head EAST to the river. We\'ll meet them there."', th: '📻 แนะนำการอพยพ:"วิทยุหานักวิทยาศาสตร์ บอกให้พวกเขามุ่งหน้าไปทางตะวันออกสู่แม่น้ำ เราจะไปเจอพวกเขาที่นั่น"', zh: '📻 疏散指导：“用无线电联系科学家。告诉他们向东去河边。我们在那里会合。”' }, consequence: { en: '💀 Bad Intel. You didn\'t realize the fire had already cut off the east path. The scientists run straight into a"wall of flame"following your orders. They perishes. You gave life-ending advice based on incomplete information. A crushing professional failure.', th: '💀 ข้อมูลผิดพลาด คุณไม่รู้ว่าไฟได้ตัดขาดเส้นทางตะวันออกไปแล้ว นักวิทยาศาสตร์วิ่งเข้าหา"กำแพงเปลวไฟ"โดยตรงตามคำสั่งของคุณ พวกเขาเสียชีวิต คุณให้คำแนะนำที่จบชีวิตคนเพียงเพราะข้อมูลไม่ครบถ้วน ความล้มเหลวทางวิชาชีพที่รุนแรง', zh: '💀 错误的情报。你没意识到大火已经切断了东边的道路。科学家们遵循你的命令，直接冲进了一堵“火焰墙”。他们丧生了。你根据不完整的信息给出了致命的建议。这是惨痛的专业失败。' }, stats: { competence: 10, ethics: 20, leadership: -30, innovation: 10 } }
        ]
    },

    {
        id: 'fir_013',
        text: {
            en: '🚨 The Ethical Split: You are a Lieutenant. Your best firefighter, a hero with 20 years experience, tests positive for opioids during a random drug screen. He tells you privately he’s been using them for back pain from a job injury."Don\'t report me, Lou. I have 2 years till pension. I\'m fine on duty."',
            th: '🚨 ทางเลือกทางจริยธรรม: คุณเป็นหมวด นักดับเพลิงที่ดีที่สุดของคุณ ฮีโร่ที่มีประสบการณ์ 20 ปี ถูกตรวจพบสารเซพติดประเภทโอปิออยด์ระหว่างการสุ่มตรวจ เขาบอกคุณเป็นการส่วนตัวว่าเขาใช้มันเพื่อบรรเทาอาการปวดหลังจากอาการบาดเจ็บจากการทำงาน"อย่ารายงานผมเลยหมวด ผมเหลืออีก 2 ปีจะเกษียณ ผมทำงานไหว"',
            zh: '🚨 伦理性抉择：你是一名中尉。你手下最优秀的消防员——一个有着20年经验的英雄，在随机药检中呈阿片类药物阳性。他私下告诉你，他因为工伤导致的背痛一直在服用这些药物。“别举报我，长官。我还有两年就领养老金了。我执勤时没问题。”'
        },
        options: [
            { id: 'A', text: { en: '🤐 Look the Other Way:"I didn\'t see the results. Just get clean. I\'ll vouch for you if anyone asks."', th: '🤐 ทำเป็นไม่เห็น:"ฉันไม่เห็นผลตรวจ แค่กลับมาเลิกให้ได้ ฉันจะรับรองให้ถ้ามีคนถาม"', zh: '🤐 视而不见：“我没看到结果。你赶紧戒掉。如果有人问起，我会为你打保票。”' }, consequence: { en: '😱 Fatal Mistake. Three months later, on a structure fire, he becomes disoriented due to the drugs and drops a patient while carrying them down a ladder. The patient suffers a spinal injury. The subsequent investigation finds your suppressed drug report. You are both fired and face criminal negligence charges.', th: '😱 ความผิดพลาดที่ร้ายแรง สามเดือนต่อมา ในเหตุไฟไหม้อาคาร เขาหลงสติเนื่องจากยาและทำผู้ป่วยหลุดมือขณะแบกลงบันได ผู้ป่วยบาดเจ็บที่ไขสันหลัง การสอบสวนตามมาพบรายงานยาที่คุณซ่อนไว้ คุณทั้งคู่ถูกไล่ออกและเผชิญข้อหาประมาทเลินเล่อทางอาญา', zh: '😱 致命错误。三个月后，在一次结构性火灾中，由于药物作用他迷失了方向，在从梯子上搬运病人时将其摔下。病人脊椎受损。随后的调查发现了你隐瞒的药检报告。你们都被解雇并面临过失指控。' }, stats: { competence: 10, ethics: -50, leadership: -40, innovation: 0 } },
            { id: 'B', text: { en: '⚖️ Mandatory Report:"I\'m sorry, brother. I can\'t have you on a rig like this. It\'s a safety risk to the whole team. I have to report it."', th: '⚖️ รายงานตามกฎ:"ฉันขอโทษ เพื่อน ฉันให้แกอยู่บนรถแบบนี้ไม่ได้ มันเสี่ยงต่อความปลอดภัยทั้งทีม ฉันต้องรายงาน"', zh: '⚖️ 强制报告：“对不起，兄弟。我不能让你在这个状态下出现。这对整个团队来说都是安全风险。我必须上报。”' }, consequence: { en: '✅ High Ethics, Hard Loss. He is placed on mandatory leave and loses his position. Eventually, he gets clean in rehab but his career is over. The crew is angry at you for"snitching"on a legend, but you prevented a future accident. Leadership is lonely.', th: '✅ จริยธรรมสูง การสูญเสียที่เจ็บปวด เขาถูกพักงานบังคับและเสียตำแหน่ง ในที่สุดเขาเลิกได้ในศูนย์บำบัดแต่อาชีพจบลง ทีมโกรธคุณที่"ฟ้อง"ตำนานของทีม แต่คุณป้องกันอุบัติเหตุในอนาคต ความเป็นผู้นำนั้นอ้างว้าง', zh: '✅ 高度道德，惨痛损失。他被强制休假并失去了职位。最终，他在戒毒所戒掉了药瘾，但职业生涯结束了。队员们因为你向传奇人物“告密”而对你感到愤怒，但你防止了未来的事故。领导者往往是孤独的。' }, stats: { competence: 30, ethics: 50, leadership: 45, innovation: 0 } },
            { id: 'C', text: { en: '🩹 The Rehab Path:"I\'m reporting this as a medical injury, not a disciplinary issue. We get you help, you go on light duty (desk work) until you\'re clean."', th: '🩹 เส้นทางกู้ชีพ:"ฉันจะรายงานเรื่องนี้ในฐานะอาการบาดเจ็บทางการแพทย์ ไม่ใช่เรื่องวินัย เราจะหาคนช่วยแก แกไปทำงานเบาๆ (งานเอกสาร) จนกว่าจะเลิกได้"', zh: '🩹 康复之路：“我将作为医疗伤情而非纪律问题上报。我们会帮你，你去做轻便工作（文案工作）直到你戒掉为止。”' }, consequence: { en: '✅ Redemption. You use the department\'s Employee Assistance Program (EAP). He gets medical treatment for his back and rehab for the addiction. A year later, he returns to the rig clean and functional. You saved a life AND a career by being compassionate but firm on safety.', th: '✅ การไถ่บาป คุณใช้โปรแกรมช่วยเหลือพนักงาน (EAP) ของกรม เขาได้รับการรักษาหลังและบำบัดการเสพติด หนึ่งปีต่อมาเขากลับมาทำงานที่รถอย่างสะอาดและทำงานได้ดี คุณช่วยชีวิตและอาชีพโดยมีความเมตตาแต่เด็ดขาดเรื่องความปลอดภัย', zh: '✅ 救赎。你利用了部门的员工援助计划（EAP）。他接受了背部医疗和戒毒治疗。一年后，他清醒且正常地回到了工作岗位。通过富有同情心且在安全问题上立场坚定，你挽救了一条生命和一段职业生涯。' }, stats: { competence: 40, ethics: 45, leadership: 50, innovation: 20 } },
            { id: 'D', text: { en: '😤 The Private Ultimatum:"You have 24 hours to check yourself into rehab voluntarily, or I report you to the Chief tomorrow morning."', th: '😤 คำขาดส่วนตัว:"แกว่ามี 24 ชั่วโมงจะไปเข้าศูนย์บำบัดด้วยตัวเอง หรือจะให้พี่รายงานหัวหน้าพรุ่งนี้เช้า"', zh: '😤 私下最后通牒：“你有24小时自愿去戒毒所，否则我明天早上就向局长举报你。”' }, consequence: { en: '⚖️ Neutral Ground. He checks himself in. The Chief still finds out eventually, but it looks better coming from him. You preserved the relationship but essentially allowed a drug-user to dictate the timeline of safety. A risky middle-ground.', th: '⚖️ ทางสายกลาง เขาไปบำบัดเอง หัวหน้าก็รู้อยู่ดีในที่สุดแต่มันดูดีกว่าถ้าเขาบอกเอง คุณรักษาความสัมพันธ์ไว้แต่ยอมได้รับอนุญาตให้ผู้ใช้ยาเป็นคนกำหนดเวลาความปลอดภัย ทางสายกลางที่เสี่ยง', zh: '⚖️ 中立立场。他自己去报到了。局长最终还是知道了，但由他自己说出来看起来好一些。你维护了关系，但实质上允许了一名药物使用者来决定安全的时间表。一个冒险的折中方案。' }, stats: { competence: 25, ethics: 20, leadership: 30, innovation: 0 } }
        ]
    },

    {
        id: 'fir_014',
        text: {
            en: '🏢 The High-Value Save: You are in a burning museum. You can save a world-famous painting worth $50 million, OR you can save a janitor you see trapped under some rubble but they are unconscious and it will take 5 minutes to lift the beam. The building is showing signs of imminent collapse.',
            th: '🏢 การช่วยชีวิตที่มีมูลค่าสูง: คุณอยู่ในพิพิธภัณฑ์ที่กำลังไฟไหม้ คุณสามารถช่วยภาพวาดชื่อดังระดับโลกมูลค่า 50 ล้านดอลลาร์ หรือจะช่วยพนักงานทำความสะอาดที่คุณเห็นติดอยู่ใต้ซากปรักหักพัง แต่เขาหมดสติและต้องใช้เวลา 5 นาทีในการยกคานออก ตัวอาคารแสดงสัญญาณว่าจะถล่มในไม่ช้า',
            zh: '🏢 高价值拯救：你在一家着火的博物馆里。你可以抢救一幅价值5000万美元的世界名画，或者去营救一名被困在瓦砾下的清洁工，但那人已失去知觉，且抬起横梁需要5分钟。建筑已显出即将坍塌的迹象。'
        },
        options: [
            { id: 'A', text: { en: '👤 Human Life First:"Forget the art, we\'re getting the person! Get the hydraulic jack now!"', th: '👤 ชีวิตคนต้องมาก่อน:"ลืมเรื่องศิลปะไป เราจะช่วยคน! เอาแม่แรงไฮดรอลิกมาเดี๋ยวนี้!"', zh: '👤 生命第一：“别管艺术品了，救人要紧！快拿液压千斤顶！”' }, consequence: { en: '✅ The True Hero. You spend the 5 minutes, free the janitor, and drag them out just as the gallery wing collapses. The painting is lost. The city is divided—some call you a hero, others mourning the cultural loss. But among firefighters, your reputation is gold. Life over property, always.', th: '✅ ฮีโร่ที่แท้จริง คุณใช้เวลา 5 นาที ปล่อยตัวพนักงาน และลากเขาออกมาทันเวลาที่ปีกแกลเลอรีถล่ม ภาพวาดสูญสลาย เมืองถูกแบ่งแยก—บางคนเรียกคุณว่าฮีโร่ บางคนเสียดายการสูญเสียทางวัฒนธรรม แต่ในหมู่นักดับเพลิง ชื่อเสียงคุณคือทองคำ ชีวิตสำคัญกว่าทรัพย์สินเสมอ', zh: '✅ 真正的英雄。你花了5分钟时间，救出了清洁工，并就在画廊侧翼坍塌前将他拖了出来。画作毁了。城市里议论纷纷——有人称你为英雄，有人哀悼文化损失。但在消防员中间，你的声誉是极好的。人命高于财产，一贯如此。' }, stats: { competence: 40, ethics: 50, leadership: 30, innovation: 0 } },
            { id: 'B', text: { en: '🎨 Save the Art:"That painting supports the city\'s entire tourism fund. The janitor looks far gone. Grab the canvas!"', th: '🎨 ช่วยศิลปะ:"ภาพวาดนั้นเลี้ยงงบการท่องเที่ยวของทั้งเมือง พนักงานคนนั้นดูไม่น่ารอดแล้ว คว้าเฟรมภาพซะ!"', zh: '🎨 拯救艺术品：“那幅画支撑着整个城市的旅游基金。清洁工看起来快不行了。拿上画布！”' }, consequence: { en: '💀 Moral Scandal. You save the painting. The janitor dies. The museum is grateful, but the internal investigation and public backlash are brutal."Firefighter values property over life."You are forced to resign. Your department\'s budget is slashed due to public anger.', th: '💀 เรื่องอื้อฉาวทางศีลธรรม คุณช่วยภาพวาด พนักงานเสียชีวิต พิพิธภัณฑ์ขอบคุณคุณ แต่การสอบสวนภายในและกระแสสังคมตีกลับนั้นรุนแรง"นักดับเพลิงให้ความสำคัญกับทรัพย์สินมากกว่าชีวิต"คุณถูกบังคับให้ลาออก งบประมาณกรมถูกตัดเนื่องจากความโกรธแค้นของประชาชน', zh: '💀 道德丑闻。你救了画，清洁工死了。博物馆很感激，但内部调查和公众抨击非常残酷。“消防员重财轻命”。你被迫辞职。你的部门预算也因公众愤怒而被削减。' }, stats: { competence: 20, ethics: -60, leadership: -40, innovation: 10 } },
            { id: 'C', text: { en: '🤝 Split the Difference:"You guys grab the painting, I\'m staying with the janitor! We save both!"', th: '🤝 แบ่งหน้าที่:"พวกเจ้าคว้าภาพวาดไป ฉันจะอยู่กับพนักงานเอง! เราจะช่วยทั้งคู่!"', zh: '🤝 折衷方案：“你们去拿画，我留下来救人！我们要两全其美！”' }, consequence: { en: '⚠️ Double Danger. By splitting your crew, you lose the manpower needed to lift the beam quickly. It takes 8 minutes now. The ceiling collapses. You are all injured. The janitor dies anyway. The painting is saved but at the cost of your crew being hospitalized for months. Poor leadership.', th: '⚠️ อันตรายสองเท่า การแยกทีมทำให้คุณเสียแรงงานที่จำเป็นในการยกคานให้เร็ว ตอนนี้ใช้เวลา 8 นาที เพดานถล่มลงมา คุณทุกคนบาดเจ็บ พนักงานเสียชีวิตอยู่ดี ภาพวาดรอดแต่แลกกับการที่ทีมต้องนอนโรงพยาบาลหลายเดือน ความเป็นผู้นำที่แย่', zh: '⚠️ 双倍危险。由于分散了人手，你失去了快速抬起横梁所需的劳动力。现在花了8分钟。天花板塌了。你们都受伤了。清洁工还是死了。画保住了，但代价是你的队员住院数月。糟糕的领导力。' }, stats: { competence: 15, ethics: 20, leadership: -20, innovation: 0 } },
            { id: 'D', text: { en: '🤖 Use Tech:"Is there a museum security robot? Can we use a forklift to prop the beam?"Try an innovative solution.', th: '🤖 ใช้เทคโนโลยี:"มีหุ่นยนต์รักษาความปลอดภัยของพิพิธภัณฑ์ไหม? เราใช้รถโฟล์คลิฟท์ค้ำคานได้ไหม?"ลองหาทางออกใหม่ๆ', zh: '🤖 利用技术：“有博物馆安保机器人吗？我们能用叉车支撑横梁吗？”尝试创新解决方案。' }, consequence: { en: '✅ Technical Genius. You find a heavy-duty floor scrubber and jam it under the beam to act as a wedge. It buys just enough time to drag the janitor out while your partner grabs the painting on the way to the exit. You saved both through quick thinking. Exceptional performance.', th: '✅ อัจฉริยะทางเทคนิค คุณหาเครื่องขัดพื้นหนักๆ แล้วเสียบเข้าไปใต้คานเพื่อทำเป็นลิ่ม มันซื้อเวลาได้พอที่จะลากพนักงานออกมาในขณะที่คู่หูของคุณคว้าภาพวาดระหว่างทางออก คุณช่วยได้ทั้งสองอย่างด้วยการคิดเร็ว ผลงานที่โดดเด่น', zh: '✅ 技术天才。你找到一台重型洗地机，将其塞到横梁下充当楔子。这争取到了足够的时间救出清洁工，同时你的搭档在去出口的路上拿走了画。你通过敏捷的思维保住了两方。表现出色。' }, stats: { competence: 50, ethics: 40, leadership: 40, innovation: 50 } }
        ]
    },

    {
        id: 'fir_015',
        text: {
            en: '🚗 The EV Battery Nightmare: An Electric Vehicle (EV) is on fire in a crowded underground parking garage. The smoke is thick and white (toxic). Traditional water application is having no effect—it’s in "thermal runaway." A nearby structural pillar is beginning to crack from the heat.',
            th: '🚗 ฝันร้ายของแบตเตอรี่ EV: รถยนต์ไฟฟ้า (EV) เกิดไฟไหม้ในที่จอดรถใต้ดินที่หนาแน่น ควันหนาทึบและเป็นสีขาว (พิษ) การฉีดน้ำแบบปกติไม่ได้ผล—มันอยู่ในสภาวะ "thermal runaway" คานรองรับอาคารที่อยู่ใกล้ๆ เริ่มมีรอยร้าวจากความร้อน',
            zh: '🚗 电动汽车电池噩梦：一辆电动汽车（EV）在拥挤的地下车库起火。烟雾又浓又白（有毒）。传统喷水毫无效果—它正处于“热失控”状态。附近的一根建筑支柱因高温开始出现裂缝。'
        },
        options: [
            { id: 'A', text: { en: '💦 Massive Water Deluge: "We need 1,000 gallons per minute! Drown the battery pack!"', th: '💦 ฉีดน้ำมหาศาล: "เราต้องการน้ำ 1,000 แกลลอนต่อนาที! จมแบตเตอรี่ให้ได้!"', zh: '💦 大规模注水：“我们需要每分钟1000加仑！淹没电池组！”' }, consequence: { en: '⚠️ Exhausting Battle. You use 10,000 gallons. The fire seems out, but then it reignites. EV fires require astronomical amounts of water for hours. You successfully cooled the pillar, but the garage is flooded and the car is still a hazard. High resource cost.', th: '⚠️ การต่อสู้ที่เหนื่อยล้า คุณใช้น้ำไป 10,000 แกลลอน ไฟดูเหมือนจะดับแต่แล้วก็ลุกขึ้นมาใหม่ ไฟไหม้ EV ต้องใช้น้ำมหาศาลต่อเนื่องหลายชั่วโมง คุณคูลโครงสร้างเสร็จแต่โรงรถน้ำท่วมและรถยังอันตรายอยู่ สิ้นเปลืองทรัพยากรสูง', zh: '⚠️ 疲劳战。你用了10,000加仑水。火似乎灭了，但接着又复燃了。电动汽车火灾需要数小时、天文数字般的水量。你成功冷却了支柱，但车库被淹了，车依然是个隐患。资源消耗巨大。' }, stats: { competence: 30, ethics: 20, leadership: 20, innovation: 0 } },
            { id: 'B', text: { en: '🛡️ Fire Blanket: "Forget the water. Smother it with a specialized EV fire blanket and defend the pillar."', th: '🛡️ ผ้าห่มทนไฟ: "ลืมเรื่องน้ำไป ใช้ผ้าห่มทนไฟเฉพาะสำหรับ EV คลุมมันไว้แล้วป้องกันคาน"', zh: '🛡️ 灭火毯：“别管水了。用专门的电动汽车灭火毯盖住它，并保卫支柱。”' }, consequence: { en: '✅ Tactical Excellence. The blanket contains the flames and toxic smoke, preventing the fire from spreading to nearby cars. You focus your hose on cooling the structural pillar. The fire continues under the blanket, but it is controlled. You saved the building.', th: '✅ ความเป็นเลิศทางยุทธวิธี ผ้าห่มกักเก็บเปลวไฟและควันพิษ ป้องกันไฟลามไปยังรถคันอื่น คุณโฟกัสการฉีดน้ำไปที่คานเพื่อลดความร้อน ไฟยังไหม้อยู่ใต้ผ้าห่มแต่ถูกควบคุมได้ คุณช่วยอาคารไว้ได้', zh: '✅ 卓越战术。灭火毯隔绝了火焰和有毒烟雾，防止火势蔓延到附近的车辆。你集中水带冷却建筑支柱。虽然毯子下的火仍在继续，但已得到控制。你保住了这栋建筑。' }, stats: { competence: 50, ethics: 40, leadership: 40, innovation: 50 } },
            { id: 'C', text: { en: '🚜 Drag it Out: "Hook it up! Drag the burning car into the street where it\'s safe!"', th: '🚜 ลากออกมา: "เกี่ยวรถ! ลากรถที่กำลังไหม้ออกไปที่ถนนตรงที่ปลอดภัยกว่านี้!"', zh: '拖出来：“钩住它！把着火的车拖到安全的街上！”' }, consequence: { en: '😱 Chaos. As you drag the car, the battery venting increases. It leaves a trail of fire across the garage floor, igniting three other vehicles. You are lucky you weren\'t engulfed. A high-risk move that backfired spectacularly.', th: '😱 ความวุ่นวาย! ขณะที่คุณลากรถ แบตเตอรี่พ่นไฟแรงขึ้น ทิ้งทางยาวของไฟไว้บนพื้นโรงรถ จนลามไปไหม้รถอีก 3 คัน โชคดีที่คุณไม่โดนไฟคลอก การตัดสินใจที่เสี่ยงและพลาดอย่างแรง', zh: '😱 混乱。当你拖车时，电池排气增加。它在车库地面上留下了一道火痕，引燃了另外三辆车。你没被吞噬真是万幸。这是一次惨遭失败的高风险举动。' }, stats: { competence: 10, ethics: 10, leadership: -20, innovation: 20 } },
            { id: 'D', text: { en: '💊 Let it Burn: "It\'s too dangerous. Evacuate the garage and let it burn out. Just protect the exposure."', th: 'D ปล่อยให้ไหม้: "มันอันตรายเกินไป อพยพคนออกจากโรงรถแล้วปล่อยให้มันไหม้จนหมด แค่ป้องกันรอบๆ พอ"', zh: '让它烧：“太危险了。疏散车库，让它烧光。只保护周边受影响区域。”' }, consequence: { en: '❌ Structural Failure. Without active cooling, the pillar reaches critical temperature. A section of the ceiling collapses. The economic damage to the building is massive. Sometimes you have to take the fight to the fire.', th: '❌ โครงสร้างพัง! หากไม่มีการระบายความร้อน คานจะถึงอุณหภูมิวิกฤต เพดานบางส่วนถล่มลงมา ความเสียหายทางเศรษฐกิจต่ออาคารมหาศาล บางครั้งคุณก็ต้องกล้าสู้กับไฟ', zh: '❌ 结构失效。由于没有积极冷却，支柱达到了临界温度。一部分天花板塌陷了。对建筑造成的经济损失巨大。有时你必须主动出击灭火。' }, stats: { competence: 20, ethics: 10, leadership: 10, innovation: 0 } }
        ]
    },

    {
        id: 'fir_016',
        text: {
            en: '🌳 The Wildland Encircled: Your crew is cutting a fireline on a ridge. A"blow-up"occurs below you. A wall of flame is racing uphill at 20 mph. The safety zone is 500 yards away, but the terrain is steep. You won\'t make it. The order is given:"Deploy Fire Shelters!"',
            th: '🌳 วงล้อมไฟป่า: ทีมของคุณกำลังตัดแนวกันไฟบนสันเขา เกิด"blow-up"ขึ้นด้านล่าง กำแพงเปลวไฟพุ่งขึ้นเขาด้วยความเร็ว 20 ไมล์ต่อชั่วโมง เขตปลอดภัยอยู่ห่างออกไป 500 หลา แต่พื้นที่มีความลาดชัน คุณไปไม่ถึงแน่ คำสั่งถูกประกาศ:"กางถุงยังชีพทนไฟ (Fire Shelters)!"',
            zh: '🌳 森林火灾被围：你的队员正在山脊上挖掘防火道。你下方发生了“爆发火”。一堵火墙正以每小时20英里的速度向山上蔓延。安全区在500码外，但地形陡峭。你赶不到了。命令下达：“部署防火毯（生命袋）！”'
        },
        options: [
            { id: 'A', text: { en: '🛡️ Proper Deployment:"Clear the ground to mineral soil! Get in and hold the flaps!"You focus on a perfect seal.', th: '🛡️ กางอย่างถูกวิธี:"ถางพื้นให้ถึงหน้าดิน! เข้าไปข้างในแล้วเหยียบขอบไว้!"คุณเน้นการปิดผนึกที่สมบูรณ์', zh: '🛡️ 正确部署：“清理地面直到露出无机土！进去并压住边缘！”你专注于完美的密封。' }, consequence: { en: '✅ Survival. The fire roars over you like a freight train. The heat is agonizing, but the shelter reflects 95% of the radiant heat. You survive with minor burns. You followed the"Last Resort"training perfectly. Terrifying, but effective.', th: '✅ รอดชีวิต ไฟคำรามข้ามตัวคุณไปเหมือนรถไฟบรรทุกสินค้า ความร้อนนั้นทรมานมาก แต่ถุงยังชีพสะท้อนความร้อนได้ 95% คุณรอดชีวิตโดยมีการถูกลวกเล็กน้อย คุณทำตามการฝึก"ทางเลือกสุดท้าย"ได้อย่างไร้ที่ติ น่ากลัวแต่ได้ผล', zh: '✅ 生还。大火像货运列车一样从你上方呼啸而过。热度令人痛苦，但防火毯反射了95%的热辐射。你仅受轻伤生还。你完美地执行了“最后手段”训练。虽然恐怖，但很有效。' }, stats: { competence: 50, ethics: 30, leadership: 30, innovation: 0 } },
            { id: 'B', text: { en: '🏃 Run for It:"I can beat it! Run to the rocky outcrop!"You ignore the shelter order and sprint.', th: '🏃 วิ่งหนี:"ฉันหนีทัน! วิ่งไปที่แนวคอดหิน!"คุณเพิกเฉยต่อคำสั่งกางถุงยังชีพและออกวิ่งสุดแรง', zh: '🏃 逃命：“我跑得赢！跑向那块岩石露头！”你忽视了部署防火毯的命令，奋力冲刺。' }, consequence: { en: '💀 Overtaken. Fire moves uphill faster than any human can run. You are caught in the open in the"active flame front."You don\'t survive. Never try to outrun a slope fire.', th: '💀 ถูกตามทัน ไฟพุ่งขึ้นเขาเร็วกว่าที่มนุษย์จะวิ่งได้ คุณถูกจับได้ในที่โล่งท่ามกลาง"หน้าแนวไฟ"คุณไม่รอด อย่าพยายามวิ่งแข่งกับไฟบนทางลาด', zh: '💀 被吞噬。火在山坡上传播的速度比任何人跑步的速度都快。你在开阔地被“活动火焰前锋”困住。你没能生还。绝不要试图跑赢坡火。' }, stats: { competence: -50, ethics: 10, leadership: -40, innovation: 0 } },
            { id: 'C', text: { en: '🔥 Counter-Burn:"I\'m lighting a backfire! Burn out the fuel around us before the main front hits!"', th: '🔥 จุดไฟต้าน:"ผมจะจุดไฟย้อน (backfire)! เผาเชื้อเพลิงรอบตัวเราก่อนที่แนวไฟหลักจะมาถึง!"', zh: '🔥 逆火对攻：“我要点燃逆火！在主火头到来之前烧掉我们周围的燃料！”' }, consequence: { en: '⚠️ High Stakes Gamble. The backfire works slightly, but the wind is too strong. It provides a small"black"area that makes your shelter deployment safer. You survive with no burns, but the Chief reprimands you for unauthorized backfiring in high winds.', th: '⚠️ การเดิมพันที่สูงมาก ไฟย้อนได้ผลเล็กน้อยแต่ลมแรงเกินไป มันช่วยสร้างพื้นที่"สีดำ"เล็กๆ ที่ทำให้การกางถุงยังชีพปลอดภัยขึ้น คุณรอดโดยไม่ถูกลวก แต่หัวหน้าตำหนิคุณที่จุดไฟย้อนโดยไม่ได้รับอนุญาตในขณะลมแรง', zh: '⚠️ 高风险豪赌。逆火起到了一定作用，但风太大了。它提供了一小块“焦土”区域，让你的防火毯部署更安全。你毫发无损地生还，但局长因你在大风中擅自点燃逆火而训诫了你。' }, stats: { competence: 30, ethics: 20, leadership: 40, innovation: 50 } },
            { id: 'D', text: { en: '🤝 Huddle Together:"Everyone into one spot! Two people per shelter to share space!"', th: '🤝 สุมหัวรวมกัน:"ทุกคนรวมกันที่จุดเดียว! สองคนต่อหนึ่งถุงเพื่อแชร์พื้นที่!"', zh: '🤝 蜷缩在一起：“大家聚成一堆！每两张防火毯合在一起分担空间！”' }, consequence: { en: '😱 Fatal Crowd. Fire shelters are designed for individuals. Two people in one shelter prevents a proper seal. The heat enters and suffocates both. A well-intentioned but deadly violation of safety physics.', th: '😱 การรวมกลุ่มที่ถึงแก่ชีวิต ถุงยังชีพทนไฟถูกออกแบบมาสำหรับรายบุคคล สองคนในหนึ่งถุงทำให้ปิดผนึกไม่สนิท ความร้อนเข้าไปข้างในและทำให้ทั้งคู่ขาดอากาศหายใจ เป็นการละเมิดฟิสิกส์ความปลอดภัยที่เจตนาดีแต่ถึงตาย', zh: '😱 致命集结。防火毯是为个人设计的。两人共用会导致无法完全密封。热气侵入导致两人窒息。这是一个出于好意但却致命的违反安全物理特性的行为。' }, stats: { competence: -10, ethics: 20, leadership: -20, innovation: -20 } }
        ]
    },

    {
        id: 'fir_017',
        text: {
            en: '🚑 The"Mass Cal"Triage: You arrive at a bus crash. 30 victims. You are the Triage Officer. You see: 1. A child screaming (minor cuts), 2. An elderly woman quiet, breathing fast (shock), 3. A man with a severed leg (heavy bleeding), 4. A teen not breathing (no pulse). You have 4 RED tags (Immediate). Who gets them?',
            th: '🚑 การคัดแยกผู้ป่วยเหตุใหญ่ (Mass Cal): คุณไปถึงเหตุรถบัสชน เหยื่อ 30 คน คุณเป็นเจ้าหน้าที่คัดแยก คุณเห็น: 1. เด็กกรีดร้อง (แผลเล็กน้อย), 2. หญิงชราเงียบ หายใจเร็ว (ช็อก), 3. ชายที่ขาขาด (เลือดออกมาก), 4. วัยรุ่นไม่หายใจ (ไม่มีชีพจร) คุณมีป้ายแดง 4 ใบ (ด่วนที่สุด) ใครจะได้ไป?',
            zh: '🚑 “群伤”分诊：你到达大巴车祸现场。有30名受害者。你是分诊官。你看到：1. 大声尖叫的孩子（轻微割伤）；2. 安静但呼吸急促的老年女性（休克）；3. 一名腿部断裂的男子（大面积出血）；4. 一名没有呼吸且无脉搏的青少年。你有4张红标（立即处理）。分给谁？'
        },
        options: [
            { id: 'A', text: { en: '🚑 Red Tag the Bleeder and Shock:"Woman and Leg injury are RED. Teen is BLACK (deceased). Child is GREEN."', th: '🚑 แปะป้ายแดงให้คนเลือดออกและช็อก:"หญิงชราและคนขาขาดคือสีแดง วัยรุ่นคือสีดำ (เสียชีวิต) เด็กคือสีเขียว"', zh: '🚑 给大出血和休克者贴红标：“女性和大腿受伤者为红色。青少年为黑色（死亡）。孩子为绿色。”' }, consequence: { en: '✅ Perfect Triage. In mass casualty, you don\'t perform CPR on pulses-less victims (Black tag). You save those who can be saved with immediate care. The child is noisy but stable (Green). You used resources correctly.', th: '✅ การคัดแยกที่สมบูรณ์แบบ ในเหตุที่มีผู้บาดเจ็บจำนวนมาก คุณจะไม่ทำ CPR กับเหยื่อที่ไม่มีชีพจร (ป้ายดำ) คุณช่วยคนที่ช่วยได้ด้วยการดูแลทันที เด็กส่งเสียงดังแต่คงที่ (สีเขียว) คุณใช้ทรัพยากรได้ถูกต้อง', zh: '✅ 完美分诊。在发生群体性伤亡时，你不对失去脉搏的受害者（黑标）进行心肺复苏。你拯救那些通过立即护理可以救活的人。孩子很吵但情况稳定（绿标）。你正确使用了资源。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 0 } },
            { id: 'B', text: { en: '👶 Rescue the Child First:"Children always first! Red tag the kid, she\'s terrified!"', th: '👶 ช่วยเด็กก่อน:"เด็กต้องมาก่อนเสมอ! แปะป้ายแดงให้เด็ก เธอขวัญเสียมาก!"', zh: '👶 优先救助孩子：“孩子永远第一位！给那孩子贴红标，她吓坏了！”' }, consequence: { en: '😔 Resource Mismanagement. The child had a scratch. While you comforted her, the woman in shock died. You allowed emotion to override triage protocols. In disasters, feelings can kill.', th: '😔 การจัดการทรัพยากรผิดพลาด เด็กมีแค่รอยขีดข่วน ในขณะที่คุณปลอบเธอ หญิงชราที่อยู่ในอาการช็อกเสียชีวิต คุณปล่อยให้อารมณ์อยู่เหนือขั้นตอนการคัดแยก ในเหตุภัยพิบัติ ความรู้สึกสามารถฆ่าคนได้', zh: '😔 资源管理不当。孩子只有擦伤。当你安慰她时，那名休克女性去世了。你让情绪凌驾于分诊规程之上。在灾难中，感情用事可能导致死亡。' }, stats: { competence: 10, ethics: 20, leadership: -20, innovation: 0 } },
            { id: 'C', text: { en: '💓 Try to Save Everyone:"Black tags are for the morgue! Start CPR on the teen! Red tag everyone else!"', th: '💓 พยายามช่วยทุกคน:"ป้ายดำมีไว้สำหรับห้องศพ! เริ่ม CPR ให้วัยรุ่น! คนอื่นแปะป้ายแดงให้หมด!"', zh: '💓 试图救活所有人：“黑标是留给太平间的！给那青少年做心肺复苏！给其他所有人贴红标！”' }, consequence: { en: '😱 Chaos and Death. By doing CPR on one person, you tied up two rescuers. The bleeder bled out. The woman in shock died. Total system collapse. By trying to save everyone, you saved almost no one.', th: '😱 ความวุ่นวายและความตาย การทำ CPR ให้คนคนเดียวทำให้คุณต้องใช้เจ้าหน้าที่สองคน คนที่เลือดออกก็เลือดหมดตัว หญิงชราที่ช็อกก็ตาย ระบบล่มโดยสิ้นเชิง การพยายามช่วยทุกคนทำให้คุณแทบจะไม่ช่วยใครได้เลย', zh: '😱 混乱与死亡。通过给一个人做心肺复苏，你占用了两名救援人员。大出血者流血而死。休克女性去世。系统彻底崩溃。通过试图拯救所有人，你几乎谁也没救成。' }, stats: { competence: -30, ethics: 20, leadership: -40, innovation: 10 } },
            { id: 'D', text: { en: '🚁 Call for Air-Vac:"I won\'t tag them yet. Request 5 helicopters immediately and let them decide."', th: '🚁 เรียกเฮลิคอปเตอร์พยาบาล:"ผมยังไม่แปะป้าย ขอเฮลิคอปเตอร์ 5 ลำทันทีแล้วให้เขารตัดสินใจเอง"', zh: '🚁 请求空中救援：“我先不贴标。立即请求5架直升机，由他们决定。”' }, consequence: { en: '⚠️ Delayed Action. Helicopters won\'t land until triage is complete and a landing zone is established. You wasted 5 minutes of"golden hour"time being indecisive. Patients are deteriorating.', th: '⚠️ การปฏิบัติที่ล่าช้า เฮลิคอปเตอร์จะไม่ลงจอดจนกว่าการคัดแยกจะเสร็จสิ้นและมีการจัดตั้งพื้นที่ลงจอด คุณเสียเวลา 5 นาทีทองไปกับการลังเลใจ ผู้ป่วยอาการแย่ลง', zh: '⚠️ 行动延误。在分诊完成并建立着陆区之前，直升机不会降落。你因为优柔寡断浪费了5分钟的“黄金一小时”。病人的情况正在恶化。' }, stats: { competence: 20, ethics: 20, leadership: 10, innovation: 0 } }
        ]
    },

    {
        id: 'fir_018',
        text: {
            en: '🏢 The Structural Breach: A car has driven into a brick corner store. The driver is still inside. You notice the main support beam for the second floor is resting on the roof of the car. If you move the car, the building might collapse on you. The driver is unconscious.',
            th: '🏢 การพังทลายของโครงสร้าง: รถพุ่งชนร้านสะดวกซื้อหัวมุมที่เป็นตึกอิฐ คนขับยังอยู่ข้างใน คุณสังเกตเห็นคานรองรับหลักของชั้นสองวางอยู่บนหลังคารถ ถ้าคุณย้ายรถ อาคารอาจถล่มใส่คุณ คนขับหมดสติ',
            zh: '🏢 结构性破坏：一辆车撞进了砖木结构的转角店。司机仍在车内。你注意到二楼的主支撑梁支撑在汽车车顶上。如果你移动汽车，建筑可能会坍塌在你身上。司机已由于受创处于昏迷状态。'
        },
        options: [
            { id: 'A', text: { en: '🏗️ Shore it Up:"Nobody touches that car! Get the Paratech struts and 4x4 cribbing. We support the beam first."', th: '🏗️ เสริมความแข็งแรง:"ห้ามใครแตะรถคันนั้น! เอาค้ำยัน Paratech และไม้หมอน 4x4 มา เราต้องหนุนคานให้ได้ก่อน"', zh: '🏗️ 支撑结构：“谁也别碰那台车！拿派力泰克支撑杆和4x4垫木来。我们先支撑横梁。”' }, consequence: { en: '✅ Professional Salvage. You stabilize the building first. It takes 15 minutes, but the driver is now safely extracted without the roof falling. You prevented a secondary collapse. Correct technical rescue protocol.', th: '✅ การกู้ภัยระดับมืออาชีพ คุณทำให้อาคารมั่นคงก่อน ใช้เวลา 15 นาที แต่คนขับถูกช่วยออกมาได้โดยที่หลังคาไม่ถล่ม คุณป้องกันการถล่มซ้ำซ้อน เป็นขั้นตอนการกู้ภัยทางเทคนิคที่ถูกต้อง', zh: '✅ 专业打捞。你先稳固了建筑。这花了15分钟，但现在司机被安全救出，屋顶没有塌陷。你防止了二次坍塌。正确的战术救援规程。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 10 } },
            { id: 'B', text: { en: '🏎️ Fast Pull:"Hook the winch to the car and pull it out fast! The driver is dying!"', th: '🏎️ ดึงออกอย่างรวดเร็ว:"เอาวินซ์เกี่ยวรถแล้วลากออกมาเร็ว! คนขับกำลังจะตาย!"', zh: '🏎️ 快速拖拽：“把绞盘钩在车上，快把它拉出来！司机快不行了！”' }, consequence: { en: '😱 Building Collapse. As soon as the car clears the threshold, the support beam drops. The second floor pancaked onto the first. You and the driver are buried. A catastrophic failure of situational awareness.', th: '😱 อาคารถล่ม ทันทีที่รถพ้นธรณีประตู คานรองรับก็ร่วงลงมา ชั้นสองถล่มทับชั้นแรก คุณและคนขับถูกฝัง ความล้มเหลวในการรับรู้สถานการณ์ที่หายนะ', zh: '😱 建筑坍塌。就在汽车离开门槛的一瞬间，支撑梁掉落了。二楼像馅饼一样砸在一楼。你和司机都被埋了。这是情境意识上的灾难性失败。' }, stats: { competence: -60, ethics: 10, leadership: -40, innovation: 0 } },
            { id: 'C', text: { en: '💉 Medical Entry:"I\'ll crawl into the backseat and start an IV and stabilize the neck while the team shores it up."', th: '💉 การช่วยเหลือทางการแพทย์:"ฉันจะคลานเข้าเบาะหลังเพื่อเปิดเส้น IV และดามคอในขณะที่ทีมกำลังค้ำยันอาคาร"', zh: '💉 医疗切入：“我要爬进后座进行静脉注射并固定脖子，同时队员们负责加固。”' }, consequence: { en: '⚖️ High Risk Bravery. You are working inside a"death trap."The building creaks several times. You get the medical care started, but you risked your life for a non-trapped medical stabilization. A gutsy move that your Chief might call"reckless."', th: '⚖️ ความกล้าหาญที่เสี่ยงสูง คุณกำลังทำงานอยู่ใน"กับดักมรดก"อาคารลั่นหลายครั้ง คุณเริ่มการรักษาได้ แต่คุณเสี่ยงชีวิตเพื่อการรักษาพยาบาลในที่ที่ไม่ควรอยู่ เป็นการกระทำที่กล้าหาญแต่หัวหน้าอาจเรียกว่า"มุทะลุ"', zh: '⚖️ 高风险英勇。你在一个“死亡陷阱”里工作。建筑发出几次吱吱声。你开始了医疗救护，但你冒着生命危险去处理一个并未被困的医疗稳定。这是一个大胆的举动，你的局长可能会称之为“鲁莽”。' }, stats: { competence: 30, ethics: 45, leadership: 20, innovation: 10 } },
            { id: 'D', text: { en: '🚁 Call for Crane:"Don\'t move. Request a heavy-lift tow crane to hold the beam from above."', th: '🚁 เรียกเครน:"ห้ามขยับ ขอรถเครนยกหนักมาถือคานไว้จากข้างบน"', zh: '🚁 请求吊车：“别动。请求重型拖车吊车从上方固定横梁。”' }, consequence: { en: '⚠️ Logistical Delay. A crane takes 90 minutes to arrive. The driver\'s condition is critical. While it\'s the"safest"option, it\'s not practical for a life-threat scene. You need to use the tools on your truck.', th: '⚠️ ความล่าช้าทางโลจิสติกส์ เครนใช้เวลา 90 นาทีกว่าจะมาถึง อาการของคนขับวิกฤต แม้มันจะเป็นทางเลือกที่"ปลอดภัยที่สุด"แต่มันไม่เหมาะกับสถานการณ์วิกฤตชีวิต คุณต้องใช้เครื่องมือที่มีบนรถ', zh: '⚠️ 物流延误。吊车需要90分钟才能到达。司机情况危急。虽然这是“最安全”的选择，但对于危及生命的场景来说并不切实际。你需要利用卡车上的工具。' }, stats: { competence: 20, ethics: 20, leadership: 10, innovation: 20 } }
        ]
    },

    {
        id: 'fir_019',
        text: {
            en: '🏫 The School Shooter Rescue: An active shooter event at a local high school. The police have the shooter"contained"in the gym, but there are 10 students bleeding in the North hallway. The area is"Warm"(not fully secured). Your captain asks for volunteers to go in with police to rescue.',
            th: '🏫 การช่วยชีวิตในเหตุกราดยิง: เกิดเหตุกราดยิงในโรงเรียนมัธยมท้องถิ่น ตำรวจ"กักตัว"มือปืนไว้ในโรงยิมแล้ว แต่มีนักเรียน 10 คนเลือดออกอยู่ในโถงทางเดินทิศเหนือ พื้นที่เป็นเขต"Warm"(ยังไม่ปลอดภัย 100%) หัวหน้าของคุณขออาสาสมัครเข้าไปพร้อมตำรวจเพื่อช่วยชีวิต',
            zh: '🏫 校园枪击案救援：当地高中发生连环枪击案。警方已将枪手“围困”在体育馆内，但在北走廊有10名学生正在大流血。该区域为“暖区”（尚未完全安全）。你的队长请求志愿者随警进入进行救援。'
        },
        options: [
            { id: 'A', text: { en: '🛡️ Join the RTF:"I\'ll go. Give me the vest and the trauma kit."You enter as a Rescue Task Force (RTF).', th: '🛡️ เข้าร่วม RTF:"ผมไปเอง เอาเสื้อคุมและอุปกรณ์กู้ชีพมา"คุณเข้าไปในฐานะ Rescue Task Force (RTF)', zh: '🛡️ 加入救援特遣队（RTF）：“我去。给我背心和急救包。”你作为救援特遣队（RTF）成员进入。' }, consequence: { en: '✅ Tactical Bravery. You enter with police protection. You apply 8 tourniquets in 4 minutes, saving lives that would have bled out. This is the modern standard for active shooters. You are a local hero.', th: '✅ ความกล้าหาญทางยุทธวิธี คุณเข้าไปโดยมีการคุ้มกันจากตำรวจ คุณใช้สายรัดห้ามเลือด 8 ชุดใน 4 นาที ช่วยชีวิตคนที่จะเลือดหมดตัว นี่คือมาตรฐานสมัยใหม่สำหรับเหตุกราดยิง คุณกลายเป็นฮีโร่ในท้องที่', zh: '✅ 战术英勇。你在警方的保护下进入。你在4分钟内使用了8个止血带，挽救了那些即将失血过多死亡的生命。这是现代处理活跃枪手案件的标准。你是当地的英雄。' }, stats: { competence: 50, ethics: 50, leadership: 40, innovation: 20 } },
            { id: 'B', text: { en: '🛑 Wait for"Cold":"I didn\'t sign up to get shot. I\'ll wait until police say the building is 100% safe."', th: '🛑 รอให้"Cold":"ฉันไม่ได้สมัครมาเพื่อถูกยิง ฉันจะรอจนกว่าตำรวจจะบอกว่าอาคารปลอดภัย 100%"', zh: '🛑 等待“冷区”：“我签名入职不是为了被枪击的。我要等到警察确认大楼100%安全为止。”' }, consequence: { en: '😔 Tragically Correct but Slow. You wait 20 minutes. By the time it\'s"Cold,"4 students have died of preventable blood loss. You are safe, but the professional guilt of not acting when lives were on the line is heavy.', th: '😔 ถูกต้องตามกฎแต่ช้า คุณรอ 20 นาที เมื่อถึงเวลาที่"Cold"นักเรียน 4 คนเสียชีวิตจากการเสียเลือดที่ป้องกันได้ คุณปลอดภัย แต่ความรู้สึกผิดในฐานะมืออาชีพที่ไม่ทำหน้าที่เมื่อชีวิตแขวนอยู่บนเส้นด้ายนั้นหนักหนา', zh: '😔 悲剧性的正确但缓慢。你等了20分钟。当区域变为“冷区”时，已有4名学生死于可预防的失血。你很安全，但因在生命关头未采取行动而产生的专业负罪感非常沉重。' }, stats: { competence: 20, ethics: 10, leadership: 10, innovation: 0 } },
            { id: 'C', text: { en: '🏃 Solo Charge:"They can\'t wait! I\'m grabbing the kit and running in now!"You jump the police line.', th: '🏃 ฉายเดี่ยว:"พวกเขารอไม่ได้แล้ว! ผมจะเกิ๊บชุดกู้ชีพแล้ววิ่งเข้าไปเดี๋ยวนี้!"คุณพุ่งข้ามแนวตำรวจไป', zh: '🏃 独自冲抵：“他们等不及了！我拿上急救包现在就冲进去！”你越过了警戒线。' }, consequence: { en: '😱 Near Death. You are mistaken for a second shooter by a SWAT team in the smoky hallway and nearly shot. You also find yourself in the shooter\'s line of sight. You are a liability, not a help. Never enter a gunfight without tactical protection.', th: '😱 เกือบตาย คุณถูกทีม SWAT เข้าใจผิดว่าเป็นมือปืนคนที่สองในโถงทางเดินที่มีควันและเกือบถูกยิง คุณยังพบว่าตัวเองอยู่ในแนวเล็งของมือปืนอีกด้วย คุณกลายเป็นภาระ ไม่ใช่คนช่วย อย่าเข้าสู่พื้นที่ต่อสู้ด้วยอาวุธโดยไม่มีการป้องกันทางยุทธวิธี', zh: '😱 险些丧命。你在烟雾弥漫的走廊里被特警队误认为是第二名枪手，险些被击毙。你也发现自己处于枪手的视线范围内。你是个累赘，而不是助手。绝不要在没有战术保护的情况下进入枪战区域。' }, stats: { competence: 10, ethics: 40, leadership: -30, innovation: 10 } },
            { id: 'D', text: { en: '📢 Remote Triage:"Use the school intercom to tell students how to make their own tourniquets!"', th: '📢 คัดแยกทางไกล:"ใช้เครื่องขยายเสียงโรงเรียนบอกนักเรียนถึงวิธีทำสายรัดห้ามเลือดด้วยตัวเอง!"', zh: '📢 远程分诊：“通过学校广播系统告诉学生们如何制作临时止血带！”' }, consequence: { en: '✨ Innovative Thinking. Some students follow the instructions and slow their bleeding until help arrives. It\'s not a substitute for entry, but it saved two lives from 100 yards away. Good use of available technology.', th: '✨ ความคิดสร้างสรรค์ นักเรียนบางคนทำตามคำแนะนำและช่วยลดการเสียเลือดจนกว่าความช่วยเหลือจะมาถึง มันไม่ใช่การทดแทนการเข้าไปช่วย แต่ช่วยได้สองชีวิตจากระยะ 100 หลา การใช้เทคโนโลยีที่มีให้เกิดประโยชน์', zh: '✨ 创新思维。一些学生遵循了指示并减缓了出血，直到救援到达。这不能替代进入救援，但在100码外挽救了两条生命。很好地利用了现有技术。' }, stats: { competence: 30, ethics: 30, leadership: 30, innovation: 50 } }
        ]
    },

    {
        id: 'fir_020',
        text: {
            en: '🔥 The Kitchen Fire Flashover: You are searching the 2nd floor of a house. The kitchen is on the 1st floor. Suddenly, the temperature spikes. The black smoke overhead begins to"roll"and glow blue (Ghosting). You know a flashover is seconds away. You haven\'t found the occupant yet.',
            th: '🔥 ครัวเกิด Flashover: คุณกำลังค้นหาชั้น 2 ของบ้าน ห้องครัวอยู่ชั้น 1 ทันใดนั้น อุณหภูมิพุ่งสูงขึ้น ควันดำเหนือหัวเริ่ม"ม้วน"และเปลี่ยนเป็นสีฟ้า (Ghosting) คุณรู้ว่า flashover จะเกิดขึ้นในไม่กี่วินาที คุณยังไม่พบผู้อยู่อาศัย',
            zh: '🔥 厨房火灾轰燃：你正在搜索一栋房子的二楼。厨房在一楼。突然，温度急剧上升。头顶上的浓烟开始“翻滚”并发出蓝光（鬼火）。你知道轰燃就在几秒钟后。你还没有找到住户。'
        },
        options: [
            { id: 'A', text: { en: '🏃 Jump for Life:"OUT! NOW!"You smash a window, bail out onto the porch roof, and jump to the ground.', th: '🏃 โดดหนีตาย:"ออกไป! เดี๋ยวนี้!"คุณทุบหน้าต่าง กระโดดออกไปยังหลังคาเฉลียง และกระโดดลงพื้น', zh: '🏃 跳窗求生：“撤！快！”你击碎窗户，跳到门廊屋顶上，然后跳到地面。' }, consequence: { en: '✅ Survival. As your feet hit the grass, the windows of the 2nd floor blow out with a roar of fire. You would have been incinerated. It\'s a terrifying defeat, but a live firefighter can fight another day.', th: '✅ รอดชีวิต ทันทีที่เท้าคุณแตะหญ้า หน้าต่างชั้น 2 ก็ระเบิดออกมาพร้อมกับเปลวไฟที่คำราม คุณคงถูกเผาไปแล้ว เป็นความพ่ายแพ้ที่น่ากลัว แต่นักดับเพลิงที่รอดชีวิตสามารถสู้ต่อได้ในวันหน้า', zh: '✅ 生还。当你的脚接触到草地时，二楼的窗户随着大火的呼啸喷涌而出。如果你还在里面，早被烧成灰了。这虽然是一次恐怖的挫败，但活着的消防员才能在将来继续战斗。' }, stats: { competence: 45, ethics: 20, leadership: 30, innovation: 0 } },
            { id: 'B', text: { en: '🛡️ Low and Slow:"Get on the floor! Face the fire and open the nozzle to the ceiling to cool the gases!"Stay and fight.', th: '🛡️ หมอบต่ำและช้า:"หมอบลงกับพื้น! หันหน้าเข้าหาไฟแล้วฉีดน้ำใส่เพดานเพื่อลดอุณหภูมิ!"อยู่และสู้ต่อ', zh: '🛡️ 低姿势缓慢行进：“趴在地上！面对火场，向天花板喷水以冷却烟气！”留下战斗。' }, consequence: { en: '😱 Severe Injury. You cool the ceiling, but you are in the 2nd floor. The flashover happened on the 1st floor, meaning the stairs are now a chimney. You are trapped. You suffer severe steam burns and have to be rescued by the ladder crew. You ignored the physics of fire flow.', th: '😱 บาดเจ็บสาหัส คุณระบายความร้อนที่เพดาน แต่คุณอยู่ชั้น 2 flashover เกิดขึ้นที่ชั้น 1 หมายความว่าบันไดกลายเป็นปล่องไฟไปแล้ว คุณถูกขัง คุณถูกไอน้ำลวกอย่างรุนแรงและต้องให้ทีมบันไดมาช่วย คุณละเลยฟิสิกส์ของการไหลของไฟ', zh: '😱 重伤。你冷却了天花板，但你在二楼。轰燃发生在一楼，这意味着楼梯现在变成了一个烟囱。你被困住了。你遭受了严重的蒸汽烫伤，不得不由云梯组营救。你忽略了火流物理学。' }, stats: { competence: 15, ethics: 10, leadership: -20, innovation: 0 } },
            { id: 'C', text: { en: '🚪 Compartmentalize:"Find a bedroom and CLOSE THE DOOR. Shelter in place until the fire is knocked down below!"', th: '🚪 แบ่งส่วน:"หาห้องนอนแล้วปิดประตู! หลบอยู่ในนั้นจนกว่าไฟข้างล่างจะถูกดับ!"', zh: '🚪 隔绝空间：“找个卧室把门关上。在楼下火势扑灭前原地避难！”' }, consequence: { en: '✅ Tactical Brilliance."Close Before You Doze"works for firefighters too. The closed door buys you 10 minutes from the heat. You find the victim in the room with you. You both wait at the window for the ladder. Calm under pressure saved two lives.', th: '✅ อัจฉริยะทางยุทธวิธี"ปิดประตูก่อนนอน (หรือสู้)"ใช้ได้กับนักดับเพลิงด้วย ประตูที่ปิดช่วยซื้อเวลาให้คุณ 10 นาทีจากความร้อน คุณพบเหยื่อในห้องเดียวกับคุณ ทั้งคู่รอที่หน้าต่างให้ทีมบันไดมาช่วย ความนิ่งภายใต้ความกดดันช่วยได้สองชีวิต', zh: '✅ 战术上的卓越建议。“睡觉（或战斗）前关门”对消防员也适用。关上的门为你争取了10分钟避热时间。你在房间里找到了受害者。你们都在窗边等待云梯。压力下的沉着挽救了两条生命。' }, stats: { competence: 50, ethics: 40, leadership: 40, innovation: 45 } },
            { id: 'D', text: { en: '💨 Floor Hole Exit:"The stairs are gone! Cut a hole in the floor to the garage and drop down!"', th: '💨 ออกทางรพื้น:"บันไดไปหมดแล้ว! เจาะรูที่พื้นลงไปยังอู่รถแล้วหย่อนตัวลงไป!"', zh: '💨 地震逃生：“楼梯没了！在在地板上挖个洞通向车库，然后跳下去！”' }, consequence: { en: '⚠️ Desperate Measure. You cut through with your axe. You drop 10 feet into a garage filled with smoke. You sprain your ankle and lose your helmet. You got out, but it was a messy, high-risk escape that almost broke your legs.', th: '⚠️ มาตรการที่สิ้นหวัง คุณใช้ขวานจามลงไป คุณร่วงลงไป 10 ฟุตในอู่รถที่เต็มไปด้วยควัน ข้อเท้าพลิกและหมวกหลุด คุณหนีออกมาได้แต่มันเป็นการหนีที่วุ่นวายและเสี่ยงสูงที่เกือบทำให้ขาคุณหัก', zh: '⚠️ 绝望之举。你用斧头砍透地板。你坠落10英尺掉进一个充满烟雾的车库。你扭伤了脚踝并弄丢了头盔。你逃了出来，但这是一次混乱且高风险的逃生，差点摔断了腿。' }, stats: { competence: 20, ethics: 20, leadership: 10, innovation: 30 } }
        ]
    },

    {
        id: 'fir_024',
        text: {
            en: '🌪️ The Tornado Aftermath: A tornado has leveled a trailer park. You are searching the debris. You hear a baby crying from under a collapsed kitchen floor, but the smell of natural gas is overwhelming. Your gas meter is screaming "EXPLOSIVE ATMOSPHERE." There is a spark clicking from a broken stove nearby.',
            th: '🌪️ หลังพายุทอร์นาโด: พายุทอร์นาโดพัดถล่มสวนรถบ้านจนราบเป็นหน้ากลอง คุณกำลังค้นหาตามซากปรักหักพัง คุณได้ยินเสียงทารกร้องไห้มาจากใต้พื้นห้องครัวที่ถล่มลงมา แต่กลิ่นก๊าซธรรมชาติรุนแรงมาก เครื่องตรวจจับก๊าซของคุณร้องเตือน "บรรยากาศที่ระเบิดได้" มีเสียงสปาร์คดังคลิกๆ จากเตาที่พังอยู่ใกล้ๆ',
            zh: '🌪️ 龙卷风过后：龙卷风夷平了一处房车公园。你正在废墟中搜救。你听到倒塌的厨房地板下传出婴儿的哭声，但天然气的味道令人窒息。你的气体探测器尖叫着提示“爆炸性环境”。附近一台损坏的炉具正发出火花点击声。'
        },
        options: [
            { id: 'A', text: { en: '👶 Immediate Grab: "I don\'t care about the gas! I\'m getting that baby now!" You dive into the hole.', th: '👶 ช่วยทันที: "ฉันไม่สนเรื่องก๊าซ! ฉันจะช่วยเด็กนั่นเดี๋ยวนี้!" คุณกระโดดลงไปในรู', zh: '👶 立即营救：“我不管什么煤气！我现在就要救那个婴儿！”你跳进洞里。' }, consequence: { en: '😱 Explosion. The spark ignites the gas while you are in the hole. You and the baby are both killed instantly. In a gas leak, "Source Control" or "Ventilation" must come before entry.', th: '😱 ระเบิด! สปาร์คจุดติดก๊าซในขณะที่คุณอยู่ในรู คุณและทารกเสียชีวิตทันที ในเหตุที่มีก๊าซรั่ว การ "ควบคุมต้นตอ" หรือ "การระบายอากาศ" ต้องมาก่อนการเข้าปฏิบัติงาน', zh: '😱 爆炸。当你在洞里时，火花引燃了气体。你和婴儿都当场丧生。在煤气泄漏的情况下，进入前必须先进行“气源控制”或“通风”。' }, stats: { competence: 10, ethics: 40, leadership: -20, innovation: 0 } },
            { id: 'B', text: { en: '🛑 Master Shut-off First: "Stop! Secure the main gas valve for the park first! And hit that stove with a CO2 extinguisher!"', th: '🛑 ปิดวาล์วหลักก่อน: "หยุด! ไปปิดวาล์วก๊าซหลักของโครงการก่อน! แล้วฉีดถัง CO2 ใส่เตานั่นซะ!"', zh: '🛑 先关闭总阀：“停！先关掉公园的燃气总阀！用二氧化碳灭火器对着那台炉子喷！”' }, consequence: { en: '✅ Controlled Rescue. You eliminate the ignition source and the fuel. The gas levels drop. You rescue the baby safely after a 2-minute delay. The baby survives. Disciplined bravery saves more lives than reckless impulse.', th: '✅ การช่วยชีวิตที่ควบคุมได้ คุณกำจัดแหล่งจุดติดไฟและเชื้อเพลิง ระดับก๊าซลดลง คุณช่วยเด็กได้อย่างปลอดภัยหลังจากล่าช้าไป 2 นาที เด็กทารกรอดชีวิต ความกล้าหาญที่มีวินัยช่วยชีวิตคนได้มากกว่าแรงผลักดันที่บ้าระห่ำ', zh: '✅ 受控救援。你消除了火源和燃料。煤气浓度下降。延误两分钟后，你安全救出了婴儿。婴儿幸存。有纪律的勇敢比鲁莽的冲动能救更多的人。' }, stats: { competence: 50, ethics: 35, leadership: 40, innovation: 20 } },
            { id: 'C', text: { en: '💨 Positive Pressure Ventilation: "Blow that gas out! Get the PPV fan here now and clear a path!"', th: '💨 ระบายอากาศแรงดันบวก: "เป่าก๊าซนั่นออกไป! เอาพัดลม PPV มาที่นี่เดี๋ยวนี้และเปิดทาง!"', zh: '💨 正压通风：“把煤气吹走！快把正压通风机（PPV）拿来，清出通道！”' }, consequence: { en: '⚠️ Risky Success. The fan clears the gas, but the airflow almost makes the stove spark into a flame. You get the baby out, but the incident commander chews you out for "adding oxygen to a fuel-rich environment" before shutting off the source.', th: '⚠️ สำเร็จอย่างเสี่ยง พัดลมเป่าก๊าซออกไปได้ แต่แรงลมเกือบทำให้สปาร์คที่เตากลายเป็นเปลวไฟ คุณช่วยเด็กออกมาได้ แต่ผู้บัญชาการเหตุการณ์ตำหนิคุณที่ "เติมออกซิเจนเข้าไปในสภาพแวดล้อมที่มีเชื้อเพลิงหนาแน่น" ก่อนที่จะปิดต้นตอ', zh: '⚠️ 冒险成功。风机排除了气体，但气流几乎让炉子的火花变成了火焰。你救出了婴儿，但现场指挥官却因为你在关闭气源前“向充满燃料的环境补充氧气”而痛斥你。' }, stats: { competence: 30, ethics: 30, leadership: 20, innovation: 40 } }
        ]
    },

    {
        id: 'fir_025',
        text: {
            en: '🚆 The Subway Flare-up: A subway train is on fire inside a tunnel. Visibility is zero. 500 passengers are trapped on the train. The third rail (high voltage) might still be live. Your radio is failing due to the depth. Your team is split.',
            th: '🚆 ไฟไหม้รถไฟใต้ดิน: รถไฟใต้ดินเกิดไฟไหม้ในอุโมงค์ ทัศนวิสัยเป็นศูนย์ ผู้โดยสาร 500 คนติดอยู่ในรถไฟ รางที่สาม (ไฟฟ้าแรงสูง) อาจยังมีไฟอยู่ วิทยุของคุณใช้การไม่ได้เพราะความลึก ทีมของคุณแยกออกจากกัน',
            zh: '🚆 地铁起火：隧道内的一列地铁着火了。能见度为零。500名乘客被困在车上。第三轨（高压电）可能依然带电。由于深度原因，你的无线电失灵了。你的团队分散了。'
        },
        options: [
            { id: 'A', text: { en: '🛤️ Power Confirmation First: "Stay off the tracks! I need absolute confirmation from Metro that power is KILLED before we advance!"', th: '🛤️ ยืนยันการตัดไฟก่อน: "ห้ามลงไปบนราง! ผมต้องการการยืนยันจากเมโทรว่าตัดไฟแน่นอนแล้ว 100% ก่อนเราจะไปต่อ!"', zh: '🛤️ 先确认电源：“别下轨道！在前进前，我需要地铁公司绝对确认电源已切断！”' }, consequence: { en: '✅ Professional Discipline. You wait 3 minutes for confirmation. It turns out the automatic shutoff failed. If you had stepped down, your whole team would be dead. You eventually lead the evacuation safely. System safety protocols exist for a reason.', th: '✅ วินัยความเป็นมืออาชีพ คุณรอ 3 นาทีเพื่อการยืนยัน ปรากฏว่าระบบตัดไฟอัตโนมัติล้มเหลว ถ้าคุณก้าวลงไป ทั้งทีมคงตายหมด ในที่สุดคุณก็นำการอพยพได้อย่างปลอดภัย กฎความปลอดภัยมีไว้เพื่อเหตุผลบางอย่างเสมอ', zh: '✅ 专业纪律。你等待了3分钟以获取确认。事实证明自动断电失败了。如果你走下去，你的整个团队都会没命。最终你安全地领导了疏散。系统安全规程的存在是有原因的。' }, stats: { competence: 50, ethics: 40, leadership: 50, innovation: 0 } },
            { id: 'B', text: { en: '🏃 Rescue Instinct: "People are suffocating! We use the wooden ladders to bridge the tracks and get them out now!"', th: '🏃 สัญชาตญาณกู้ภัย: "คนกำลังจะขาดใจตาย! เราใช้บันไดไม้พาดข้ามรางและช่วยพวกเขาออกมาเดี๋ยวนี้!"', zh: '🏃 营救本能：“人们快窒息了！我们用木梯跨过轨道，现在就把他们救出来！”' }, consequence: { en: '⚠️ Narrow Escape. The wooden ladder provides some insulation, but a firefighter slips and touches the rail, receiving a non-fatal but agonizing shock. You saved many, but injured your own. A high-cost victory.', th: '⚠️ รอดมาได้อย่างหวุดหวิด บันไดไมช่วยฉนวนได้บ้าง แต่นักดับเพลิงคนหนึ่งลื่นไปโดนราง ทำให้ถูกไฟช็อตอย่างรุนแรงแต่ไม่ถึงแก่ชีวิต คุณช่วยคนได้มากแต่ทีมบาดเจ็บ เป็นชัยชนะที่แลกมาด้วยราคาแพง', zh: '⚠️ 险些脱险。木梯提供了一定的绝缘作用，但一名消防员滑倒并触碰了轨道，遭到了虽不致命但极其痛苦的电击。你救了很多人，但伤了自己的队员。代价高昂的胜利。' }, stats: { competence: 30, ethics: 30, leadership: 30, innovation: 40 } },
            { id: 'C', text: { en: '📻 Runner Tactic: "We can\'t use radio. I\'ll act as a human messenger between the train and the tunnel entrance. Keep the team together!"', th: '📻 กลยุทธ์คนส่งสาร: "เราใช้วิทยุไม่ได้ ผมจะทำหน้าที่เป็นคนส่งสารเดินเท้าไประหว่างรถไฟและทางเข้าอุโมงค์ รวมกลุ่มกันไว้!"', zh: 'C 通讯员战术：“我们无法使用无线电。我将担任地铁和隧道口之间的人力通讯员。保持团队在一起！”' }, consequence: { en: '✅ Effective Low-Tech. By maintaining a human chain of communication, you coordinate the rescue without electronics. It’s slow, but no one gets lost in the smoke. You are praised for adapting to equipment failure.', th: '✅ เทคโนโลยีต่ำแต่ได้ผล ด้วยการรักษาการสื่อสารแบบห่วงโซ่มนุษย์ คุณสามารถประสานการกู้ภัยได้โดยไม่ต้องใช้เครื่องมืออิเล็กทรอนิกส์ มันช้าแต่ไม่มีใครหลงในควัน คุณได้รับคำชมที่ปรับตัวเข้ากับอุปกรณ์ที่ล้มเหลวได้ดี', zh: '✅ 有效的低技术方案。通过建立人力通信链，你在没有电子设备的情况下协调了救援。虽然慢，但没人在烟雾中走失。你因在设备故障时的应变能力而受到表扬。' }, stats: { competence: 40, ethics: 30, leadership: 40, innovation: 30 } }
        ]
    },

    {
        id: 'fir_026',
        text: {
            en: '🏥 The Hospital Backup Failure: A massive storm caused a power outage at the city hospital. The redundant generators failed. 15 infants in the NICU are on ventilators that have 20 minutes of battery life. Your station is the only place with portable oxygen and power packs.',
            th: '🏥 ระบบสำรองโรงพยาบาลล้มเหลว: พายุรุนแรงทำให้ไฟดับที่โรงพยาบาลประจำเมือง เครื่องปั่นไฟสำรองใช้งานไม่ได้ ทารก 15 คนในแผนก NICU ต้องใช้เครื่องช่วยหายใจซึ่งมีแบตเตอรี่เหลือ 20 นาที สถานีของคุณเป็นที่เดียวที่มีออกซิเจนพกพาและชุดสำรองไฟ',
            zh: '🏥 医院后备系统故障：一场特大风暴导致市医院停电。冗余发电机失灵。新生儿重症监护室（NICU）的15名婴儿靠呼吸机维持生命，而呼吸机的电池只能维持20分钟。你们消防站是唯一拥有便携式氧气和电源包的地方。'
        },
        options: [
            { id: 'A', text: { en: '🚚 All-In Delivery: "Load every portable generator and O2 tank into the trucks. We drive through the floodwaters now!"', th: '🚚 ขนไปให้หมด: "ขนเครื่องปั่นไฟพกพาและถังออกซิเจนทุกใบขึ้นรถ เราจะขับลุยน้ำท่วมไปเดี๋ยวนี้!"', zh: '🚚 全力运送：“把所有便携式发电机和氧气瓶装上车。我们现在就开车冲过洪区！”' }, consequence: { en: '✅ Miracle on Main Street. You push the engines through 3 feet of water. You arrive with 5 minutes to spare. You and your crew manually bag the babies until power is restored. You are national heroes. "Firefighters" means more than just fire.', th: '✅ ปาฏิหาริย์บนถนนหลัก คุณขับรถดับเพลิงลุยน้ำลึก 3 ฟุตไปได้ คุณไปถึงก่อนเวลา 5 นาที คุณและทีมช่วยกันบีบลูกยางมือช่วยหายใจให้ทารกจนกว่าไฟจะมา คุณกลายเป็นฮีโร่ระดับประเทศ "นักดับเพลิง" เป็นอะไรได้มากกว่าแค่เรื่องไฟ', zh: '✅ 大街上的奇迹。你开着消防车冲过了3英尺深的水。你在最后5分钟赶到。你和你的队员手动为婴儿进行人工呼吸，直到电力恢复。你们是国家英雄。“消防员”的含义远不止灭火。' }, stats: { competence: 50, ethics: 50, leadership: 50, innovation: 20 } },
            { id: 'B', text: { en: '🚁 Request Air Support: "We can\'t make it by road. Call the National Guard for a heavy-lift chopper to move our gear."', th: '🚁 ขอสนับสนุนทางอากาศ: "เราไปทางบกไม่ได้ โทรหา National Guard ขอเฮลิคอปเตอร์ยกของหนักมาย้ายอุปกรณ์เราเดี๋ยวนี้"', zh: '🚁 请求空中支援：“我们走陆路赶不及。打电话给国民警卫队，请求重型直升机运送我们的装备。”' }, consequence: { en: '😔 Red Tape Death. The authorization takes 40 minutes. By the time the chopper arrives at your station, the hospital reports the batteries have died and the infants didn\'t make it. Bureaucracy killed them.', th: '😔 ความตายจากระเบียบราชการ การอนุมัติใช้เวลา 40 นาที กว่าเฮลิคอปเตอร์จะมาถึงสถานีของคุณ โรงพยาบาลรายงานว่าแบตเตอรี่หมดและทารกไม่รอดชีวิต ระบบราชการฆ่าพวกเขา', zh: '😔 官僚主义导致的死亡。审批花了40分钟。等直升机到达你的站点时，医院报告电池已经耗尽，婴儿们没能挺过来。官僚程序害死了他们。' }, stats: { competence: 20, ethics: 20, leadership: 10, innovation: 10 } },
            { id: 'C', text: { en: '🚒 Fire Truck Power Bridge: "Park the Engine under the window. Use the truck\'s massive alternator and an inverter to power the ward!"', th: '🚒 สะพานไฟจากรถดับเพลิง: "จอดรถดับเพลิงไว้ใต้หน้าต่าง ใช้อัลเทอร์เนเตอร์ยักษ์ของรถและตัวแปลงไฟส่งพลังงานให้วอร์ด!"', zh: '🚒 消防车电力桥接：“把消防车停在窗下。利用车上的大型发电机和逆变器为病房供电！”' }, consequence: { en: '✨ Engineering Genius. You jerry-rig a power line from the truck directly into the NICU. It works perfectly. You save the equipment without needing portable units. Innovation under pressure is your specialty.', th: '✨ อัจฉริยะทางวิศวกรรม คุณดัดแปลงสายไฟจากรถตรงเข้าแผนก NICU มันได้ผลสมบูรณ์แบบ คุณช่วยอุปกรณ์ได้โดยไม่ต้องใช้เครื่องพกพา การสร้างสรรค์ภายใต้ความกดดันคือความเชี่ยวชาญของคุณ', zh: '✨ 工程天才。你临时架设了一条从消防车直接通往NICU的电力线。效果完美。你无需便携设备就保住了医疗仪器。压力下的创新是你的专长。' }, stats: { competence: 60, ethics: 40, leadership: 30, innovation: 60 } }
        ]
    },

    {
        id: 'fir_027',
        text: {
            en: '🚨 The "Blue Wall" Ethics: Your Captain, a decorated veteran, accidentally backs the fire truck into a parked Mercedes. No one saw it. He tells you, "Don\'t put it in the log. I\'ll fix the scratch myself. If HQ finds out, I lose my promotion."',
            th: '🚨 จริยธรรมหลังกำแพงสีน้ำเงิน: หัวหน้าของคุณซึ่งเป็นวีรบุรุษเหรียญตราเพียบ ขับรถดับเพลิงถอยไปชนรถเบนซ์ที่จอดอยู่โดยอุบัติเหตุ ไม่มีใครเห็น เขาบอกคุณว่า "ไม่ต้องลงบันทึกนะ เดี๋ยวพี่จัดการรอยขีดข่วนเอง ถ้าสำนักงานใหญ่รู้ พี่จะไม่ได้เลื่อนตำแหน่ง"',
            zh: '🚨 “蓝色墙壁”伦理：你的队长是一位功勋卓著的老兵，他不小心把消防车撞到了一辆停着的梅赛德斯奔驰上。没人看到。他告诉你：“别记进日志。我自己会修好划痕。如果总部知道了，我就没法晋升了。”'
        },
        options: [
            { id: 'A', text: { en: '🤐 Protect the Captain: "Copy that, Cap. I didn\'t see anything." You value loyalty over the rulebook.', th: '🤐 ปกป้องหัวหน้า: "รับทราบครับพี่ ผมไม่เห็นอะไรทั้งนั้น" คุณให้ค่าความภักดีมากกว่าสมุดกฎระเบียบ', zh: '🤐 保护队长：“明白，队长。我什么也没看见。”你认为忠诚高于规章制度。' }, consequence: { en: '💀 Blackmail & Guilt. A month later, a bystander\'s doorbell camera footage goes viral. The department is humiliated. The Captain is fired, and you are suspended for 6 months for "falsifying official records." Loyalty to a person over the public is a trap.', th: '💀 การข่มขู่และความรู้สึกผิด หนึ่งเดือนต่อมา คลิปจากกล้องวงจรปิดของเพื่อนบ้านกลายเป็นไวรัล กรมเสียชื่อเสียง หัวหน้าถูกไล่ออก และคุณถูกพักงาน 6 เดือนฐาน "ทำบันทึกราชการเป็นเท็จ" ความภักดีต่อคนเหนือประชาชนคือกัปดัก', zh: '💀 勒索与负罪感。一个月后，一位路人的门铃摄像头视频走红。部门蒙羞。队长被解雇，而你因“伪造官方记录”被停职6个月。对个人的忠诚高于对公众的忠诚是一个陷阱。' }, stats: { competence: 10, ethics: -50, leadership: -30, innovation: 0 } },
            { id: 'B', text: { en: '📝 Report it Anonymously: "I can\'t lie, but I don\'t want to burn him directly. I\'ll leave an anonymous tip for the Chief."', th: '📝 รายงานแบบไม่เผยตัวตน: "ผมโกหกไม่ได้ แต่ก็ไม่อยากทำลายเขาตรงๆ ผมจะทิ้งข้อมูลเบลอๆ ไว้ให้หัวหน้าใหญ่เอง"', zh: '📝 匿名举报：“我不能撒谎，但我也不想直接毁了他。我会给局长留个匿名提示。”' }, consequence: { en: '⚖️ Cowardly Ethics. The Chief investigates and finds the truth. The Captain suspects you. The crew treats you like a "rat." You did the right thing, but in a way that destroyed your team status. Integrity requires courage, not anonymity.', th: '⚖️ จริยธรรมที่ขี้ขลาด หัวหน้าใหญ่สอบสวนและพบความจริง หัวหน้าคุณสงสัยในตัวคุณ ทีมงานคนอื่นปฏิบัติกับคุณเหมือน "แมลงสาบ" คุณทำสิ่งที่ถูกต้อง แต่ในวิธีที่ทำลายสถานะในทีมของคุณ ความซื่อสัตย์ต้องการความกล้าหาญ ไม่ใช่การไม่ระบุชื่อ', zh: '⚖️ 懦弱的道德。局长进行了调查并发现了真相。队长开始怀疑你。队员们把你当成“内奸”对待。你做了正确的事，但方式毁掉了你的团队地位。正直需要勇气，而不是匿名。' }, stats: { competence: 20, ethics: 20, leadership: 10, innovation: 0 } },
            { id: 'C', text: { en: '🗣️ Confront and Insist: "Cap, I respect you, but we have to log this. I\'ll testify it was a mechanical glitch to help you, but the truth stays on paper."', th: '🗣️ เผชิญหน้าและยืนกราน: "พี่ครับ ผมเคารพพี่นะ แต่เราต้องลงบันทึก ผมจะให้การว่าเป็นเพราะระบบเครื่องยนต์ขัดข้องเพื่อช่วยพี่ แต่ความจริงต้องอยู่บนกระดาษ"', zh: 'C 对质并坚持：“队长，我尊重你，但我们必须记录这件事。我会作证说是机械故障以帮你，但事实必须写在纸上。”' }, consequence: { en: '✅ Respect Earned. The Captain is angry initially but respects your backbone. He reports it. He gets a slap on the wrist, but because he was honest, he keeps his promotion track. You are seen as a leader of high character.', th: '✅ ได้รับความเคารพ ตอนแรกหัวหน้าโกรธแต่ก็เคารพในความเด็ดเดี่ยวของคุณเขารายงานเรื่องนี้ เขาถูกตำหนิเล็กน้อย แต่เพราะความซื่อสัตย์ เขาจึงยังได้เลื่อนตำแหน่งต่อ คุณถูกมองว่าเป็นผู้นำที่มีคุณสมบัติสูง', zh: '✅ 赢得尊重。队长起初很生气，但尊重你的骨气。他上报了。他只受到了轻微处罚，但因为他的诚实，他保留了晋升轨迹。你被视为一位具有高尚品格的领导者。' }, stats: { competence: 40, ethics: 50, leadership: 60, innovation: 10 } }
        ]
    },

    {
        id: 'fir_028',
        text: {
            en: '🏭 The Industrial Dust Explosion: A grain elevator has exploded. The air is still thick with combustible dust. A second explosion is imminent if any spark occurs. You see a worker trapped under a heavy beam, but your battery-powered tools might spark.',
            th: '🏭 การระเบิดของฝุ่นอุตสาหกรรม: ไซโลเก็บธัญพืชเกิดระเบิดขึ้น อากาศยังเต็มไปด้วยฝุ่นที่พร้อมจะลุกไหม้ การระเบิดครั้งที่สองจะเกิดขึ้นทันทีหากมีสปาร์คเพียงนิดเดียว คุณเห็นคนงานติดอยู่ใต้คานหนัก แต่อุปกรณ์ไฟฟ้าของคุณอาจทำให้เกิดสปาร์คได้',
            zh: '🏭 工业粉尘爆炸：一座谷仓发生了爆炸。空气中仍然弥漫着浓密的易燃粉尘。如果出现任何火花，随时可能发生二次爆炸。你看到一名工人被困在沉重的梁下，但你的电池供电工具可能会产生火花。'
        },
        options: [
            { id: 'A', text: { en: '⛏️ Manual Extraction: "No power tools! Get the hand jacks and pry bars. We do this old school."', th: '⛏️ ใช้แรงคน: "ห้ามใช้เครื่องมือไฟฟ้า! เอาแม่แรงมือและชะแลงมา เราจะทำแบบดั้งเดิม"', zh: '⛏️ 手动营救：“不准使用电动工具！去拿手动千斤顶和撬棍。我们用老办法。”' }, consequence: { en: '✅ Safe but Slow. It takes twice as long, and your back is screaming, but you avoid a second explosion. The worker is rescued with a crushed leg. You prioritized scene safety over speed, which is the hallmark of a veteran.', th: '✅ ปลอดภัยแต่ช้า ใช้เวลานานเป็นสองเท่าและคุณปวดหลังสุดๆ แต่คุณหลีกเลี่ยงการระเบิดครั้งที่สองได้ คนงานได้รับการช่วยเหลือออกมาแต่ขาแหลก คุณให้ความสำคัญกับความปลอดภัยของที่เกิดเหตุมากกว่าความเร็ว ซึ่งเป็นเครื่องหมายของมือโปร', zh: '✅ 安全但缓慢。花了两倍的时间，你的腰快断了，但你避免了二次爆炸。工人获救了，但腿部被压伤。你将现场安全置于速度之上，这是老兵的标志。' }, stats: { competence: 40, ethics: 30, leadership: 40, innovation: 0 } },
            { id: 'B', text: { en: '💦 Wet the Dust: "Flood the area with a fine water mist to knock the dust down, then use the power cutters."', th: '💦 ฉีดน้ำพรมฝุ่น: "ฉีดละอองน้ำหมอกให้ทั่วพื้นที่เพื่อให้ฝุ่นตกลงมา แล้วค่อยใช้เครื่องตัดไฟฟ้า"', zh: '💦 弄湿粉尘：“用细水雾喷洒该区域以压制粉尘，然后使用电动切割机。”' }, consequence: { en: '✨ Scientific Tactic. The mist binds the dust particles, rendering the atmosphere non-explosive. You cut the beam in 30 seconds. The worker is out and in the ambulance before the structural integrity fails. Brilliant application of hazmat physics.', th: '✨ กลยุทธ์ทางวิทยาศาสตร์ ละอองน้ำช่วยจับอนุภาคฝุ่น ทำให้บรรยากาศไม่ระเบิดได้อีก คุณตัดคานได้ใน 30 วินาที คนงานออกมาและขึ้นรถพยาบาลได้ก่อนที่โครงสร้างจะพัง การประยุกต์ใช้ฟิสิกส์วัตถุอันตรายที่ยอดเยี่ยม', zh: '✨ 科学战术。水雾束缚了粉尘颗粒，使大气环境变得不再具有爆炸性。你在30秒内切断了横梁。在结构强度失效前，工人已获救护车送走。对危化物理学的精妙应用。' }, stats: { competence: 50, ethics: 35, leadership: 40, innovation: 60 } },
            { id: 'C', text: { en: '🚜 Heavy Push: "Hook the winch from the truck 50 feet away and pull the beam. Keep the electronics away from the dust!"', th: '🚜 ลากออก: "เกี่ยววินซ์จากรถที่จอดอยู่ห่างไป 50 ฟุตแล้วฉุดคานออกไป เก็บเครื่องไฟฟ้าให้ห่างจากฝุ่น!"', zh: 'C 重力牵引：“用50英尺外消防车的绞盘钩住横梁并拉动。让电子设备远离粉尘！”' }, consequence: { en: '⚠️ Structural Collapse. The beam was a "secondary support." When the truck pulled it, a portion of the roof collapsed near the victim. You got them out, but they suffered additional injuries. A blunt tool for a delicate problem.', th: '⚠️ โครงสร้างถล่ม คานนั้นเป็น "ส่วนรองรับรอง" พอรถดึงออกไป เพดานส่วนหนึ่งก็ถล่มลงมาใกล้เหยื่อ คุณช่วยเขาออกมาได้แต่เขาได้รับบาดเจ็บเพิ่ม เป็นการใช้วิธีรุนแรงกับปัญหาที่ละเอียดอ่อน', zh: '⚠️ 结构塌陷。那根梁是“次要支撑”。当卡车拉动它时，受害者附近的一部分屋顶坍塌了。你把他们救了出来，但他们受了额外的伤。用蛮力处理微妙问题。' }, stats: { competence: 20, ethics: 20, leadership: 20, innovation: 30 } }
        ]
    },

    {
        id: 'fir_029',
        text: {
            en: '🚢 The Drowning Car: A car has plunged into the city harbor. You are the first on scene. You see a face pressed against the rear window. The car is sinking fast, only the roof is visible. You are not a certified dive-rescue technician, but the specialist team is 10 minutes away.',
            th: '🚢 รถจมน้ำ: รถคันหนึ่งพุ่งตกลงไปในท่าเรือ คุณไปถึงที่เกิดเหตุเป็นคนแรก เห็นหน้าคนแนบกับกระจกหลัง รถกำลังจมอย่างรวดเร็ว เหลือแต่หลังคาที่มองเห็น คุณไม่ใช่เจ้าหน้าที่กู้ภัยทางน้ำที่ได้รับใบเซอร์ แต่ทีมเฉพาะทางอยู่ห่างไป 10 นาที',
            zh: '🚢 坠海车辆：一辆汽车坠入了城市港口。你是第一个到达现场的人。你看到一张脸紧贴在后窗上。车子沉得很快，只剩下车顶可见。你不是认证的水下救援人员，但专家小组需要10分钟才能赶到。'
        },
        options: [
            { id: 'A', text: { en: '🏊 Immediate Dive: "I can\'t watch them drown! I\'m going in with a window punch!" You jump in without a line.', th: '🏊 กระโดดลงไปทันที: "ผมดูเขาจมน้ำตายไม่ได้! ผมจะลงไปพร้อมตัวตอกกระจก!" คุณกระโดดลงไปโดยไม่มีสายเซฟตี้', zh: '🏊 立即下水：“我不能眼睁睁看着他们淹死！我拿着破窗器跳下去！”你在没有牵引绳的情况下跳了进去。' }, consequence: { en: '⚡ Dangerous Heroics. You reach the car, but the water is murky and the current is stronger than you thought. You break the window, but the sudden rush of water sucks the car down further. You nearly drown and have to be rescued by a bystander. You failed the victim by not securing yourself first.', th: '⚡ วีรบุรุษจอมปลอมที่อันตราย คุณถึงตัวรถแต่น้ำขุ่นและกระแสลึกแรงกว่าที่คิด พอคุณทุบกระจก แรงดันน้ำที่ไหลเข้าดึงรถให้จมดิ่งลงไปอีก คุณเกือบจมน้ำและต้องให้คนแถวนั้นช่วย คุณทำพลาดเพราะไม่เซฟตัวเองก่อน', zh: '⚡ 危险的英雄主义。你游到了车边，但水很浑浊，水流比你想象的还要强。你打破了窗户，但突然涌入的水流将车吸得更深。你险些溺水，不得不由路人营救。你因为没有先固定好自己而未能救出受害者。' }, stats: { competence: 20, ethics: 40, leadership: 10, innovation: 10 } },
            { id: 'B', text: { en: '🛡️ Shore-Based Anchor: "Tie a line to me! Give me the underwater window punch. Keep 3 people on the shore line!"', th: '🛡️ ยึดเหนี่ยวจากบนฝั่ง: "เอาเชือกผูกตัวผมไว้! เอาตัวตอกกระจกใต้น้ำมา ให้ 3 คนคอยดึงเชือกบนฝั่งไว้!"', zh: 'B 岸上锚固：“给我系上绳子！给我水下破窗器。岸边留三个人拽住绳子！”' }, consequence: { en: '✅ Controlled Success. With the safety line, you reach the car and break the rear window. You pull a child out just as the car disappears. You return to shore safely. You managed the risk properly and got the result.', th: '✅ สำเร็จอย่างมีการควบคุม ด้วยสายเซฟตี้ คุณถึงตัวรถและทุบกระจกหลัง คุณดึงเด็กออกมาได้ทันเวลาก่อนรถจะหายไป คุณกลับเข้าฝั่งได้อย่างปลอดภัย คุณจัดการความเสี่ยงได้อย่างถูกต้องและได้ผลลัพธ์ที่ต้องการ', zh: '✅ 受控并成功。有了安全牵引绳，你游到了车边并打破了后窗。就在车子消失前，你拉出了一个孩子。你安全返回岸边。你正确处理了风险并取得了成果。' }, stats: { competence: 50, ethics: 45, leadership: 40, innovation: 20 } },
            { id: 'C', text: { en: '🚜 Winch Technique: "The car is still shallow! Hook the fire truck winch to the axle and drag it onto the ramp!"', th: 'C เทคนิคใช้วินซ์: "รถยังจมไม่ลึก! เอาวินซ์รถดับเพลิงไปเกี่ยวเพลาแล้วลากขึ้นทางลาดตรงนั้น!"', zh: 'C 绞盘技术：“车还没沉深！用消防车绞盘钩住车轴，把它拖到斜坡上！”' }, consequence: { en: '✨ Asset Mastery. You work with a teammate who swims the hook down. You drag the car out of the water in 2 minutes. The occupants are rescued on dry land. No diving needed. Best use of available heavy equipment.', th: '✨ ความเป็นเลิศในการใช้อุปกรณ์ คุณร่วมมือกับเพื่อนร่วมทีมที่ว่ายเอาตะขอไปเกี่ยว คุณลากรถขึ้นจากน้ำได้ใน 2 นาที ผู้โดยสารได้รับการช่วยเหลือบนบก ไม่ต้องดำน้ำลงไป เป็นการใช้อุปกรณ์หนักที่ยอดเยี่ยมที่สุด', zh: '✨ 装备精通。你和一名队友合作，他游下去勾住车。你在2分钟内将车拖出水面。车内人员在干地上获救。无需下潜。对现有重型设备的最佳利用。' }, stats: { competence: 60, ethics: 40, leadership: 30, innovation: 50 } }
        ]
    },

    {
        id: 'fir_030',
        text: {
            en: '🚨 The Mental Health Toll: After a particularly brutal car accident involving children, your youngest crew member is staring into space and refusing to eat. Your Captain says, "He just needs to toughen up. It\'s part of the job. Don\'t coddle him."',
            th: '🚨 บาดแผลทางใจ: หลังจากอุบัติเหตุรถยนต์ที่รุนแรงมากซึ่งมีเด็กเข้ามาเกี่ยวข้อง ลูกทีมที่อายุน้อยที่สุดของคุณนั่งเหม่อลอยและไม่ยอมกินข้าว หัวหน้าบอกคุณว่า "เขาต้องเข้มแข็งขึ้นเอง มันคืองาน อย่าไปโอ๋เขามาก"',
            zh: '🚨 心理健康代价：在处理完一起涉及儿童的惨烈车祸后，你团队里最年轻的队员盯着虚空发呆，拒绝进食。你的队长说：“他只需要变坚强。这是工作的一部分。别娇惯他。”'
        },
        options: [
            { id: 'A', text: { en: '👊 Follow Captain: "Listen kid, suck it up. We have another shift. This isn\'t for everyone." You focus on "Toughness."', th: '👊 ทำตามหัวหน้า: "ฟังนะเจ้าหนู อดทนไว้ เรายังมีกะต่อไป งานนี้มันไม่ได้เหมาะกับทุกคน" คุณเน้นการ "อดทน"', zh: '👊 遵循队长：“听着伙计，挺住。我们还有下一个班。这工作不是人人都能干的。”你专注于“坚韧”。' }, consequence: { en: '💀 Breaking Point. The rookie quits 2 weeks later and suffers a mental breakdown. You lost a good firefighter and perpetuated a toxic culture that leads to high suicide rates in the service.', th: '💀 จุดแตกหัก รุ่นน้องลาออกใน 2 สัปดาห์ถัดมาและมีอาการทางจิตพังทลาย คุณเสียเจ้าหน้าที่ดีๆ ไปคนหนึ่งและส่งต่อวัฒนธรรมที่เป็นพิษซึ่งนำไปสู่อัตราการฆ่าตัวตายสูงในอาชีพนี้', zh: '💀 崩溃点。两周后这个新人辞职了，并遭受了精神崩溃。你失去了一名优秀的消防员，并助长了导致该行业高自杀率的有毒文化。' }, stats: { competence: 10, ethics: -40, leadership: -40, innovation: 0 } },
            { id: 'B', text: { en: '🧘 Peer Support: "Ignore Cap. Hey brother, let\'s go for a walk. I\'ve seen things that haunt me too. It\'s okay to be messed up after today."', th: '🧘 เพื่อนช่วยเพื่อน: "อย่าไปฟังหัวหน้าเลย เฮ้ยเพื่อน ไปเดินเล่นกันหน่อย พี่ก็เคยเห็นเรื่องที่ตามหลอนพี่เหมือนกัน วันนี้มันหนักจริงๆ ไม่แปลกที่แกจะรู้สึกแบบนี้"', zh: '🧘 同僚支持：“别管队长。嘿兄弟，我们去走走。我也见过令我魂牵梦萦的事。今天过后感觉不舒服是很正常的。”' }, consequence: { en: '✅ Emotional Resilience. You build a bond. He realizes he\'s not "broken." He stays with the department and eventually becomes a counselor for other firefighters. True brotherhood is about protection, including mental health.', th: '✅ ความยืดหยุ่นทางอารมณ์ คุณสร้างสายสัมพันธ์ เขาตระหนักว่าเขาไม่ได้ "พัง" เขาอยู่กับกรมต่อและสุดท้ายกลายเป็นที่ปรึกษาให้เพื่อนร่วมอาชีพคนอื่น ความเป็นพี่น้องที่แท้จริงคือการปกป้อง รวมถึงสุขภาพจิตด้วย', zh: '✅ 心理韧性。你建立了联结。他意识到自己并未“坏掉”。他留在了部门，最终成为其他消防员的心理咨询员。真正的兄弟情谊关乎保护，也包括心理健康。' }, stats: { competence: 30, ethics: 50, leadership: 60, innovation: 10 } },
            { id: 'C', text: { en: '📢 Call a Critical Incident Stress Debrief (CISD): "Captain, I\'m calling the chaplain and the peer support team for the WHOLE station. We all saw it."', th: '📢 เรียกประชุมเยียวยาจิตใจ (CISD): "หัวหน้าครับ ผมจะเรียกอนุศาสนาจารย์และทีมเยียวยาใจเข้ามาให้คนทั้งสถานี เราทุกคนเห็นภาพเดียวกัน"', zh: 'C 要求进行重大事件压力汇报（CISD）：“队长，我要为全站人员请随军牧师和同僚互助小组。我们大家都看到了。”' }, consequence: { en: '✅ Professional Management. By making it a group activity, you remove the stigma from the rookie. The whole crew talks, and even the Captain ends up admitting he\'s stressed. You improved the entire station\'s longevity.', th: '✅ การจัดการอย่างมือโปร ด้วยการทำให้เป็นกิจกรรมกลุ่ม คุณลบตราบาปออกจากรุ่นน้อง ทุกคนได้ระบาย แม้แต่หัวหน้าเองสุดท้ายก็ยอมรับว่าเครียด คุณช่วยยืดอายุการทำงานให้กับคนทั้งสถานี', zh: '✅ 专业管理。通过将其转变为集体活动，你消除了新人的羞耻感。全队进行了交流，甚至队长最后也承认自己压力很大。你延长了全站人员的职业寿命。' }, stats: { competence: 40, ethics: 40, leadership: 70, innovation: 20 } }
        ]
    },
    {
        id: 'fir_031',
        text: {
            en: '🚗 The EV Thermal Runaway: A Tesla is on fire in an underground parking garage. The smoke is thick and toxic. You’ve been spraying water for 20 minutes, but the battery keeps reigniting (thermal runaway). The heat is beginning to damage the concrete ceiling above.',
            th: '🚗 ไฟไหม้รถยนต์ไฟฟ้า: รถเทสลาเกิดเพลิงไหม้ในที่จอดรถใต้ดิน ควันหนาทึบและเป็นพิษ คุณฉีดน้ำมา 20 นาทีแล้วแต่แบตเตอรี่ยังคงลุกไหม้ซ้ำ (Thermal Runaway) ความร้อนเริ่มทำลายเพดานคอนกรีตด้านบน',
            zh: '🚗 电动汽车热失控：地下车库内一辆特斯拉起火。烟雾浓烈且有毒。你已经喷水20分钟了，但电池仍在不断复燃（热失控）。高温开始损坏上方的混凝土天花板。'
        },
        options: [
            { id: 'A', text: { en: '💧 Massive Water Supply: "We need more lines! Just keep drowning it until the temperature drops!"', th: '💧 ใช้น้ำมหาศาล: "เราต้องการสายส่งน้ำเพิ่ม! ฉีดถล่มมันเข้าไปจนกว่าอุณหภูมิจะลด!"', zh: '💧 海量供水：“我们需要更多水带！不停地淹没它，直到温度下降！”' }, consequence: { en: '😱 Garage Collapse. You use 10,000 gallons of water. The battery is still burning, but the weight of the water and the thermal stress causes a "spalling" effect in the concrete. A section of the ceiling collapses. You risked the structural integrity for a chemical fire that doesn\'t react to water.', th: '😱 อาคารจอดรถถล่ม คุณใช้น้ำไปหมื่นแกลลอน แบตเตอรี่ยังไหม้อยู่ แต่น้ำหนักของน้ำและความเครียดความร้อนทำให้คอนกรีตเกิดการกะเทาะ (Spalling) เพดานส่วนหนึ่งหล่นลงมา คุณเสี่ยงความมั่นคงของโครงสร้างเพื่อสู้กับไฟเคมีที่ไม่ตอบสนองต่อน้ำ', zh: '😱 车库坍塌。你使用了1万加仑水。电池仍在燃烧，但水的重量和热应力导致混凝土产生“剥落”效应。一部分天花板塌陷了。你为了一个对水不产生反应的化学火灾而冒了结构完整性的风险。' }, stats: { competence: 10, ethics: 20, leadership: 10, innovation: 0 } },
            { id: 'B', text: { en: '📦 Fire Blanket and containment: "Stop the water. Deploy the EV fire blanket to contain the smoke and let it burn out in a controlled way."', th: '📦 ใช้ผ้าห่มกันไฟ: "หยุดน้ำ! ใช้ผ้าห่มกันไฟสำหรับ EV คลุมเพื่อกักควันและปล่อยให้มันไหม้หมดไปเองภายใต้การควบคุม"', zh: '📦 灭火毯与隔离：“停止喷水。部署电动汽车灭火毯以遏制烟雾，让它在受控的情况下燃尽。”' }, consequence: { en: '✅ Expert Hazmat Logic. By cutting off oxygen and containing the toxic hydrogen fluoride gas, you prevent the garage from becoming a toxic death trap. The battery eventually exhausts itself. You saved the building from water damage and collapse.', th: '✅ ตรรกะวัตถุอันตรายระดับเชี่ยวชาญ การตัดออกซิเจนและกักก๊าซไฮโดรเจนฟลูออไรด์ที่เป็นพิษ ช่วยป้องกันไม่ให้ที่จอดรถกลายเป็นกับดักมรณะ แบตเตอรี่จะมอดไปเองในที่สุด คุณช่วยอาคารจากความเสียหายจากน้ำและการถล่ม', zh: '✅ 专家级危化逻辑。通过隔离氧气并遏制有毒的氟化氢气体，你防止了车库变成有毒的死亡陷阱。电池最终自行燃尽。你使建筑免受水损和坍塌。' }, stats: { competence: 50, ethics: 40, leadership: 30, innovation: 50 } },
            { id: 'C', text: { en: '🚜 Tactical Tow: "Hook it and drag it out into the street where we can build a dam and submerge it!"', th: '🚜 ลากออกข้างนอก: "เกี่ยวรถแล้วลากออกมาที่ถนน เราจะสร้างเขื่อนกั้นน้ำแล้วแช่มันลงไปในน้ำเลย!"', zh: 'C 战术拖车：“钩住它，把它拖到街上，我们在那里筑坝将其淹没！”' }, consequence: { en: '⚠️ Dangerous Success. Dragging a burning EV through a garage involves high risk of spreading the fire to other cars. You get it out, but the street-side "pool" you created is now considered a toxic waste site by the EPA. An expensive cleanup follows.', th: '⚠️ สำเร็จอย่างเสี่ยง การลากรถ EV ที่กำลังไหม้ผ่านโรงรถมีความเสี่ยงสูงที่จะแพร่ไฟไปยังรถคันอื่น คุณนำมันออกมาได้ แต่ "สระน้ำ" ริมถนนที่คุณสร้างขึ้นถูกมองว่าเป็นแหล่งกากสารพิษอันตราย ต้องมีการทำความสะอาดที่แพงมากตามมา', zh: '⚠️ 危险的成功。在车库中拖拽一辆燃烧的电动汽车存在将火灾蔓延到其他车辆的高风险。你把它弄了出来，但你在街边制造的“水池”现在被环保署视为有毒废物场。随后是昂贵的清理工作。' }, stats: { competence: 30, ethics: 20, leadership: 30, innovation: 40 } }
        ]
    },

    {
        id: 'fir_032',
        text: {
            en: '🏙️ The Jumper: A distraught man is sitting on the edge of a 10th-story window. Police negotiators are caught in traffic. You are at the top of the aerial ladder. He starts to lean forward. He says, "I have nothing left. Don\'t come closer."',
            th: '🏙️ คนจะกระโดด: ชายผู้สิ้นหวังนั่งอยู่บนขอบหน้าต่างชั้น 10 ทีมเจรจาของตำรวจติดไฟแดงอยู่ คุณอยู่บนสุดของบันไดรถดับเพลิง เขาเริ่มโน้มตัวไปข้างหน้าและพูดว่า "ผมไม่เหลืออะไรแล้ว อย่าเข้ามานะ"',
            zh: '🏙️ 轻生者：一名心灰意冷的男子坐在10楼窗户边缘。警方谈判专家被堵在路上。你就在云梯的最顶端。他开始身体前倾，说道：“我一无所有了。别靠近我。”'
        },
        options: [
            { id: 'A', text: { en: '👨‍🚒 Tactical Grab: "I\'m making a move! Swing the ladder in and I\'ll tackle him back into the room!"', th: '👨‍🚒 พุ่งชาร์จ: "ผมจะเข้าแล้ว! เหวี่ยงบันไดเข้าไปแล้วผมจะรวบเขาเข้าห้องไปเอง!"', zh: '👨‍🚒 战术扑救：“我要动手了！把云梯摆过去，我把他扑进房间里！”' }, consequence: { en: '😱 Tragic Failure. He sees your sudden movement and panics, jumping before you can grab his jacket. You witness the fall from 3 feet away. Physical force in psychological crises often backfires without specialized training.', th: '😱 ความล้มเหลวที่น่าสลดใจ เขาเห็นคุณขยับตัวกะทันหันแล้วตกใจกลัว เลยกระโดดลงไปก่อนที่คุณจะคว้าแจ็คเก็ตเขาได้ทัน คุณเห็นเขาตกลงไปต่อหน้าต่อตา การใช้กำลังในวิกฤตทางจิตใจมักให้ผลตรงข้ามหากไม่มีการฝึกเฉพาะทาง', zh: '😱 悲剧性的失败。他看到了你突然的动作并感到恐慌，在你抓到他的夹克前就跳了下去。你在3英尺外亲眼目睹了坠落。在心理危机中使用武力，如果没有经过专业培训，往往会适得其反。' }, stats: { competence: 10, ethics: 10, leadership: -20, innovation: 0 } },
            { id: 'B', text: { en: '🤝 Emathetic Connection: "My name is [Name]. I\'m just a firefighter. I\'m not here to arrest you. I\'m just here to make sure you\'re safe. Can we just talk for a minute?"', th: '🤝 สร้างความสัมพันธ์: "ผมชื่อ [ชื่อ] ผมเป็นแค่นักดับเพลิงครับ ผมมาที่นี่ไม่ได้จะมาจับคุณ ผมแค่มาดูให้แน่ใจว่าคุณปลอดภัย เราคุยกันสักนาทีได้ไหมครับ?"', zh: '🤝 共情连接：“我叫[名字]。我只是个消防员。我不是来逮捕你的。我只是来确保你的安全。我们能聊一分钟吗？”' }, consequence: { en: '✅ Crisis Containment. Your calm, non-threatening demeanor de-escalates his panic. You keep him talking for 15 minutes until the professionals arrive to take over. You saved a life with words, the most powerful tool in your belt.', th: '✅ ควบคุมวิกฤต ท่าทีที่สงบและไม่คุกคามของคุณช่วยลดความตื่นตระหนกของเขา คุณชวนเขาคุยได้ 15 นาทีจนกระทั่งผู้เชี่ยวชาญมาถึงเพื่อรับช่วงต่อ คุณช่วยชีวิตคนด้วยคำพูด ซึ่งเป็นเครื่องมือที่ทรงพลังที่สุดที่คุณมี', zh: '✅ 危机控制。你冷静、无威胁的态度缓和了他的恐慌。你让他保持交谈15分钟，直到专业人员赶来接手。你用语言挽救了一个生命，这是你工具带上最强大的工具。' }, stats: { competence: 40, ethics: 50, leadership: 40, innovation: 20 } },
            { id: 'C', text: { en: '🔫 Water Deterrent: "Ready the deck gun! If he jumps, a high-pressure blast might push him back into the window area!"', th: '🔫 ใช้แรงดันน้ำยับยั้ง: "เตรียมปืนฉีดน้ำบนรถ! ถ้าเขาโดด ให้ฉีดน้ำแรงดันสูงดันเขาเข้าหาหน้าต่าง!"', zh: 'C 水流威慑：“准备好车载水炮！如果他跳，高压水流可能会把他冲回窗户区域！”' }, consequence: { en: '💀 Deadly Mistake. Water at that pressure is a physical weapon. You either shatter the glass onto him or blast him off the ledge with 1000 lbs of force. The Chief immediately strips you of your helmet for suggesting such a lethal tactic.', th: '💀 ความผิดพลาดที่ร้ายแรง น้ำในแรงดันขนาดนั้นคืออาวุธดีๆ นี่เอง คุณอาจจะทำกระจกแตกใส่เขาหรือฉีดเขาตกขอบหน้าต่างด้วยแรงกระแทกมหาศาล หัวหน้ายึดหมวกคุณทันทีที่เสนอแผนการที่อันตรายถึงชีวิตขนาดนี้', zh: '💀 致命错误。那种压力的水流是一种物理武器。你要么把玻璃震碎在他身上，要么用1000磅的推力把他从台阶上冲下去。局长因为你建议这种致命战术而立即撤了你的职。' }, stats: { competence: -20, ethics: -20, leadership: -30, innovation: 10 } }
        ]
    },

    {
        id: 'fir_033',
        text: {
            en: '🔥 The Backdraft Warning: You are at the door of a commercial bakery. The windows are "breathing" (smoke puffing in and out of cracks). The glass is yellow-stained and vibrating. Your partner has the halligan tool ready to forced-entry. "Let\'s go, the fire is inside!"',
            th: '🔥 สัญญาณเตือนแบ็คดราฟต์: คุณอยู่หน้าประตูร้านเบเกอรี่ กระจกหน้าต่างเหมือนกำลัง "หายใจ" (ควันพ่นเข้าพ่นออกตามรอยแตก) กระจกมีคราบเหลืองและกำลังสั่นสะเทือน คู่หูของคุณเตรียมอุปกรณ์งัดประตูแล้ว "ไปกันเถอะ ไฟอยู่ข้างใน!"',
            zh: '🔥 回燃警告：你站在一家商业面包店门前。窗户正在“呼吸”（烟雾从缝隙中吸入呼出）。玻璃发黄并震动。你的搭档已经准备好了哈利根工具准备强转。“快走，火就在里面！”'
        },
        options: [
            { id: 'A', text: { en: '🛑 Hold Position: "Stop! That’s a backdraft waiting to happen. Do not open that door! We need to vent the roof first!"', th: '🛑 ตรึงกำลังไว้: "หยุด! นั่นมันแบ็คดราฟต์กำลังจะเกิดขึ้น ห้ามเปิดประตูเด็ดขาด! เราต้องระบายอากาศจากบนหลังคาก่อน!"', zh: '🛑 守住位置：“停！那是回燃的前兆。别开那扇门！我们需要先进行屋顶通风！”' }, consequence: { en: '✅ Scientific Firefighting. Just as you call for roof ventilation, the roof team cuts a hole. A massive fireball shoots 50 feet into the air—the backdraft occurred safely upward. If you had opened the door, your crew would have been vaporized.', th: '✅ การดับเพลิงตามหลักวิทยาศาสตร์ ทันทีที่คุณเรียกกู้ภัยบนหลังคา ทีมบนหลังคาก็เจาะรู ลูกไฟยักษ์พุ่งขึ้นฟ้า 50 ฟุต—แบ็คดราฟต์เกิดขึ้นในทิศทางด้านบนอย่างปลอดภัย หากคุณเปิดประตู ทีมของคุณคงถูกเผาไหม้ไปหมดแล้ว', zh: '✅ 科学灭火。就在你请求屋顶通风时，屋顶小组打开了一个洞。一个巨大的火球向空中喷射了50英尺——回燃安全地向上发生了。如果你打开了门，你的队员会被瞬间汽化。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 10 } },
            { id: 'B', text: { en: '💪 Quick Entry: "Kick it anyway! We have the line charged. We can take the heat!"', th: '💪 บุกเข้าไป: "ถีบเข้าไปเลย! เราเตรียมสายฉีดน้ำไว้แล้ว เราทนความร้อนได้!"', zh: '💪 快速进入：“管他的，踢开它！我们已经充压了水带。我们能扛住热量！”' }, consequence: { en: '💀 Catastrophic Outcome. The moment the door seal breaks, oxygen rushes in. The entire building explodes. The force throws your engine 10 feet. You and your partner are critically injured or worse. Ignoring "reading the fire" is the ultimate sin.', th: '💀 ความผิดพลาดที่ร้ายแรงที่สุด วินาทีที่อากาศเข้า ตึกระเบิดทันที คุณและคู่หูบาดเจ็บสาหัส การละเลยสัญญาณเตือนคือความผิดที่แก้ตัวไม่ได้', zh: '💀 灾难性后果。门封破裂的一瞬间，氧气涌入。整座建筑爆炸了。爆炸力把你们的消防车掀飞了10英尺。你和你的搭档重伤甚至死亡。忽视“读火”是终极的罪过。' }, stats: { competence: 10, ethics: 10, leadership: -40, innovation: 0 } },
            { id: 'C', text: { en: '💦 Door-Cooling: "Spray the door and the cracks to cool the gases before we open up!"', th: '💦 ฉีดน้ำคูลลิ่ง: "ฉีดน้ำใส่ประตูและรอยแตกเพื่อลดอุณหภูมิก๊าซก่อนที่เราจะเปิด!"', zh: 'C 冷却舱门：“在我们开启前，向门上和缝隙喷水以冷却气体！”' }, consequence: { en: '⚠️ Ineffective. Cooling the door does nothing for the superheated, oxygen-starved gases inside. It may actually obscure your vision with steam. You either wait for vertical ventilation or you face a backdraft. This "middle ground" is dangerous.', th: '⚠️ ไม่ได้ผล การระบายความร้อนที่ประตูช่วยอะไรไม่ได้เลยสำหรับก๊าซที่ร้อนจัดข้างใน แถมไอน้ำอาจจะบังทัศนวิสัยคุณอีก ทางสายกลางนี้มันอันตราย', zh: '⚠️ 无效。冷却门对于内部过热、缺氧的气体毫无作用。事实上，产生的蒸汽可能会模糊你的视线。你要么等待垂直通风，要么就会面临回燃。这种“中间地带”非常危险。' }, stats: { competence: 20, ethics: 20, leadership: 10, innovation: 20 } }
        ]
    },

    {
        id: 'fir_034',
        text: {
            en: '🏚️ The "Empty" Building Search: You are searching a condemned apartment complex that is officially empty. The fire is spreading in the walls. Your air tank is at 25%. You hear a faint "Help" from a boarded-up room. The building is starting to groan.',
            th: '🏚️ ค้นหาในตึก "ร้าง": คุณกำลังค้นหาในอพาร์ตเมนต์ร้างที่ถูกสั่งปิดอย่างเป็นทางการ ไฟกำลังลามตามผนัง ถังอากาศของคุณเหลือ 25% คุณได้ยินเสียง "ช่วยด้วย" เบาๆ จากห้องที่ถูกตอกไม้ปิดไว้ ตึกเริ่มมีเสียงเอี๊ยดอ๊าดเตือนการถล่ม',
            zh: '🏚️ “空”屋搜索：你正在一栋官方登记为空置的废弃公寓楼内搜救。火势正在墙内蔓延。你的气瓶还剩25%。你听到一个封死的房间里传出微弱的“救命”声。楼体开始发出呻吟声。'
        },
        options: [
            { id: 'A', text: { en: '🔨 Breach and Rescue: "I\'m going in! I have air for 5 more minutes. Coverage, stand by!"', th: '🔨 พังเข้าไปช่วย: "ผมจะเข้าไป! ผมยังมีอากาศอีก 5 นาที ทีมสนับสนุนเตรียมพร้อม!"', zh: '🔨 破拆并营救：“我要进去了！我的空气还能维持5分钟。掩护人员，待命！”' }, consequence: { en: '✅ Heroic Save. You smash the boards and find a squatter trapped under a collapsed ceiling. You drag them out just as your low-air alarm starts whistling. You reached the exit with 0% air, but the victim is alive. Risk vs Gain was high, but justified by a life.', th: '✅ การช่วยชีวิตที่กล้าหาญ คุณทุบไม้กระดานและพบคนไร้บ้านติดอยู่ใต้เพดานที่ถล่มลงมา คุณลากเขาออกมาได้ทันทีที่สัญญาณเตือนอากาศต่ำดังขึ้น คุณถึงทางออกพอดีขณะอากาศหมดเกลี้ยง แต่เหยื่อรอดชีวิต แม้ความเสี่ยงจะสูงแต่คุ้มค่าที่ช่วยชีวิตคนได้', zh: '✅ 英勇营救。你砸开了木板，发现一名被困在坍塌天花板下的流浪者。就在你的低气压警报响起时，你把他拖了出来。你到达出口时空气已耗尽，但受害者获救了。收益风险比很高，但为了生命是值得的。' }, stats: { competence: 40, ethics: 50, leadership: 40, innovation: 0 } },
            { id: 'B', text: { en: '🛑 Safety First: "Building is unstable and air is low. I can\'t make entry. Marking the room for the rescue squad with more air."', th: '🛑 ความปลอดภัยต้องมาก่อน: "ตึกไม่มั่นคงและอากาศเหลือต่ำ ผมเข้าไปไม่ได้ จะทำเครื่องหมายที่ห้องไว้ให้ทีมกู้ภัยที่มีอากาศเยอะกว่าเข้ามาจัดการ"', zh: '🛑 安全第一：“建筑不稳且空气不足。我无法进入。给房间做标记，让空气充足的救援小组来。”' }, consequence: { en: '😔 Victim Fatality. By the time the next squad reaches the 3rd floor, the hallway has collapsed. They find the victim deceased from smoke inhalation. It was the "safe" choice, but haunt your dreams for years.', th: '😔 เหยื่อเสียชีวิต กว่าทีมต่อไปจะถึงชั้น 3 ทางเดินก็ถล่มลงมาแล้ว พวกเขาพบเหยื่อเสียชีวิตจากการสูดควันเข้าไป มันคือทางเลือกที่ "ปลอดภัย" แต่มันจะตามหลอนคุณไปอีกหลายปี', zh: '😔 受害者遇难。等到下一个小组到达3楼时，走廊已经塌了。他们发现受害者因阴气入体（吸入烟雾）死亡。这是“安全”的选择，但会成为你多年的噩梦。' }, stats: { competence: 30, ethics: 20, leadership: 20, innovation: 0 } },
            { id: 'C', text: { en: '💨 Air Share: "Partner, gimme your buddy-breather. I\'m going in, you stay in the clear and hold the rope!"', th: '💨 ใช้อากาศร่วมกัน: "คู่หู ขอต่อสาย Buddy-breather หน่อย ผมจะเข้าไป คุณอยู่ตรงที่ควันน้อยและคอยดึงเชือกไว้!"', zh: '💨 共享空气：“搭档，把你的应急呼吸器给我。我进去，你待在安全处拽住绳子！”' }, consequence: { en: '😱 Double Disaster. The buddy-breather hose gets snagged on a nail. Now both of you are trapped in a burning room with failing air. The RIT (Rapid Intervention Team) has to rescue you both, and the original victim dies anyway. Never compromise two lives for a high-risk one.', th: '😱 หายนะคูณสอง สาย Buddy-breather ไปเกี่ยวเข้ากับตะปู ตอนนี้คุณทั้งคู่ติดอยู่ในห้องที่ไฟไหม้และอากาศกำลังจะหมด ทีม RIT ต้องเข้ามาช่วยคุณทั้งสองคน และเหยื่อคนแรกก็ตายอยู่ดี อย่าเอาชีวิตสองคนไปเสี่ยงกับโอกาสรอดที่ต่ำมาก', zh: '😱 双重灾难。应急呼吸器软管被钉子钩住了。现在你们两个都困在燃烧的房间里，空气也快没了。快速干预小组（RIT）不得不营救你们两个，而最初的受害者还是死去了。永远不要为了一个高风险生命而搭上两条命。' }, stats: { competence: 10, ethics: 10, leadership: -50, innovation: 20 } }
        ]
    },

    {
        id: 'fir_035',
        text: {
            en: '🛤️ The Hazmat Tanker Leak: A train has derailed in a residential valley. Anhydrous ammonia is leaking—a giant white cloud is rolling toward 200 homes. The leak is a small valve. You have a Level A suit, but the "hot zone" is 120 degrees due to the sun and chemical reaction.',
            th: '🛤️ ถังก๊าซอันตรายรั่ว: รถไฟตกรางในหุบเขาที่มีบ้านเรือน แอมโมเนียปราศจากน้ำกำลังรั่ว—ควันขาวขนาดใหญ่กำลังลอยเข้าหาบ้าน 200 หลัง จุดรั่วคือวาล์วขนาดเล็ก คุณมีชุด Level A แต่ "โซนอันตราย" (Hot zone) ร้อนถึง 50 องศาเซลเซียสจากแดดและปฏิกิริยาเคมี',
            zh: '🛤️ 危化品罐车泄漏：一列火车在住宅区山谷出轨。无水氨正在泄漏——一团巨大的白云正滚向200户人家。泄漏点是一个小阀门。你穿着A级防化服，但由于阳光和化学反应，“热区”温度高达120华氏度（约49摄氏度）。'
        },
        options: [
            { id: 'A', text: { en: '🏃 Sprint-Fix: "I\'ll run in, fix the valve in 2 minutes, and get out before I heat-stroke. No backup needed, time is critical!"', th: '🏃 วิ่งไปซ่อม: "ผมจะวิ่งเข้าไป ซ่อมวาล์วใน 2 นาที แล้วออกมาให้ทันก่อนจะเป็นลมแดด ไม่ต้องมีทีมหนุน เวลาเป็นเรื่องสำคัญ!"', zh: '🏃 冲刺修复：“我冲进去，2分钟修好阀门，在热中风前出来。不需要备份人员，时间紧迫！”' }, consequence: { en: '💀 Heat Stroke Disaster. The Level A suit is a plastic oven. Inside 60 seconds, your heart rate hits 180. You collapse 10 feet from the valve. Because you had no backup, you lay there until the ammonia eats through your seals. Hazmat rules are written in blood.', th: '💀 หายนะลมแดด ชุด Level A คือเตาอบพลาสติกดีๆ นี่เอง ภายใน 60 วินาที หัวใจคุณเต้นถึง 180 ครั้งต่อนาที คุณล้มลงห่างจากวาล์วแค่ 10 ฟุต เพราะไม่มีคนหนุน คุณต้องนอนรอจนกว่าแอมโมเนียจะกัดกร่อนซีลชุดคุณ กฎของ Hazmat เขียนขึ้นด้วยเลือดจริงๆ', zh: '💀 热中风灾难。A级防化服就是一个塑料烤箱。60秒内，你的心率飙升至180。你在距离阀门10英尺处晕倒。因为你没有备用方案，你就躺在那里直到氨气腐蚀掉你的密封件。危化品规程是用鲜血换来的。' }, stats: { competence: 10, ethics: 30, leadership: -30, innovation: 0 } },
            { id: 'B', text: { en: '🛡️ Team Rotation: "Set up a 3-man rotation. 4 minutes in, 4 minutes out. I need a water spray to cool the tech during the fix."', th: '🛡️ เวียนกำลังพล: "จัดทีมเวียน 3 คน เข้า 4 นาที ออก 4 นาที ผมต้องการละอองน้ำคูลลิ่งเจ้าหน้าที่ระหว่างซ่อมด้วย"', zh: 'B 团队轮换：“设置3人轮换。进去4分钟，出来4分钟。我需要在修复过程中喷水冷却技术人员。”' }, consequence: { en: '✅ Textbook Management. The water spray knocks down the ammonia fumes and cools the suit. The 3rd rotation finally closes the valve. You saved the town without losing a single member of your team. Professionalism over ego.', th: '✅ การจัดการตามตำรา ละอองน้ำช่วยลดควันแอมโมเนียและลดอุณหภูมิชุด ทีมที่ 3 สามารถปิดวาล์วได้ในที่สุด คุณช่วยเมืองได้โดยไม่เสียทีมงานเลยแม้แต่คนเดียว ความเป็นมืออาชีพสำคัญกว่าอีโก้', zh: '✅ 教科书级管理。喷水压制了氨气烟雾并冷却了防化服。第3组轮换最终关闭了阀门。你在没有损失一名队员的情况下救了整个镇子。专业精神高于个人英雄主义。' }, stats: { competence: 50, ethics: 40, leadership: 50, innovation: 20 } },
            { id: 'C', text: { en: '💨 Massive Evacuation: "Forget the leak, it\'s too dangerous. Put all resources into moving those 200 families now!"', th: '💨 อพยพขนานใหญ่: "ลืมเรื่องรอยรั่วไปเลย มันอันตรายเกินไป ทุ่มกำลังทั้งหมดไปอพยพ 200 ครอบครัวออกมาเดี๋ยวนี้!"', zh: '💨 大规模疏疏散：“别管泄漏了，太危险。现在把所有资源都投入到疏散那200户家庭上！”' }, consequence: { en: '⚠️ Heavy Casualties. Ammonia moves faster than children and the elderly. You manage to move 50 families, but the remaining 150 suffer severe respiratory burns. By not addressing the source, you allowed a fixable problem to become a catastrophe.', th: '⚠️ ผู้บาดเจ็บจำนวนมาก แอมโมเนียเคลื่อนที่เร็วกว่าเด็กและคนชรา คุณอพยพได้ 50 ครอบครัว แต่ที่เหลืออีก 150 ครอบครัวได้รับบาดเจ็บสาหัสทางระบบหายใจ การไม่แก้ที่ต้นเหตุทำให้ปัญหาที่แก้ได้กลายเป็นหายนะ', zh: '⚠️ 重大伤亡。氨气扩散的速度比老人孩子逃命的速度快。你成功疏散了50户家庭，但剩下的150户由于呼吸道严重灼伤受难。由于没有处理源头，你让一个可以解决的问题演变成了灾难。' }, stats: { competence: 20, ethics: 40, leadership: 20, innovation: 0 } }
        ]
    },

    {
        id: 'fir_036',
        text: {
            en: '🤝 The Volunteer Conflict: You (a professional) are assigned as a liaison to a rural Volunteer department. They are using unsafe "cowboy" tactics—climbing ladders without harnesses and using old, frayed ropes. They tell you, "We’ve done it this way for 40 years, city boy. Get lost."',
            th: '🤝 ขัดแย้งกับอาสา: คุณ (ฝ่ายอาชีพ) ถูกส่งไปประสานงานกับหน่วยอาสาในชนบท พวกเขาใช้วิธีที่อันตรายแบบ "คาวบอย"—ปีนบันไดโดยไม่ใส่ชุดฮาร์เนสและใช้เชือกเก่าๆ ที่เปื่อยแล้ว พวกเขาบอกคุณว่า "เราทำแบบนี้มา 40 ปีแล้วไอ้หนุ่มเมืองกรุง ไปไกลๆ ไป"',
            zh: '🤝 志愿者冲突：你（一名职业消防员）被派去担任一个农村志愿消防部门的联络员。他们正在使用不安全的“牛仔”战术——不带安全带爬云梯，使用磨损严重的老旧绳索。他们告诉你：“城里娃，我们40年来一直是这么干的。滚一边去。”'
        },
        options: [
            { id: 'A', text: { en: '👮 Pull Rank: "I\'m the assigned liaison. Stop operations immediately or I\'ll have the Fire Marshal shut down this station!"', th: '👮 ใช้อำนาจ: "ผมได้รับแต่งตั้งเป็นผู้ประสานงาน หยุดปฏิบัติงานเดี๋ยวนี้ ไม่อย่างนั้นผมจะให้ Fire Marshal สั่งปิดสถานีนี้ซะ!"', zh: '👮 动用职权：“我是被指派的联络员。立即停止行动，否则我让消防局长关了这间消防站！”' }, consequence: { en: '❌ Total Alienation. They ignore you and walk away. When the big fire hits that night, they refuse to talk to you on the radio. You failed to influence safety because you led with ego rather than relationship.', th: '❌ ถูกโดดเดี่ยวโดยสิ้นเชิง พวกเขาเมินคุณและเดินหนีไป พอเกิดไฟไหม้ใหญ่คืนนั้น พวกเขาไม่ยอมคุยกับคุณผ่านวิทยุ คุณล้มเหลวในการสร้างความปลอดภัยเพราะคุณนำด้วยอีโก้แทนที่จะเป็นการสร้างความสัมพันธ์', zh: '❌ 彻底疏远。他们无视你并走开了。当那天晚上发生大火时，他们拒绝在无线电中与你交谈。你未能影响安全，因为你用傲慢而不是关系来领导。' }, stats: { competence: 20, ethics: 20, leadership: -40, innovation: 0 } },
            { id: 'B', text: { en: '🛠️ Lead by Example: "I hear you. Hey, I brought some of our new thermal cameras and modern harnesses. Want to see how easy they make the job?"', th: '🛠️ ทำให้ดูเป็นตัวอย่าง: "ผมเข้าใจครับพี่ เออ พี่ครับ ผมเอากล้องตรวจจับความร้อนตัวใหม่กับชุดฮาร์เนสแบบใหม่มาด้วย อยากลองดูไหมครับว่ามันช่วยให้งานง่ายขึ้นยังไง?"', zh: 'B 言传身教：“我懂。嘿，我带了一些我们新的热像仪和现代安全带。想看看它们能让工作变得多简单吗？”' }, consequence: { en: '✅ Cultural Shift. By showing "value" rather than "rules," you win them over. They start asking to use the new gear. You upgraded their safety culture without a single argument. True leadership is influence.', th: '✅ เปลี่ยนแปลงวัฒนธรรม การแสดงให้เห็น "คุณค่า" มากกว่าการเน้น "กฎ" ช่วยให้คุณชนะใจพวกเขา พวกเขาเริ่มขอใช้อุปกรณ์ใหม่ คุณยกระดับความปลอดภัยของพวกเขาได้โดยไม่มีการเถียงกันสักคำ ภาวะผู้นำที่แท้จริงคือการสร้างอิทธิพล', zh: '✅ 文化转变。通过展示“价值”而不是“规则”，你赢得了他们的心。他们开始请求使用新装备。你在没有任何争论的情况下升级了他们的安全文化。真正的领导力就是影响力。' }, stats: { competence: 40, ethics: 30, leadership: 60, innovation: 40 } },
            { id: 'C', text: { en: '🤐 Silent Witness: "It’s their town. If they want to risk their necks, that’s on them. I’ll just document it and stay safe."', th: '🤐 เพิกเฉย: "มันคือเมืองของพวกเขา ถ้าอยากเสี่ยงตายก็เรื่องของเขา ผมจะแค่จดบันทึกไว้แล้วดูแลตัวเองให้ปลอดภัยพอ"', zh: 'C 沉默的证人：“这是他们的地盘。如果他们想玩命，那是他们的事。我只负责记录，确保自己安全。”' }, consequence: { en: '💀 Avoidable Injury. An hour later, a volunteer falls when a frayed rope snaps. He is paralyzed. You knew the risk and said nothing. Silence in the face of danger is a failure of your oath to protect life.', th: '💀 การบาดเจ็บที่ป้องกันได้ หนึ่งชั่วโมงต่อมา อาสาคนหนึ่งร่วงลงมาเพราะเชือกเปื่อยขาด เขาเป็นอัมพาต คุณรู้ถึงความเสี่ยงแต่ไม่พูดอะไร การเงียบเมื่อเห็นภัยอันตรายคือความล้มเหลวต่อคำสัตย์ปฏิญาณที่จะปกป้องชีวิต', zh: '💀 可避免的伤害。一小时后，一名志愿者因磨损的绳索断裂而坠落。他瘫痪了。你明知风险却保持沉默。面对危险保持沉默是对保护生命誓言的背叛。' }, stats: { competence: 20, ethics: -40, leadership: -20, innovation: 0 } }
        ]
    },

    {
        id: 'fir_037',
        text: {
            en: '🚨 The Fire Inspection Dilemma: You find a popular local nightclub has blocked its emergency exits with sound equipment. The owner is the Fire Chief’s brother-in-law. He says, "Come on, it’s just for one sold-out show. Don\'t be a jerk."',
            th: '🚨 ปัญหาการตรวจความปลอดภัย: คุณพบว่าไนต์คลับชื่อดังปิดตายประตูหนีไฟด้วยอุปกรณ์เครื่องเสียง เจ้าของร้านคือพี่เขยของหัวหน้าดับเพลิง เขาบอกคุณว่า "น่าพี่ แค่คืนเดียวเองงานขายตั๋วหมดแล้ว อย่าเข้มงวดนักเลย"',
            zh: '🚨 消防检查两难：你发现一家倍受欢迎的当地夜总会用音响设备阻塞了紧急出口。老板是消防局长的小舅子。他说：“拜托，就这一场售罄演出。别那么死脑筋。”'
        },
        options: [
            { id: 'A', text: { en: '👮 Immediate Closure: "Exits blocked means no show. Clear the equipment now or I\'m pulling the occupancy permit!"', th: '👮 สั่งปิดทันที: "ประตูหนีไฟถูกบล็อกคือห้ามแสดง ย้ายของเดี๋ยวนี้ไม่อย่างนั้นผมยึดใบอนุญาตใช้อาคาร!"', zh: '👮 立即关停：“出口被堵，演出取消。现在就把设备搬走，否则我吊销你们的使用证！”' }, consequence: { en: '✅ Life Safety Priority. The owner is furious and calls the Chief. The Chief visits and, to your surprise, backs you up. "My brother-in-law is an idiot," the Chief says. You prevented a potential "Station Nightclub" fire disaster.', th: '✅ ความปลอดภัยของชีวิตต้องมาก่อน เจ้าของโมโหและโทรหาหัวหน้าใหญ่ หัวหน้าใหญ่มาถึงและที่น่าประหลาดใจคือเขาหนุนหลังคุณ "พี่เขยฉันมันโง่เอง" หัวหน้ากล่าว คุณได้ป้องกันหายนะไฟไหม้ที่อาจเกิดขึ้นได้', zh: '✅ 生命安全至上。老板勃然大怒并给局长打电话。局长赶到后，出乎你意料的是，他支持了你。局长说：“我那小舅子是个白痴。”你防止了一场潜在的“车站夜总会”式的火灾惨剧。' }, stats: { competence: 40, ethics: 60, leadership: 50, innovation: 0 } },
            { id: 'B', text: { en: '🤝 Compromise: "Okay, I\'ll let it slide this once, but I\'m staying here for the whole show as a fire watch."', th: '🤝 ยอมหย่อนตาม: "โอเค ผมจะยอมให้ครั้งเดียว แต่ผมจะอยู่เฝ้าที่นี่ตลอดงานในฐานะเจ้าหน้าที่เฝ้าระวังไฟ"', zh: '🤝 妥协：“好吧，破例这一次，但整场演出我会待在这里担任消防警戒。”' }, consequence: { en: '⚠️ Close Call. A minor electrical spark occurs. Because you were there, you put it out with an extinguisher instantly. However, you lost the respect of the inspection team for showing favoritism. Regulations are there for when you *aren\'t* there.', th: '⚠️ เกือบไปแล้ว เกิดประกายไฟจากไฟฟ้าเล็กน้อย เพราะคุณอยู่ที่นั่นคุณเลยดับมันได้ทันที แต่คุณเสียความเคารพจากทีมตรวจเพราะการเลือกปฏิบัติ', zh: '⚠️ 虚惊一场。发生了一点小电火花。因为你在场，你立即用灭火器扑灭了它。然而，你由于表现出偏袒而失去了检查小组的尊重。规章制度是为了当你*不在*场时发挥作用的。' }, stats: { competence: 30, ethics: 10, leadership: 20, innovation: 20 } },
            { id: 'C', text: { en: '🤐 Report to the Chief: "I\'ll let the Chief handle his own family. I\'m not getting in the middle of this."', th: '🤐 รายงานหัวหน้าใหญ่: "ให้หัวหน้าใหญ่จัดการครอบครัวเขาเองเถอะ ผมไม่ขอเข้าไปยุ่งเกี่ยวด้วย"', zh: 'C 报告局长：“让局长自己处理家务事。我不想掺和进这种关系里。”' }, consequence: { en: '💀 Tragic Omission. You leave. A fire breaks out 2 hours later. 12 people die because they couldn\'t reach the blocked exit. You are fired and face criminal negligence charges for failing to enforce a clear violation. Ethics is not about family.', th: '💀 ความเพิกเฉยที่น่าสลด คุณเดินหนีไป ไฟไหม้เกิดขึ้นใน 2 ชั่วโมงต่อมา มี 12 คนตายเพราะเข้าถึงทางหนีไฟที่ถูกบล็อกไม่ได้ คุณถูกไล่ออกและถูกดำเนินคดีอาญาฐานประมาทเลินเล่อจากการละเลยการฝ่าฝืนที่ชัดเจน', zh: '💀 惨痛的玩忽职守。你离开了。2小时后发生了火灾。12人因为无法到达被封堵的出口而死亡。你被解雇，并因未能执法明显的违规行为而面临刑事过失指控。伦理不关乎亲情。' }, stats: { competence: 10, ethics: -60, leadership: -40, innovation: 0 } }
        ]
    },

    {
        id: 'fir_038',
        text: {
            en: '🏗️ The Trench Collapse: A construction worker is buried to his waist in a 10-foot deep trench. The dirt is "sugar sand" (unstable). Every time he moves, more dirt falls in. A heavy excavator is parked right on the edge of the trench, vibrating the ground.',
            th: '🏗️ ดินถล่มในร่องลึก: คนงานก่อสร้างถูกดินฝังถึงเอวในร่องลึกลูก 10 ฟุต ดินเป็นแบบ "ทรายลื่น" (ไม่มั่นคง) ทุกครั้งที่เขาขยับ ดินจะยิ่งถล่มลงมา รถขุดดินขนาดใหญ่จอดอยู่ริมขอบร่องพอดี ทำให้พื้นสั่นสะเทือน',
            zh: '🏗️ 沟渠坍塌：一名建筑工人被埋在10英尺深的沟渠里，泥土没过腰部。泥土是“糖沙”（极不稳定）。他每动一下，就有更多的土掉下来。一台重型挖掘机就停在沟渠边缘，震动着地面。'
        },
        options: [
            { id: 'A', text: { en: '👷 Clear the Edge: "Stop that excavator! Move it 50 feet away now. Everyone get back from the edge! We need shoring panels before anyone goes down!"', th: '👷 เคลียร์พื้นที่ขอบร่อง: "หยุดรถขุดนั่น! ถอยมันออกไป 50 ฟุตเดี๋ยวนี้ ทุกคนถอยห่างจากขอบร่อง! เราต้องใช้แผ่นค้ำยันก่อนจะส่งคนลงไป!"', zh: '👷 清理边缘：“停掉那台挖掘机！把它挪到50英尺外。所有人退离边缘！在任何人下去前，我们需要支护板！”' }, consequence: { en: '✅ Technical Proficiency. You recognize that the "vibration" and "lip-load" (the weight of the excavator) were the biggest threats. You stabilize the scene first. The rescue takes 2 hours, but it’s safe. The worker survives. Precision over speed in trench rescue.', th: '✅ ความเชี่ยวชาญทางเทคนิค คุณตระหนักว่า "แรงสั่นสะเทือน" และ "น้ำหนักกดทับที่ขอบ" คือภัยคุกคามที่ใหญ่ที่สุด คุณคุมที่เกิดเหตุให้มั่นคงก่อน การกู้ภัยใช้เวลา 2 ชั่วโมงแต่ปลอดภัย', zh: '✅ 技术精湛。你意识到“震动”和“边缘负载”（挖掘机的重量）是最大的威胁。你先稳定了现场。救援花了2个小时，但很安全。工人获救了。在沟渠救援中，精准高于速度。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 10 } },
            { id: 'B', text: { en: '🧗 Immediate Entry: "He\'s sinking! I\'m jumping in with a shovel to dig him out before he suffocates!"', th: '🧗 ลงไปช่วยทันที: "เขากำลังจม! ผมจะกระโดดลงไปพร้อมพลั่วเพื่อขุดเขาออกมาก่อนจะขาดใจตาย!"', zh: '🧗 立即进入：“他在下沉！我拿着铲子跳过去，在他窒息前把他挖出来！”' }, consequence: { en: '😱 Double Entrapment. As soon as you jump in, your weight causes a secondary collapse. Now you are buried to your neck, and the original victim is completely covered. You became part of the problem. Trench rescue is the most dangerous discipline for a reason.', th: '😱 ติดอยู่ข้างในทั้งคู่ ทันทีที่คุณกระโดดลงไป น้ำหนักตัวคุณทำให้ดินถล่มซ้ำ ตอนนี้คุณถูกฝังถึงคอ และเหยื่อคนแรกถูกดินกลบมิด คุณกลายเป็นส่วนหนึ่งของปัญหาไปแล้ว', zh: '😱 双重被困。你一跳进去，你的重量就导致了二次坍塌。现在你也被埋到了脖子，而最初的受害者被完全掩埋了。你成了问题的一部分。沟渠救援之所以是最危险的学科是有原因的。' }, stats: { competence: 10, ethics: 20, leadership: -30, innovation: 0 } },
            { id: 'C', text: { en: '🚜 Use the Excavator: "Tell the operator to use the bucket to gently lift the worker out by his harness!"', th: '🚜ใช้รถขุดช่วย: "บอกคนขับรถขุดให้ใช้บุ้งกี๋ค่อยๆ เกี่ยวชุดฮาร์เนสยกตัวคนงานขึ้นมา!"', zh: 'C 使用挖掘机：“告诉操作员用铲斗通过安全带轻轻地把工人拎出来！”' }, consequence: { en: '💀 Gruesome Injury. Excavators are not precision rescue tools. The bucket shifts a small amount of dirt which causes a massive cave-in, crushing the worker’s pelvis against the trench wall. You tried to use a sledgehammer for a surgery.', th: '💀 บาดเจ็บสาหัส รถขุดไม่ใช่เครื่องมือกู้ภัยที่แม่นยำ บุ้งกี๋ทำดินเคลื่อนขยับนิดเดียวก็ส่งผลให้ดินถล่มทับครั้งใหญ่ บีบอัดกระดูกเชิงกรานของคนงานติดกับผนังร่อง', zh: '💀 惨剧。挖掘机不是精密救援工具。铲斗移动了一点泥土，导致了大规模塌方，将工人的骨盆挤向沟壁。你这是在用大锤做手术。' }, stats: { competence: 20, ethics: 10, leadership: 10, innovation: 30 } }
        ]
    },
    {
        id: 'fir_039',
        text: {
            en: '🚁 The Helicopter Landing Zone (LZ): An Air-Med helicopter is coming to pick up a burn victim. The best LZ is a dusty field next to the fire. You are the LZ Coordinator. You see power lines to the North and loose debris in the field. The pilot asks, "Is the LZ secure for landing?"',
            th: '🚁 ปฏิบัติการลานจอดเฮลิคอปเตอร์: เฮลิคอปเตอร์พยาบาลกำลังจะมารับผู้ป่วยถูกไฟลวก จุดจอดที่ดีที่สุดคือทุ่งหญ้าที่มีฝุ่นเยอะข้างที่เกิดเหตุไฟไหม้ คุณคือผู้ประสานงานลานจอด คุณเห็นสายไฟทางทิศเหนือและมีเศษขยะกระจัดกระจายในทุ่ง นักบินถามว่า "ลานจอดปลอดภัยสำหรับการลงจอดไหม?"',
            zh: '🚁 直升机着陆区（LZ）：一架医疗直升机正赶来接载一名烧伤受害者。最佳着陆区是火场旁边的一块多尘的田地。你是着陆区协调员。你看到北面有电线，田地里有松散的碎片。飞行员问：“着陆区安全吗？”'
        },
        options: [
            { id: 'A', text: { en: '✅ Secure and Land: "LZ is secure. Land at your discretion. We’ll keep the area clear."', th: '✅ ยืนยันความปลอดภัย: "ลานจอดปลอดภัย ลงจอดได้ตามดุลยพินิจ เราจะเคลียร์พื้นที่ไว้ให้"', zh: '✅ 安全并着陆：“着陆区安全。请酌情着陆。我们将保持该区域清空。”' }, consequence: { en: '😱 Brown-out Crash. As the helicopter nears the ground, the rotor wash kicks up a massive dust cloud (brown-out). The pilot loses sight of the power lines and the ground. The rotor clips a wire and the helicopter crashes. You failed to account for "environmental hazards" beyond just the perimeter.', th: '😱 อุบัติเหตุฝุ่นตลบ (Brown-out) เมื่อเฮลิคอปเตอร์ใกล้พื้น แรงลมจากใบพัดทำให้ฝุ่นพุ่งกระจายจนมองอะไรไม่เห็น นักบินมองไม่เห็นสายไฟและพื้น ใบพัดไปเกี่ยวสายไฟทำให้เครื่องตก คุณล้มเหลวในการประเมิน "ภัยจากสภาพแวดล้อม" ที่นอกเหนือไปจากแค่พื้นที่จอด', zh: '😱 尘暴坠毁。当直升机接近地面时，旋翼气流卷起了巨大的尘云（尘暴）。飞行员看不清电线和地面。旋翼刮到了电线，直升机坠毁。你未能考虑到周界以外的“环境危害”。' }, stats: { competence: 10, ethics: 20, leadership: 10, innovation: 0 } },
            { id: 'B', text: { en: '💦 Wet Down the LZ: "Wait 2 minutes. We are going to wet down the field with a hose to kill the dust. And be advised: Power lines North side!"', th: '💦 ฉีดน้ำพรมพื้น: "รอ 2 นาที เราจะฉีดน้ำพรมพื้นที่เพื่อลดฝุ่น และโปรดทราบ: มีสายไฟทางทิศเหนือ!"', zh: 'B 喷水降尘：“请等2分钟。我们将用自来水软管弄湿田地以压住灰尘。并请注意：北侧有电线！”' }, consequence: { en: '✅ Professional LZ Management. By wetting the dust, you prevent a brown-out. Your warning about the power lines gives the pilot a crucial reference point. The victim is lifted safely. In aviation-related rescues, details save lives.', th: '✅ การจัดการลานจอดมืออาชีพ การฉีดน้ำช่วยป้องกันฝุ่นตลบ คำเตือนเรื่องสายไฟช่วยให้นักบินมีจุดอ้างอิงที่สำคัญ ผู้ป่วยถูกส่งตัวได้สำเร็จอย่างปลอดภัย ในงานกู้ภัยที่เกี่ยวกับอากาศยาน รายละเอียดปลีกย่อยคือสิ่งช่วยชีวิต', zh: '✅ 专业着陆区管理。通过喷水降尘，你防止了尘暴的发生。你对电线的警告为飞行员提供了一个关键的参考点。受害者被安全吊起。在与航空相关的救援中，细节决定生命。' }, stats: { competence: 50, ethics: 40, leadership: 50, innovation: 20 } },
            { id: 'C', text: { en: '🚜 Relocate LZ: "Negative. Field is too dusty and has power lines. Move the LZ to the highway 1/2 mile away. We will transport the victim by ambulance there."', th: '🚜 เปลี่ยนจุดจอด: "ไม่อนุญาต พื้นที่ฝุ่นเยอะและมีสายไฟ ให้เปลี่ยนจุดจอดไปที่ถนนทางหลวงห่างออกไปครึ่งไมล์ เราจะใช้รถพยาบาลเคลื่อนย้ายผู้ป่วยไปที่นั่นแทน"', zh: 'C 重新定位着陆区：“不行。田地粉尘太大且有电线。到着路区移到半英里外的公路上。我们将用救护车把受害者运过去。”' }, consequence: { en: '⚠️ Delayed Care. The extra 10 minutes spent loading the victim into an ambulance and driving to the second LZ results in the victim going into shock. They survive, but with a harder recovery. You were overly cautious when a field-level fix was possible.', th: '⚠️ การรักษาล่าช้า เวลาที่เสียไปเพิ่ม 10 นาทีในการย้ายผู้ป่วยขึ้นรถพยาบาลและขับไปจุดที่สอง ทำให้ผู้ป่วยเกิดอาการช็อก แม้จะรอดชีวิตแต่ฟื้นตัวยากขึ้น คุณระแวงเกินไปทั้งที่สามารถแก้ไขปัญหาในพื้นที่ได้', zh: '⚠️ 延迟救治。将受害者装入救护车并开车前往第二个着陆区多花了10分钟，导致受害者陷入休克。他们活了下来，但康复过程更加艰难。当你本来可以现场解决问题时，你表现得过度谨慎了。' }, stats: { competence: 30, ethics: 30, leadership: 30, innovation: 0 } }
        ]
    },

    {
        id: 'fir_040',
        text: {
            en: '🏚️ The Hoarder Fire: You are fighting a fire in a house filled with "heavy content" (hoarding). There are stacks of newspapers 6 feet high. You can\'t see the floor. Your boot suddenly feels soft. You suspect a floor-hole or structural weakness. Your partner is pushing forward.',
            th: '🏚️ ไฟไหม้ในบ้านนักสะสม: คุณกำลังดับไฟในบ้านที่เต็มไปด้วยขยะและสิ่งของสะสมจำนวนมหาศาล มีกองหนังสือพิมพ์สูงถึง 6 ฟุต คุณมองไม่เห็นพื้นเลย จู่ๆ เท้าคุณรู้สึกว่าพื้นนิ่มๆ คุณสงสัยว่าอาจเป็นรูกลางพื้นหรือโครงสร้างอ่อนแอ แต่คู่หูกำลังดันไปข้างหน้า',
            zh: '🏚️ 囤积者之家火灾：你正在一个堆满“重物”（囤积物）的房子里灭火。报纸堆了6英尺高。你看不到地板。你的靴子突然感觉陷了下去。你怀疑地板有洞或结构脆弱。你的搭档正向前推进。'
        },
        options: [
            { id: 'A', text: { en: '🛑 Halt and Sound: "Stop! Sound the floor! Don\'t move until we confirm we have a stable path!"', th: '🛑 หยุดและเดินสุ่มเช็คพื้น: "หยุด! เช็คพื้นก่อน! ห้ามขยับจนกว่าจะยืนยันว่าพื้นมั่นคง!"', zh: '🛑 停止并试探：“停！试探地板！在确定路径稳定前别动！”' }, consequence: { en: '✅ Life-Saving Intuition. Your partner hits the floor with an axe and it goes right through. A massive hole in the joists was hidden by trash. You find an alternate path and successfully reach the seed of the fire. In hoarding fires, the "traps" are constant.', th: '✅ สัญชาตญาณช่วยชีวิต คู่หูของคุณใช้ขวานกระทุ้งพื้นแล้วมันทะลุลงไปเลย มีรูขนาดใหญ่ที่คานพื้นถูกขยะบังไว้ คุณหาทางเดินใหม่และไปถึงต้นเพลิงได้สำเร็จ ในบ้านนักสะสม "กับดัก" มีอยู่ทุกที่', zh: '✅ 救命的直觉。你的搭档用斧头击打地板，斧头直接穿了过去。碎片下面遮盖着一个巨大的地洞。你找到了另一条路径并成功到达了火源。在囤积者之家的火灾中，“陷阱”无处不在。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 10 } },
            { id: 'B', text: { en: '🏃 Power Through: "It\'s just a stack of papers. Keep moving, we need to hit the fire before it hits the roof!"', th: '🏃 ลุยต่อ: "มันก็แค่กองกระดาษน่ะ เดินต่อเถอะ เราต้องดับไฟให้ได้ก่อนมันจะลามไปถึงหลังคา!"', zh: '🏃 强攻：“那只是一堆报纸。继续前进，我们得在火烧到屋顶前扑灭它！”' }, consequence: { en: '😱 The Plunge. Your partner takes one more step and falls through the floor into the basement fire below. You spend the next 20 minutes in a desperate Mayday rescue instead of firefighting. Your partner suffers severe burns. Speed killed.', th: '😱 ร่วงทะลุพื้น คู่หูของคุณก้าวไปอีกก้าวแล้วร่วงทะลุพื้นลงไปในห้องใต้ดินที่ไฟกำลังลุกไหม้ คุณต้องใช้เวลา 20 นาทีในการกู้ภัยฉุกเฉินแทนที่จะระงับเหตุ คู่หูถูกไฟคลอกรุนแรง ความเร่งรีบทำให้เกิดความสูญเสีย', zh: '😱 坠落。你的搭档又往前走了一步，掉进了下面正在燃烧的地下室。接下来的20分钟你都在进行拼命的求救营救，而不是灭火。你的搭档遭受了严重的烧伤。欲速则不达。' }, stats: { competence: 10, ethics: 20, leadership: -40, innovation: 0 } },
            { id: 'C', text: { en: '🛶 Crawl: "Get low and crawl on your belly to distribute weight. Use the newspaper stacks for stability."', th: '🛶 หมอบคลาน: "หมอบต่ำแล้วคลานไปเพื่อกระจายน้ำหนัก ใช้กองหนังสือพิมพ์ช่วยพยุงตัว"', zh: 'C 爬行：“趴低身体爬行以分散重量。利用报纸堆保持稳定。”' }, consequence: { en: '⚠️ Dangerous Logic. Distributing weight helps, but newspapers add thousands of pounds of "dead load" to an already weak floor. You both make it to the fire, but the floor collapses shortly after you exit. You were "lucky" rather than "safe."', th: '⚠️ ตรรกะแบบเสี่ยงๆ การกระจายน้ำหนักช่วยได้บ้าง แต่กองหนังสือพิมพ์คือน้ำหนักมหาศาลที่กดทับพื้นซึ่งอ่อนแออยู่แล้ว คุณทั้งคู่ดับไฟได้ แต่พื้นถล่มลงมาทันทีหลังจากคุณออกมา คุณก็แค่ "โชคดี" ไม่ใช่ "ปลอดภัย"', zh: '⚠️ 危险的逻辑。分散重量有所帮助，但报纸给本已脆弱的地板增加了数千磅的“恒载”。你们两个都赶到了火场，但在你们撤离后不久地板就塌了。你只是“运气好”而不是“安全”。' }, stats: { competence: 30, ethics: 30, leadership: 20, innovation: 30 } }
        ]
    },

    {
        id: 'fir_041',
        text: {
            en: '⛽ The Overdosing Driver: A car has smashed into a gas pump. The emergency shutoff worked, but fuel is pooled under the car. The driver is slumped over, unconscious, likely an opioid overdose (pinpoint pupils). Vapor is rising. The car door is locked.',
            th: '⛽ คนขับเสพยาเกินขนาด: รถพยาบาลพุ่งชนหัวจ่ายน้ำมัน วาล์วปิดฉุกเฉินทำงานแล้วแต่ยังมีน้ำมันนองอยู่ใต้รถ คนขับฟุบแหมดไม่ได้สติ ดูเหมือนจะเสพฝิ่นเกินขนาด (รูม่านตาหดเล็ก) ควันระเหยเริ่มลอยขึ้น และประตูรถล็อคอยู่',
            zh: '⛽ 过量吸毒的司机：一辆车撞上了加油机。紧急切断装置已启动，但车下方有燃油积聚。司机瘫软在地，处于昏迷状态，很可能是阿片类药物过量（瞳孔缩小）。油汽正在升起。车门锁着。'
        },
        options: [
            { id: 'A', text: { en: '🔨 Smash and Drag: "Break the window and pull him out now! The fuel could ignite any second!"', th: '🔨 ทุบกระจกแล้วลากออกมา: "ทุบกระจกแล้วลากเขาออกมาเดี๋ยวนี้! น้ำมันอาจจะติดไฟได้ทุกเมื่อ!"', zh: '🔨 砸窗并拖拽：“打破车门窗，马上把他拉出来！燃油随时可能点燃！”' }, consequence: { en: '✅ Rapid Rescue. You drag him 100 feet away just as a spark from the hot engine ignites the pool. The car becomes a fireball. You saved a life by prioritizing speed over secondary medical assessment.', th: '✅ กู้ภัยรวดเร็ว คุณลากเขาออกมาได้ 100 ฟุตพอดีกับที่ประกายไฟจากเครื่องยนต์ที่ร้อนจัดทำให้น้ำมันติดไฟ รถกลายเป็นลูกไฟยักษ์ คุณช่วยชีวิตคนไว้ได้โดยจัดลำดับความสำคัญของความเร็วเหนือกว่าการประเมินทางการแพทย์ขั้นที่สอง', zh: '✅ 快速营救。你刚把他拖到100英尺外，热引擎发出的火花就点燃了积油。汽车变成了一个火球。你通过将速度置于二次医疗评估之上挽救了一个生命。' }, stats: { competence: 50, ethics: 40, leadership: 30, innovation: 0 } },
            { id: 'B', text: { en: '💉 Narcan First: "Give him the Narcan through the cracked window! If he wakes up, we don\'t have to drag him and risk a needle stick!"', th: '💉 ให้ยาแก้ยาเสพติดก่อน: "พ่น Narcan ให้เขาทางช่องหน้าต่าง! ถ้าเขาตื่น เราจะได้ไม่ต้องลากเขาแล้วเสี่ยงโดนเข็มตำ!"', zh: 'B 先用纳洛酮：“通过车窗缝隙给他注射纳洛酮！如果他醒了，我们就不用拖他，还能避免针刺风险！”' }, consequence: { en: '💀 Fatal Delay. Narcan takes 2-3 minutes to work. In that time, the fuel ignites. Because you were focused on the overdose rather than the immediate fire threat, the driver is burned alive in the car. Wrong priority.', th: '💀 ความล่าช้าที่อันตราย ยา Narcan ใช้เวลา 2-3 นาทีถึงจะออกฤทธิ์ ในระหว่างนั้นน้ำมันเกิดติดไฟขึ้นมา เพราะคุณมัวแต่สนใจเรื่องเสพยาเกินขนาดมากกว่าภัยไฟไหม้ที่อยู่ตรงหน้า คนขับเลยถูกเผาทั้งเป็นในรถ คุณจัดลำดับความสำคัญผิดไป', zh: '💀 致命延迟。纳洛酮需要2-3分钟才能见效。在那段时间里，燃油起火了。因为你专注于过量用药而忽略了眼前的火灾威胁，司机在车内被活活烧死。优先级错了。' }, stats: { competence: 10, ethics: 10, leadership: -30, innovation: 20 } },
            { id: 'C', text: { en: '🌊 Foam Blanket: "Cover the car and the pool with foam first, then work on the driver safely."', th: '🌊 ฉีดโฟมคลุม: "ฉีดโฟมคลุมรถและจุดที่น้ำมันนองก่อน แล้วค่อยช่วยคนขับอย่างปลอดภัย"', zh: 'C 泡沫覆盖：“先用泡沫覆盖汽车和积油，然后再安全地营救司机。”' }, consequence: { en: '⚠️ Technical Success, Clinical Risk. The foam prevents the fire, but by the time you reach the driver, he has stopped breathing due to the overdose. You prevented the fire but nearly lost the patient to respiratory failure. A mixed result.', th: '⚠️ สำเร็จทางเทคนิคแต่เสี่ยงทางการแพทย์ โฟมช่วยป้องกันไฟได้ แต่กว่าจะถึงตัวคนขับ เขาก็หยุดหายใจเพราะเสพยาเกินขนาดไปแล้ว คุณป้องกันไฟได้แต่เกือบเสียคนไข้ไปเพราะระบบหายใจล้มเหลว เป็นผลลัพธ์ที่ก้ำกึ่ง', zh: '⚠️ 技术成功，但存在临床风险。泡沫阻火了，但当你救出司机时，他已因过量用药停止了呼吸。你防止了火灾，但险些让病人死于呼吸衰竭。结果好坏参半。' }, stats: { competence: 30, ethics: 30, leadership: 20, innovation: 40 } }
        ]
    },

    {
        id: 'fir_042',
        text: {
            en: '🏭 The Industrial Ammonia Leak: An ice cream factory has a massive ammonia leak. The computer control is fried. You need to manually close the master valve in the basement. It\'s dark, flooded with waist-high water, and filled with toxic fumes. You have 15 minutes of air.',
            th: '🏭 ก๊าซแอมโมเนียรั่วในโรงงาน: โรงงานไอศกรีมมีก๊าซแอมโมเนียรั่วไหลขนานใหญ่ ระบบคอมพิวเตอร์พังเสียหาย คุณต้องลงไปปิดวาล์วหลักด้วยมือในห้องใต้ดิน มันทั้งมืด มีน้ำท่วมสูงถึงเอว และเต็มไปด้วยไอพิษ คุณมีอากาศเหลือแค่ 15 นาที',
            zh: '🏭 工业氨气泄漏：一家冰淇淋工厂发生了大规模氨气泄漏。电脑控制系统损坏。你需要手动关闭地下室的总阀。那里漆黑一片，积水齐腰，且充满了有毒烟雾。你只有15分钟的空气。'
        },
        options: [
            { id: 'A', text: { en: '🧠 Map Study: "I’m not going in blind. Bring me the facility manager and the blueprints. Point exactly to the valve."', th: '🧠 ศึกษาแผนผัง: "ผมจะไม่สุ่มเข้าไปมั่วๆ ไปเรียกผู้จัดการโรงงานและเอาพิมพ์เขียวมาให้ผม ชี้ให้ชัดว่าวาล์วอยู่ตรงไหน"', zh: '🧠 地图研究：“我不会盲目进去。把工厂经理找来，拿上蓝图。准确指出阀门的位置。”' }, consequence: { en: '✅ Strategic Precision. Spending 3 minutes on the map saves you 10 minutes of searching in the toxic dark. You walk straight to the valve, close it, and exit with 2 minutes of air to spare. Mental prep is faster than physical searching.', th: '✅ ความแม่นยำทางกลยุทธ์ การเสียเวลา 3 นาทีดูแผนที่ช่วยลดเวลาหาของในความมืดที่เต็มไปด้วยพิษไปได้ถึง 10 นาที คุณเดินตรงไปที่วาล์ว ปิดมัน และออกมาโดยเหลืออากาศอีก 2 นาที การเตรียมใจเร็วกว่าการสุ่มหาด้วยแรงกาย', zh: '✅ 战略精准。在地图上花3分钟为你节省了在有毒黑暗中搜索的10分钟。你直奔阀门，将其关闭，并在空气还剩2分钟时撤离。心理准备比体力搜索更快。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 20 } },
            { id: 'B', text: { en: '🏊 Immediate Entry: "Time is running out! I\'ll find it! Just keep the radio clear!"', th: '🏊 เข้าไปทันที: "เวลาจะหมดแล้ว! เดี๋ยวผมหาเอง! เคลียร์วิทยุให้ว่างไว้ด้วย!"', zh: 'B 立即进入：“没时间了！我会找到它的！保持无线电畅通！”' }, consequence: { en: '😱 Lost in the Dark. Without a clear plan, you get disoriented in the waist-high water. You run out of air before finding the valve. RIT has to drag you out. The leak continues for another hour, forcing an evacuation of the whole neighborhood.', th: '😱 หลงทางในความมืด หากไม่มีแผนที่ชัดเจน คุณจะสับสนในน้ำที่สูงถึงเอว คุณอากาศหมดก่อนจะหาวาล์วเจอ ทีม RIT ต้องลากคุณออกมา ก๊าซรั่วไหลต่ออีกชั่วโมง บังคับให้ต้องอพยพคนทั้งละแวกบ้าน', zh: '😱 在黑暗中迷失。由于没有明确的计划，你在齐腰深的水中失去了方向。你在找到阀门前耗尽了空气。RIT不得不把你拖出来。泄漏又持续了一个小时，迫使整个街区的人员撤离。' }, stats: { competence: 10, ethics: 20, leadership: 10, innovation: 0 } },
            { id: 'C', text: { en: '🤖 Drone Deployment: "Send in the waterproof HAZMAT drone to find the valve first, then I\'ll go in and turn it."', th: '🤖 ใช้โดรนกู้ภัย: "ส่งโดรน HAZMAT กันน้ำเข้าไปหาวาล์วก่อน พอเจอแล้วผมค่อยลงไปหมุนปิดมัน"', zh: 'C 部署无人机：“先派防水危化品无人机去找阀门，然后我再进去拧它。”' }, consequence: { en: '✨ High-Tech Hybrid. The drone finds the valve in 2 minutes and marks it with a strobe light. You go in and finish the job in record time. You used technology to eliminate the "search" phase of the risk. High innovation score.', th: '✨ ลูกผสมสุดล้ำ โดรนหาวาล์วเจอใน 2 นาทีและทำหเครื่องหมายไว้ด้วยไฟกะพริบ คุณเข้าไปปิดวาล์วได้ในเวลาที่เร็วที่สุด คุณใช้เทคโนโลยีเพื่อกำจัดขั้นตอน "การค้นหา" ที่มีความเสี่ยงออกไป คะแนนด้านนวัตกรรมสูงมาก', zh: '✨ 高科技混合。无人机在2分钟内找到了阀门并在那里放置了闪光灯标记。你进入并以破纪录的时间完成了工作。你利用技术消除了风险中的“搜索”阶段。创新分很高。' }, stats: { competence: 40, ethics: 30, leadership: 30, innovation: 60 } }
        ]
    },

    {
        id: 'fir_043',
        text: {
            en: '🏢 High-Rise Pump Failure: You are on the 25th floor of a luxury hotel fire. The building\'s pump system fails. The water pressure in your hose drops to a trickle. The fire is pushing out of the room onto your crew.',
            th: '🏢 ปั๊มน้ำตึกสูงขัดข้อง: คุณอยู่ที่ชั้น 25 ของโรงแรมหรูที่เกิดไฟไหม้ ระบบปั๊มน้ำของตึกเสีย แรงดันน้ำในสายฉีดของคุณลดลงเหลือแค่หยดๆ ไฟกำลังลามออกมาจากห้องเข้าหาทีมของคุณ',
            zh: '🏢 高层泵机故障：你正在一家豪华酒店的25层扑救火灾。大楼的泵系统故障。你水带里的水压降成了涓涓细流。大火正从房间冲向你的队员。'
        },
        options: [
            { id: 'A', text: { en: '🚒 Street-Level Relay: "Engine 1, pump into the standpipe at max pressure! We need a relay pumping operation now!"', th: '🚒 ส่งน้ำจากพื้นดิน: "Engine 1 ฉีดน้ำเข้าท่อยืนอาคารด้วยแรงดันสูงสุด! เราต้องทำการส่งต่อแรงดันน้ำ (Relay pumping) เดี๋ยวนี้!"', zh: '🚒 地面中继：“1号车，向竖管以最大压力供水！我们现在需要中继供水行动！”' }, consequence: { en: '✅ Mechanical Mastery. Your team on the street hooks up the engine and bypasses the building\'s failed pump. Pressure returns to your nozzle. You knock down the fire and save the floor. Knowing how to override building systems is vital.', th: '✅ ความเชี่ยวชาญด้านเครื่องกล ทีมของคุณบนถนนต่อสายเข้ากับรถดับเพลิงและจัดการส่งน้ำข้ามระบบปั๊มที่เสียของตึก แรงดันน้ำกลับมาที่หัวฉีดอีกครั้ง คุณดับไฟได้และเซฟชั้นนั้นไว้ได้ การรู้วิธีแทรกแซงระบบอาคารเป็นเรื่องสำคัญมาก', zh: '✅ 机械精通。你在地面的团队接通了消防车，绕过了大楼发生故障的泵。你的喷头恢复了压力。你扑灭了大火并保住了楼层。了解如何接管大楼系统至关重要。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 10 } },
            { id: 'B', text: { en: '🏃 Tactical Retreat: "No water, no fight! Everyone back into the stairwell and close the door! Abandon the line!"', th: '🏃 ถอยเชิงยุทธวิธี: "ไม่มีน้ำ สู้ไม่ได้! ทุกคนถอยไปที่บันไดหนีไฟแล้วปิดประตู! ทิ้งสายฉีดไปก่อน!"', zh: 'B 战术撤退：“没水就没法打！所有人退回楼梯间并关上门！放弃水带！”' }, consequence: { en: '⚠️ Living to Fight Another Day. You save your crew, but the fire grows unchecked and consumes 3 floors before water is restored. You were safe, but the damage was extensive. Your Captain questions why you didn\'t call for a relay sooner.', th: '⚠️ เก็บชีวิตไว้สู้ต่อ คุณช่วยทีมไว้ได้ แต่ไฟลามแบบฉุดไม่อยู่จนเผาไป 3 ชั้นก่อนจะกู้ระบบน้ำคืนมาได้ คุณปลอดภัยแต่ความเสียหายขยายวงกว้าง หัวหน้าถามว่าทำไมคุณถึงไม่เรียกทำ Relay pumping ให้เร็วกว่านี้', zh: '⚠️ 留得青山在。你救了你的团队，但火势在失去控制的情况下蔓延，在供水恢复前吞噬了3层楼。你很安全，但损失巨大。你的队长质疑你为什么不早点请求中继供水。' }, stats: { competence: 20, ethics: 40, leadership: 20, innovation: 0 } },
            { id: 'C', text: { en: '🧯 Extinguisher Stand: "Grab every fire extinguisher from the hallway! We hold this door until the pressure returns!"', th: '🧯 ใช้เครื่องดับเพลิง: "หยิบถังดับเพลิงทุกถังในทางเดินมา! เราจะคุมประตูนี้ไว้จนกว่าแรงดันน้ำจะกลับมา!"', zh: 'C 灭火器支撑：“拿走走廊上的所有灭火器！我们要守住这扇门直到压力恢复！”' }, consequence: { en: '😱 Overwhelmed. A 2.5lb dry chemical extinguisher is no match for a fully involved hotel suite. The smoke becomes too thick, and you are forced into an emergency bail-out. You risked lives on a futile gesture.', th: '😱 รับมือไม่ไหว ถังดับเพลิงเคมีแห้งขนาดเล็กสู้ไฟที่กำลังลุกลามในห้องสูทโรงแรมไม่ได้เลย ควันหนาทึบเกินไปจนคุณต้องกู้ภัยฉุกเฉินตัวเองออกมา คุณเอาชีวิตไปเสี่ยงกับการกระทำที่ไร้ประโยชน์', zh: '😱 难以承受。一个2.5磅的干粉灭火器根本无法抗衡火势全开的酒店套房。烟雾变得太浓，你被迫紧急撤离。你为了徒劳的举动而冒了生命危险。' }, stats: { competence: 10, ethics: 10, leadership: -30, innovation: 20 } }
        ]
    },

    {
        id: 'fir_044',
        text: {
            en: '🛩️ The Aircraft Crash: A small Cessna has crashed into a suburban backyard. The pilot is trapped. High-octane aviation fuel (AVGAS) is leaking into the family\'s swimming pool. The pool pump is running and could spark.',
            th: '🛩️ เครื่องบินตก: เครื่องบินเซสนาขนาดเล็กตกลงในหลังบ้านย่านชานเมือง นักบินติดอยู่ข้างใน น้ำมันเครื่องบิน (AVGAS) กำลังรั่วไหลลงในสระว่ายน้ำของบ้าน ปั๊มสระน้ำยังทำงานอยู่และอาจเกิดประกายไฟได้',
            zh: '🛩️ 飞机坠毁：一架小型塞斯纳飞机坠毁在郊区住宅的后院。飞行员被困。高辛烷值的航空汽油（AVGAS）正泄漏到这户人家的游泳池里。游泳池泵正在运行，可能会产生火花。'
        },
        options: [
            { id: 'A', text: { en: '⚡ Cut Power First: "I\'ll hit the main breaker for the pool and house, then we move in for the pilot!"', th: '⚡ ตัดไฟก่อน: "ผมจะไปสับเบรกเกอร์หลักของสระและตัวบ้านก่อน แล้วเราค่อยเข้าไปช่วยนักบิน!"', zh: '⚡ 先切断电源：“我去拉掉泳池和房子的总电闸，然后我们再进去救飞行员！”' }, consequence: { en: '✅ Risk Mitigation. Eliminating the ignition source (the pool pump) makes the scene vastly safer. You extract the pilot with no fire. In complex crashes, managing the "hidden" electrical risks is key.', th: '✅ ลดความเสี่ยง การกำจัดต้นตอของการติดไฟ (ปั๊มสระน้ำ) ทำให้ที่เกิดเหตุปลอดภัยขึ้นมาก คุณช่วยนักบินออกมาได้โดยไม่มีไฟไหม้ ในเหตุการณ์เครื่องบินตกที่ซับซ้อน การจัดการความเสี่ยงจากไฟฟ้าที่ "ซ่อนอยู่" คือหัวใจสำคัญ', zh: '✅ 风险缓解。消除着火源（泳池泵）使现场变得极其安全。你在没有起火的情况下救出了飞行员。在复杂的空难中，管理“隐藏”的电气风险是关键。' }, stats: { competence: 50, ethics: 40, leadership: 40, innovation: 20 } },
            { id: 'B', text: { en: '🏃 Extraction Rush: "Forget the pump! The pilot is bleeding out! Get him out now!"', th: '🏃 รีบช่วยคน: "ช่างหัวปั๊มมันเถอะ! นักบินเสียเลือดมากแล้ว! เอาเขาออกมาเดี๋ยวนี้!"', zh: 'B 紧急撤离：“别管泵了！飞行员流血过多！马上把他救出来！”' }, consequence: { en: '😱 Pool Explosion. Just as you reach the plane, the pump timer kicks a relay, causing a spark. The pool surface—covered in AVGAS—erupts in flame. You and your team suffer 2nd-degree burns. You ignored a preventable ignition source.', th: '😱 สระว่ายน้ำระเบิด ทันทีที่คุณถึงตัวเครื่องบิน นาฬิกาปั๊มน้ำทำงานทำให้เกิดประกายไฟ ผิวน้ำในสระที่เคลือบด้วยน้ำมันระเบิดเป็นกองไฟ คุณและทีมถูกไฟลวกระดับ 2 คุณเพิกเฉยต่อต้นตอการติดไฟที่ป้องกันได้', zh: '😱 泳池爆炸。就在你到达飞机旁时，水泵定时器启动了继电器并产生火花。覆盖着航空汽油的泳池表面爆发出了火焰。你和你的团队遭受了二级烧伤。你忽略了本可以避免的着火源。' }, stats: { competence: 10, ethics: 30, leadership: -20, innovation: 0 } },
            { id: 'C', text: { en: '💦 Foam Float: "Spray AFFF foam onto the pool surface to seal the vapors, then we ignore the pump and go for the pilot."', th: '💦 ใช้โฟมหน่วงไฟ: "ฉีดโฟม AFFF ลงบนผิวน้ำในสระเพื่อกักไอระเหย จากนั้นเราค่อยเข้าไปช่วยนักบินโดยไม่ต้องสนใจปั๊ม"', zh: 'C 泡沫覆盖：“向泳池表面喷洒AFFF（成膜氟蛋白）泡沫以封闭油汽，然后别管水泵，直接救飞行员。”' }, consequence: { en: '⚠️ Technical Gamble. The foam works temporarily, but the pump\'s underwater intake creates turbulence that breaks the foam seal. A small fire starts but you managed to get the pilot out just in time. Too risky compared to cutting power.', th: '⚠️ การพนันทางเทคนิค โฟมทำงานได้ชั่วคราว แต่แรงดูดน้ำใต้อันทรงพลังทำให้ผิวน้ำปั่นป่วนจนชั้นโฟมแตก ไฟเริ่มติดขึ้นมานิดๆ แต่คุณช่วยนักบินออกมาได้ทันเวลา มันเสี่ยงเกินไปเมื่อเทียบกับการแค่ไปตัดไฟ', zh: '⚠️ 技术豪赌。泡沫暂时有效，但水泵的下吸口产生的湍流破坏了泡沫密封层。一场小火发生了，但你及时救出了飞行员。与切断电源相比，这太冒险了。' }, stats: { competence: 30, ethics: 30, leadership: 20, innovation: 40 } }
        ]
    },
    {
        id: 'fir_045',
        text: {
            en: '🌊 The Flooded Basement: A heavy storm has flooded a basement where a homeowner is trapped on top of a washing machine. The water is rising. You see a submerged electrical panel that is "buzzing." The main breaker is in the flooded area.',
            th: '🌊 ห้องใต้ดินน้ำท่วม: พายุหนักทำให้น้ำท่วมห้องใต้ดิน เจ้าของบ้านติดอยู่บนเครื่องซักผ้า น้ำกำลังเพิ่มระดับขึ้นเรื่อยๆ คุณเห็นแผงควบคุมไฟฟ้าที่จมน้ำอยู่มีเสียง "หึ่งๆ" เบรกเกอร์หลักอยู่ในพื้นที่ที่น้ำท่วมไปแล้ว',
            zh: '🌊 淹水的地下室：一场暴雨淹没了地下室，房主被困在洗衣机顶部。水位正在上升。你看到一个被淹没的配电盘发出“嗡嗡”声。总断路器就在淹水区。'
        },
        options: [
            { id: 'A', text: { en: '🛶 Rubber Boat Entry: "Deploy the inflatable boat! We float over to him. Rubber doesn\'t conduct electricity!"', th: '🛶 ใช้เรือยาง: "เอาเรือยางออกมา! เราจะพายไปหาเขา ยางไม่นำไฟฟ้า!"', zh: '🛶 橡皮艇进入：“部署充气艇！我们漂过去找他。橡胶不导电！”' }, consequence: { en: '😱 Fatal Shock. Rubber boat hulls are often thin, and if any part of your gear (an axe, a boot, a wet rope) touches the water while you are touching the boat, you complete the circuit. Fresh water is a conductor. You and the homeowner are electrocuted. Insulation is not invincibility.', th: '😱 ไฟช็อตซ้ำซ้อน ตัวเรือยางบางครั้งก็บาง และถ้าอุปกรณ์อย่างใดอย่างหนึ่ง (ขวาน, รองเท้าบูท, เชือกเปียก) ไปโดนน้ำในขณะที่คุณสัมผัสเรือ คุณจะกลายเป็นส่วนหนึ่งของวงจรไฟฟ้าทันที น้ำจืดเป็นตัวนำไฟฟ้า คุณและเจ้าของบ้านถูกไฟดูด การมีฉนวนไม่ได้หมายความว่าจะเป็นอมตะ', zh: '😱 致命电击。橡皮艇的船体通常很薄，如果你身上任何装备（斧头、靴子、湿绳子）在触碰船只的同时接触到水，你就会闭合电路。淡水是导体。你和房主都会触电。绝缘并不等于无敌。' }, stats: { competence: 10, ethics: 20, leadership: 10, innovation: 25 } },
            { id: 'B', text: { en: '⚡ External Shutoff: "Call the utility company for a remote grid disconnect! Do not enter the water until the line is verified dead!"', th: '⚡ ตัดไฟจากภายนอก: "โทรหาการไฟฟ้าให้ตัดไฟจากระบบหลัก! ห้ามลงน้ำจนกว่าจะยืนยันได้ว่าไม่มีกระแสไฟแล้ว!"', zh: 'B 外部切断：“呼叫电力公司进行远程电网断开！在确认线路断电前不得进入水中！”' }, consequence: { en: '✅ Expert Safety. You wait 5 minutes for the grid cut. The homeowner is scared but safe. You then enter with drysuits and rescue them. You avoided a "double-victim" scenario by respecting invisible killers.', th: '✅ ความปลอดภัยระดับผู้เชี่ยวชาญ คุณรอ 5 นาทีเพื่อให้การไฟฟ้าตัดไฟ เจ้าของบ้านอาจจะกลัวแต่เขาปลอดภัย จากนั้นคุณค่อยเข้าไปช่วยด้วยชุดแห้ง (Drysuit) คุณหลีกเลี่ยงสถานการณ์ "เหยื่อรายที่สอง" โดยการเคารพภัยเงียบที่ไม่เห็นด้วยตา', zh: '✅ 专业安全性。你等待了5分钟直到电网断电。房主虽然害怕但很安全。然后你穿着干式潜水服进入并救出了他们。通过敬畏无形的杀手，你避免了“二次伤害”的情况。' }, stats: { competence: 50, ethics: 40, leadership: 40, innovation: 0 } },
            { id: 'C', text: { en: '🎣 Fishing Rescue: "Throw him a life ring and a rope from the stairs. Tell him to swim to us!"', th: '🎣 กู้ภัยจากระยะไกล: "โยนห่วงยางและเชือกให้เขาจากบันได บอกให้เขาว่ายน้ำมาหาเรา!"', zh: 'C 钓鱼式救援：“从楼梯上向他扔救生圈和绳子。让他游向我们！”' }, consequence: { en: '💀 Deadly Instruction. The moment he steps off the washing machine into the electrified water, he suffers cardiac arrest. You guided him to his death. Never tell a victim to enter a hazardous zone.', th: '💀 คำแนะนำมรณะ วินาทีที่เขาก้าวลงจากเครื่องซักผ้าลงน้ำที่มีกระแสไฟ หัวใจเขาหยุดเต้นทันที คุณนำทางเขาไปสู่ความตาย อย่าบอกให้เหยื่อเข้าไปในเขตอันตรายเด็ดขาด', zh: '💀 致命指示。在他离开洗衣机踏入带电水面的一瞬间，他心搏骤停。你指引他走向了死亡。绝不要告诉受害者进入危险区域。' }, stats: { competence: 10, ethics: 10, leadership: -40, innovation: 0 } }
        ]
    },

    {
        id: 'fir_046',
        text: {
            en: '🕵️ The Ethics Test: At a fire in a high-end jewelry store, you see a veteran firefighter pocket a small diamond ring. He sees you looking. Later, he says, "Insurance covers it, kid. We work hard for low pay. Keep your mouth shut and I\'ll get you a nice watch next time."',
            th: '🕵️ บททดสอบจริยธรรม: ในเหตุไฟไหม้ร้านเพชรหรู คุณเห็นนักดับเพลิงรุ่นพยศซุกแหวนเพชรวงเล็กเข้ากระเป๋า เขาเห็นว่าคุณมองอยู่ หลังจากนั้นเขาบอกว่า "ประกันจ่ายน่าไอ้หนู เราทำงานหนักแต่เงินเดือนน้อยนะ เงียบไว้แล้วคราวหน้าพี่จะหานาฬิกาสวยๆ ให้แกเรือนนึง"',
            zh: '🕵️ 伦理测试：在一家高端珠宝店的火灾现场，你看到一名老牌消防员私吞了一枚小钻戒。他也看到了你在看他。稍后他说道：“保险会赔的，孩子。我们干得卖力，拿得太少。闭上你的嘴，下次我给你弄块好表。”'
        },
        options: [
            { id: 'A', text: { en: '📢 Immediate Report: "I’m going straight to the Captain. This is theft and it dishonors the badge."', th: '📢 รายงานทันที: "ผมจะไปรายงานหัวหน้าเดี๋ยวนี้ นี่คือการขโมยและมันทำให้ตราที่เราติดอยู่เสียเกียรติ"', zh: '📢 立即汇报：“我要直接去找队长。这是偷窃，是对徽章的玷污。”' }, consequence: { en: '✅ Integrity Maintained. The veteran is fired and prosecuted. Some of the crew call you a "snitch" for a while, but the Captain and the public trust you. You kept the department\'s reputation clean. Integrity is non-negotiable.', th: '✅ รักษาความซื่อสัตย์ รุ่นพี่คนนั้นถูกไล่ออกและดำเนินคดี ทีมบางคนอาจจะเรียกคุณว่า "สายสืบ" อยู่พักหนึ่ง แต่หัวหน้าและประชาชนเชื่อใจคุณ คุณรักษาชื่อเสียงของกรมไว้ได้ ความซื่อสัตย์คือเรื่องที่ต่อรองไม่ได้', zh: '✅ 保持正直。老兵被解雇并起诉。有些队员会有段时间叫你“告密者”，但队长和公众信任你。你保持了部门的名誉。诚信是不容谈判的。' }, stats: { competence: 30, ethics: 70, leadership: 50, innovation: 0 } },
            { id: 'B', text: { en: '🤐 Quiet Confrontation: "Put it back, or I’ll report it. No watches, no deals. Just put it back now."', th: '🤐 เผชิญหน้าเงียบๆ: "เอากลับไปวางที่เดิม ไม่อย่างนั้นผมจะรายงาน ไม่เอาของขวัญ ไม่เอาข้อเสนออะไรทั้งนั้น วางคืนเดี๋ยวนี้"', zh: 'B 私下对质：“把它放回去，否则我就举报。不要表，不要交易。现在就放回去。”' }, consequence: { en: '⚠️ Uncertain Ground. He puts it back, but he hates you forever. You didn\'t report the crime, which technically makes you an accessory. You resolved the immediate theft but left a "cancer" in the department.', th: '⚠️ พื้นที่สีเทา เขาเอาคืนที่เดิมแต่จะเกลียดคุณไปตลอดชีวิต คุณไม่ได้รายงานการกระทำผิด ซึ่งในทางเทคนิคคุณคือผู้สมรู้ร่วมคิด คุณแก้เรื่องขโมยของได้แต่ทิ้ง "มะเร็งร้าย" ไว้ในหน่วยงาน', zh: '⚠️ 不确定的局面。他放回去了，但他从此恨透了你。你没有举报罪行，这在技术上让你成了从犯。你解决了眼前的偷窃问题，但在部门内留下了“毒瘤”。' }, stats: { competence: 20, ethics: 40, leadership: 30, innovation: 20 } },
            { id: 'C', text: { en: '💸 Take the Deal: "You\'re right, Cap. It\'s a tough world. I didn\'t see anything."', th: '💸 ยอมรับข้อเสนอ: "พี่พูดถูกครับหัวหน้า โลกมันอยู่ยาก ผมไม่เห็นอะไรทั้งนั้นแหละ"', zh: 'C 接受交易：“你说得对，长官。这世道不容易。我什么都没看见。”' }, consequence: { en: '💀 Moral Corruption. A month later, the department is raided by the FBI. Cameras were recording the whole time. You are fired, lose your pension, and go to prison alongside the veteran. You traded your entire career for a watch you never even got.', th: '💀 ความเสื่อมทรามทางศีลธรรม หนึ่งเดือนต่อมา กรมถูก FBI บุกตรวจสอบ กล้องวงจรปิดบันทึกภาพไว้ได้ทั้งหมด คุณถูกไล่ออก เสียเงินบำนาญ และติดคุกไปพร้อมกับรุ่นพี่คนนั้น คุณแลกอนาคตทั้งชีวิตกับนาฬิกาที่ยังไม่ทันได้เห็นเลยด้วยซ้ำ', zh: '💀 道德败坏。一个月后，联邦调查局突袭了该部门。录像带一直都在录像。你被开除，失去了养老金，并和那名老兵一起入狱。你用整个职业生涯换了一块还没到手的表。' }, stats: { competence: 10, ethics: -80, leadership: -50, innovation: -10 } }
        ]
    },

    {
        id: 'fir_047',
        text: {
            en: '🌳 The Wildland Interface: A massive brush fire is approaching a row of high-value homes. You are in a driveway. The fire is moving 30 mph. You have 3 minutes before the "fire front" hits. Your pump pressure is weak.',
            th: '🌳 เขตพื้นที่รอยต่อป่าและเมือง: ไฟป่าขนาดใหญ่กำลังมุ่งหน้าเข้าหาบ้านหรูแถวหนึ่ง คุณอยู่ในทางเข้าบ้าน ไฟเคลื่อนที่ด้วยความเร็ว 30 ไมล์ต่อชั่วโมง คุณเหลือเวลาแค่ 3 นาทีก่อน "แนวไฟ" จะมาถึง แรงดันปั๊มน้ำของคุณอ่อนมาก',
            zh: '🌳 林区/社区交界处：一场大规模林火正席卷一排豪宅。你正待在一条车道上。火焰移动速度达到每小时30英里。你只有3分钟的时间，火头就要压顶了。你的水泵压力很弱。'
        },
        options: [
            { id: 'A', text: { en: '🛡️ Defensible Space Stand: "We can save this! Set up the sprinklers on the roof and hide in the truck until the flame-front passes!"', th: '🛡️ ยืนหยัดสู้: "เราเซฟบ้านได้! ตั้งสปริงเกอร์บนหลังคาแล้วเข้าไปหลบในรถจนกว่าแนวไฟจะผ่านไป!"', zh: 'A 守卫可防空间：“我们能保住它！在屋顶架起洒水器，躲进卡车里直到火头过去！”' }, consequence: { en: '💀 Fatal Error. A "burnover" is often unsurvivable in a standard fire engine. The tires melt, and the glass shatters. You chose property over life. The house burns anyway because the pump failed during the peak heat. You nearly died for a pile of bricks.', th: '💀 ความผิดพลาดถึงตาย เหตุการณ์ "ไฟป่าคลอกรถ" (Burnover) มักไม่มีใครรอดในรถดับเพลิงมาตรฐาน ยางละลาย กระจกแตก คุณเลือกทรัพย์สินมากกว่าชีวิต สุดท้ายบ้านก็ไหม้อยู่ดีเพราะปั๊มเสียตอนที่ร้อนจัด คุณเกือบตายเพื่อกองอิฐกองเดียว', zh: '💀 致命错误。在普通的消防车里经受“火卷”通常是无法生还的。轮胎会熔化，玻璃会碎裂。你选择了财产而非生命。由于水泵在最高温时故障，房子最终还是烧毁了。你差点为了一堆砖头送命。' }, stats: { competence: 10, ethics: 20, leadership: -30, innovation: 0 } },
            { id: 'B', text: { en: '🏃 Tactical Withdrawal: "Fire is non-survivable. Load up! We retreat to the safety zone. We\'ll catch the embers after the front passes."', th: '🏃 ถอยตั้งรับ: "ไฟนี้เราทนไม่ได้แน่ๆ โหลดของ! ถอยไปเขตปลอดภัยก่อน เราค่อยกลับมาเก็บงานหลังจากแนวไฟผ่านไปแล้ว"', zh: 'B 战术撤退：“火势无法抵挡。收拾东西！撤退到安全区。火头过后我们再来扑灭余火。”' }, consequence: { en: '✅ Professional Judgement. You live to fight. You watch the fire front roar through. Once it passes, you return and put out a small fire on the porch, SAVING the house. By being alive and mobile, you were more effective than the "heroic" stand.', th: '✅ การตัดสินใจอย่างมืออาชีพ คุณยังมีชีวิตอยู่สู้ต่อ คุณเฝ้าดูแนวไฟพัดผ่านไป พอไฟพ้นไปแล้ว คุณกลับมาดับไฟเล็กๆ ตรงระเบียงบ้าน ผลคือเซฟบ้านไว้ได้ การมีชีวิตอยู่และเคลื่อนที่ได้ทำให้คุณทำงานได้ดีกว่าการยืนหยัดแบบ "ฮีโร่" แต่ไร้สติ', zh: '✅ 专业判断。你保存了实力。你看着火头咆哮而过。一旦过去，你就返回并扑灭了门廊上的一处小火，保住了房子。通过生存和机动，你比那种“英勇”的坚守更有效。' }, stats: { competence: 50, ethics: 40, leadership: 40, innovation: 20 } },
            { id: 'C', text: { en: '🔥 Back-Burn: "Light a counter-fire! We’ll burn the grass around the house so the main fire has no fuel!"', th: '🔥 เผาสกัด: "จุดไฟสวนกลับ! เราจะเผาหญ้ารอบบ้านก่อน เพื่อให้ไฟหลักไม่มีเชื้อเพลิง!"', zh: 'C 预焚：“点燃反火！我们要把房子周围的草烧掉，这样主火就没有燃料了！”' }, consequence: { en: '⚠️ High-Risk Innovation. Without a massive crew and weather data, your "back-fire" gets out of control and burns down the Neighbor\'s house instead. You had the right idea but were under-resourced for the execution. Lawsuits follow.', th: '⚠️ นวัตกรรมที่มีความเสี่ยงสูง หากไม่มีทีมงานจำนวนมากและข้อมูลสภาพอากาศ "ไฟสกัด" ของคุณกลับลามคุมไม่ได้และไปเผาบ้านเพื่อนบ้านแทน คุณมีความคิดที่ดีแต่ขาดทรัพยากรในการทำ การฟ้องร้องกำลังตามคุณมา', zh: '⚠️ 高风险创新。在没有庞大团队和气象数据的情况下，你的“反火”失去了控制，反而烧毁了邻居的房子。你的思路是对的，但执行该方案的资源不足。随后是法律诉讼。' }, stats: { competence: 30, ethics: 25, leadership: 20, innovation: 60 } }
        ]
    },

    {
        id: 'fir_048',
        text: {
            en: '🏢 The Trash Chute Fire: A fire is burning inside a 40-story trash chute. Smoke is filling every floor. The chute is clogged on the 10th floor. Your crew wants to drop water from the roof (40th floor).',
            th: '🏢 ไฟไหม้ในช่องทิ้งขยะ: ไฟกำลังไหม้ในช่องทิ้งขยะของตึกสูง 40 ชั้น ควันลอยฟุ้งไปทุกชั้น ช่องทิ้งขยะอุดตันที่ชั้น 10 ทีมของคุณต้องการฉีดน้ำลงมาจากดาดฟ้าชั้น 40',
            zh: '🏢 垃圾道火灾：一座40层建筑的垃圾道内发生火灾。浓烟充斥着每一个楼层。垃圾道在10层堵塞。你的团队想从屋顶（40层）往下浇水。'
        },
        options: [
            { id: 'A', text: { en: '💧 Roof Drop: "Gravity is our friend. Open the top hatch and let the master stream do the work!"', th: '💧 ฉีดน้ำจากดาดฟ้า: "แรงดึงดูดคือเพื่อนเรา เปิดประตูด้านบนแล้วใช้น้ำแรงดันสูงฉีดลงมาเลย!"', zh: '💧 屋顶倾倒：“重力是我们的朋友。打开顶部舱盖，让主供水管大显身手！”' }, consequence: { en: '😱 Steam Explosion. The water hits the fire at the 10th floor, turns to steam, and has nowhere to go. It blasts out of the trash chute doors on floors 1-9, scalding occupants and your own crews. You turned a chute into a steam cannon. Basic physics fail.', th: '😱 ระเบิดไอน้ำ น้ำไปโดนไฟที่ชั้น 10 แล้วเปลี่ยนเป็นไอน้ำโดยไม่มีทางออก มันเลยระเบิดออกทางประตูทิ้งขยะชั้น 1-9 ลวกคนในอาคารและทีมงานของคุณเอง คุณเปลี่ยนช่องขยะให้กลายเป็นปืนใหญ่ไอน้ำ เป็นการผิดพลาดหลักฟิสิกส์พื้นฐาน', zh: '😱 蒸汽爆炸。水冲向10层的火点，转化为蒸汽，且无处可逃。它从1到9层的垃圾道门中冲出，烫伤了楼内居民和你自己的队员。你把垃圾道变成了蒸汽大炮。物理常识不过关。' }, stats: { competence: 10, ethics: 20, leadership: 30, innovation: 0 } },
            { id: 'B', text: { en: '🔨 Mid-Level Search: "Halt roof operations. We need to find the clog on the 10th floor, breach the chute there, and hit it directly."', th: '🔨 คลำหาจุดอุดตัน: "หยุดงานบนดาดฟ้าก่อน เราต้องไปหาจุดที่ตันที่ชั้น 10 เจาะช่องทิ้งขยะตรงนั้นแล้วฉีดน้ำใส่โดยตรง"', zh: 'B 中层搜索：“停止屋顶作业。我们需要找到10层的堵塞点，在那里破拆垃圾道并直接扑救。”' }, consequence: { en: '✅ Correct High-Rise Tactic. By breaching the chute just above the fire, you contain the damage and the steam. The fire is out in minutes. Patience and investigation beat the "easy" brute-force solution.', th: '✅ ยุทธวิธีตึกสูงที่ถูกต้อง การเจาะช่องทิ้งขยะเหนือกองเพลิงช่วยควบคุมความเสียดายและไอน้ำได้ ไฟดับในเวลาไม่กี่นาที ความอดทนและการสืบสวนให้ผลดีกว่าการแก้ปัญหาแบบใช้กำลังหักโหม', zh: '✅ 正确的高层战术。通过在火源上方破拆垃圾道，你遏制了损伤和蒸汽。火在几分钟内被扑灭。耐心和调查击败了“简单”的暴力解决方法。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 10 } },
            { id: 'C', text: { en: '💨 Foam Infusion: "Use a high-expansion foam generator from the base of the chute. It’ll fill the whole tube smoothly."', th: '💨 ใช้โฟมท่วมช่อง: "ใช้เครื่องผลิตโฟมหนาแน่นสูงจากฐานช่องทิ้งขยะ มันจะลอยขึ้นไปเต็มช่องได้ง่ายกว่า"', zh: 'C 泡沫灌注：“从垃圾道底部使用高倍数泡沫发生器。它会顺滑地填满整个管道。”' }, consequence: { en: '✨ Creative Success. The foam rises 10 floors and smothers the fire without the risk of steam expansion. It’s messy to clean up, but highly effective for vertical void fires. Excellent use of specialized equipment.', th: '✨ ความสำเร็จที่สร้างสรรค์ โฟมลอยขึ้นไป 10 ชั้นและกลบไฟได้โดยไม่มีความเสี่ยงเรื่องระเบิดไอน้ำ แม้จะทำความสะอาดยากแต่มันได้ผลดีเยี่ยมสำหรับไฟในช่องแนวดิ่ง เป็นการใช้อุปกรณ์เฉพาะทางที่ยอดเยี่ยม', zh: '✨ 创意成功。泡沫上升到10层并扑灭了火焰，而没有蒸汽膨胀的风险。清理起来很麻烦，但对垂直空洞火灾非常有效。对专业设备的使用非常出色。' }, stats: { competence: 40, ethics: 30, leadership: 30, innovation: 60 } }
        ]
    },

    {
        id: 'fir_049',
        text: {
            en: '🤝 The Multi-Agency Mesh: At a massive building collapse, the Police Sergeant is trying to order your firefighters to move unstable concrete. Your structural engineer says it\'s too dangerous. The Sergeant says, "My officers are under there! Move it now or I\'m arresting you for obstruction!"',
            th: '🤝 การทำงานร่วมกับหลายหน่วยงาน: ในเหตุการณ์ตึกถล่มขนานใหญ่ จ่าตำรวจพยายามสั่งให้เหล่านักดับเพลิงย้ายก้อนคอนกรีตที่ไม่มั่นคง วิศวกรโครงสร้างของคุณบอกว่ามันอันตรายเกินไป จ่าคนนั้นบอกว่า "ลูกน้องผมติดอยู่ข้างใต้! ย้ายมันเดี๋ยวนี้ไม่อย่างนั้นผมจะจับคุณข้อหาขัดขวางการทำงาน!"',
            zh: '🤝 多机构协同：在一次大规模建筑倒塌现场，警察中士正试图命令你的消防员搬运不稳定的混凝土。你的结构工程师说那太危险了。中士说：“我的警员就在下面！马上搬走，否则我以妨碍公务罪逮捕你！”'
        },
        options: [
            { id: 'A', text: { en: '👮 Face-off: "Arrest me then. You aren’t qualified to judge structural safety. My crew doesn’t move until the shoring is set."', th: '👮 เผชิญหน้าชน: "ก็จับสิ คุณไม่มีสิทธิ์มาตัดสินความปลอดภัยโครงสร้าง ทีมผมจะไม่ขยับจนกว่าจะติดตั้งค้ำยันเสร็จ"', zh: 'A 对峙：“那你就逮捕我吧。你没资格判断结构安全。在支撑加固完成前，我的队伍绝不会动。”' }, consequence: { en: '✅ Expert Authority. He doesn\'t arrest you. He realizes he\'s speaking out of grief. You finish the shoring, and 20 minutes later, you safely extract the police officers. By standing your ground, you saved BOTH the victims and your rescuers.', th: '✅ อำนาจของผู้เชี่ยวชาญ เขาไม่จับคุณหรอก เขาแค่พูดออกมาด้วยความเสียใจ คุณทำค้ำยันจนเสร็จ และ 20 นาทีต่อมา คุณก็ช่วยตำรวจออกมาได้อย่างปลอดภัย การยึดมั่นในหลักการช่วยทั้งเหยื่อและกู้ภัยให้รอดชีวิต', zh: '✅ 专家权威。他并没有逮捕你。他意识到自己是因为悲痛才出言不逊。你完成了支撑加固，20分钟后，你安全地救出了警察。通过坚守立场，你同时救了受害者和你的搜救队员。' }, stats: { competence: 50, ethics: 40, leadership: 60, innovation: 0 } },
            { id: 'B', text: { en: '🤝 Compromise: "We’ll move the small pieces by hand while the engineer watches, but no heavy machinery yet."', th: '🤝 ประนีประนอม: "เราจะย้ายชิ้นเล็กๆ ด้วยมือระหว่างวิศวกรดูอยู่ แต่จะยังไม่ใช้เครื่องจักรหนัก"', zh: 'B 妥协：“我们会在工程师的观察下手动搬运小块碎片，但暂时不动用重型机械。”' }, consequence: { en: '😱 Secondary Collapse. Even moving "small pieces" shifts the load. A slab slips and crushes the hand of one of your firefighters. You let a non-expert influence a high-stakes safety environment. Leadership failure under pressure.', th: '😱 ถล่มซ้ำสอง แม้การย้าย "ชิ้นเล็กๆ" ก็ทำให้การกระจายน้ำหนักเปลี่ยนไป คอนกรีตแผ่นหนึ่งสไลด์ทับมือหนึ่งในนักดับเพลิงของคุณ คุณปล่อยให้คนที่ไม่ใช่ผู้เชี่ยวชาญมามีอิทธิพลในการตัดสินใจเรื่องความปลอดภัยสูง ภาวะผู้นำล้มเหลวภายใต้ความกดดัน', zh: '😱 二次塌方。即使搬动“小碎片”也会导致载荷偏移。一块板材滑动，压伤了你一名消防员的手。你让非专业人士影响了高风险的安全环境。压力下的领导力失败。' }, stats: { competence: 20, ethics: 30, leadership: 20, innovation: 10 } },
            { id: 'C', text: { en: '🚜 Tactical Leverage: "Officer, hand me your tactical jack from your squad car. If we use that while we dig, we can stabilize it just enough to reach them."', th: 'C การใช้เครื่องมือพลิกแพลง: "จ่าครับ ส่งแม่แรงยุทธวิธีที่อยู่ในรถสายตรวจมาให้ผมหน่อย ถ้าเราใช้ตัวนั้นช่วยตอนขุด เราจะคุมความมั่นคงได้พอที่จะเข้าถึงตัวพวกเขา"', zh: 'C 战术杠杆：“警官，把你巡逻车里的战术千斤顶给我。如果我们挖掘时使用它，我们就能提供足够的稳定性来营救他们。”' }, consequence: { en: '✨ Synergistic Success. By involving the policeman and using his equipment, you de-escalate the tension. You use a non-standard tool for a quick stabilization. You reach the men safely. 10/10 for diplomacy and innovation.', th: '✨ ความสำเร็จที่ผสานพลัง การดึงตำรวจเข้ามาช่วยและใช้อุปกรณ์ของเขาช่วยลดความตึงเครียด คุณใช้เครื่องมือที่ไม่ใช่มาตรฐานเพื่อคุมที่เกิดเหตุได้อย่างรวดเร็ว คุณเข้าถึงตัวคนได้อย่างปลอดภัย 10/10 สำหรับการทูตและนวัตกรรม', zh: '✨ 协同成功。通过让警察参与进来并使用他的设备，你缓和了紧张局势。你使用非标准工具进行了快速加固。你安全地救出了伤员。外交和创新满分。' }, stats: { competence: 40, ethics: 40, leadership: 50, innovation: 70 } }
        ]
    },

    {
        id: 'fir_050',
        text: {
            en: '🎖️ The Legacy: You are 25 years into the service and preparing to retire. A young rookie looks at you after a long, exhausting shift and asks, "Is it worth it? The soot, the trauma, the missed birthdays... Does it matter in the end?"',
            th: '🎖️ มรดกที่ทิ้งไว้: คุณทำงานมา 25 ปีแล้วและกำลังจะเกษียณ น้องใหม่คนหนึ่งมองหน้าคุณหลังจากผ่านกะงานที่เหนื่อยล้ามาทั้งวันแล้วถามว่า "มันคุ้มไหมครับพี่? ทั้งควันไฟ ทั้งภาพติดตา ทั้งวันเกิดที่ไม่ได้ไปฉลอง... สุดท้ายแล้วมันมีความหมายอะไรบ้างไหม?"',
            zh: '🎖️ 传承：你已经服役25年，正准备退休。在一次漫长、精疲力竭的轮班后，一个年轻的新手看着你问道：“这值得吗？烟灰、创伤、错过家人的生日……到头来，这一切重要吗？”'
        },
        options: [
            { id: 'A', text: { en: '👨‍👧‍👦 The Human Connection: "The soot washes off. The birthdays... you make them up. But the families we saved? They are living their lives because of US. That’s the only trophy that matters."', th: '👨‍👧‍👦 ความผูกพันของมนุษย์: "ควันไฟมันล้างออกได้ วันเกิด... เราฉลองย้อนหลังได้ แต่ครอบครัวที่เราเคยช่วยไว้ล่ะ? พวกเขามีชีวิตอยู่ต่อได้เพราะเรานะ นั่นแหล่ะคือรางวัลเดียวที่มีความหมายจริงๆ"', zh: '👨‍👧‍搬 人的纽带：“烟灰会洗掉。生日……你会补回来的。但我们救过的那些家庭呢？因为有我们在，他们才能继续生活。那是唯一重要的奖杯。”' }, consequence: { en: '✅ A Leader\'s Heart. You inspire the next generation. The rookie stays on, fueled by your words. You retire knowing the department is in good hands. Your legacy isn\'t in medals, but in the people you mentored.', th: '✅ หัวใจของผู้นำ คุณสร้างแรงบันดาลใจให้คนรุ่นหลัง น้องใหม่คนนั้นตัดสินใจอยู่ต่อโดยมีคำพูดคุณเป็นพลังใจ คุณเกษียณไปโดยรู้ว่ากรมดับเพลิงอยู่ในมือคนที่ยอดเยี่ยม มรดกของคุณไม่ใช่เหรียญกล้าหาญ แต่คือคนที่คุณพร่ำสอนมา', zh: '✅ 领导者之心。你激励了下一代。受你这番话的鼓舞，新手留了下来。你退休时深知部门得到了良人托付。你的遗产不在于奖章，而在于你指导过的人。' }, stats: { competence: 40, ethics: 60, leadership: 100, innovation: 0 } },
            { id: 'B', text: { en: '🥃 The Bitter Reality: "Honestly? No. Take your pension and get out as fast as you can. This job takes everything and gives back nothing but a bad back."', th: '🥃 ความจริงที่แสนขมขื่น: "เอาจริงๆ นะ ไม่เลย แกเอาบำนาญแล้วรีบลาออกไปให้เร็วที่สุดเถอะ งานนี้มันสูบทุกอย่างไปจากแก แล้วให้คืนมาแค่โรคปวดหลังเรื้อรังเท่านั้นแหล่ะ"', zh: 'B 苦涩的现实：“实话实说？不值。拿了你的养老金，尽早离开。这份工作夺走了一切，除了落下一身腰酸背痛外什么都没给你。”' }, consequence: { en: '😔 Toxic Departure. You leave a legacy of bitterness. The rookie quits the next week. You retire alone and angry. You saved lives for 25 years, but failed to save the spirit of the service. A sad end to a long career.', th: '😔 การจากไปที่เป็นพิษ คุณทิ้งมรดกเป็นความขุ่นเคืองไว้ น้องใหม่ลาออกในอาทิตย์ถัดมา คุณเกษียณไปอย่างโดดเดี่ยวและขี้โมโห คุณช่วยชีวิตคนมา 25 ปี แต่กลับล้มเหลวในการช่วยจิตวิญญาณของงานบริการสังคม เป็นการจบอาชีพที่น่าเศร้า', zh: '😔 有毒的离开。你留下的是痛苦的情绪。新手下周就辞职了。你带着愤怒孤独地退休。你救了25年人，却没能拯救这份职业的精神。漫长职业生涯的一个悲伤结局。' }, stats: { competence: 30, ethics: 20, leadership: -100, innovation: 0 } },
            { id: 'C', text: { en: '🔥 The Eternal Fire: "It matters because we are the line between chaos and order. If we don’t do it, who will? Now, clean your gear and get ready for the next bell."', th: '🔥 กองไฟที่ไม่มีวันดับ: "มันสำคัญสิ เพราะเราคือกำแพงกั้นระหว่างความวุ่นวายและความสงบสุข ถ้าเราไม่ทำใครจะทำ? เอ้า ไปเช็คของให้เรียบร้อยแล้วเตรียมตัวรอระฆังครั้งต่อไปได้แล้ว"', zh: '🔥 永恒之火：“这很重要，因为我们是混乱与秩序之间的防线。如果我们不干，谁干？现在，去清理你的装备，准备迎接下一次铃声。”' }, consequence: { en: '✅ Stoic Professionalism. You teach him the discipline of the service. He becomes a hard but fair officer. You retire with the respect of every member of the squad. The fire never goes out as long as there are people willing to fight it.', th: '✅ ความเป็นมืออาชีพที่เคร่งครัด คุณสอนระเบียบวินัยของงานบริการให้เขา เขากลายเป็นเจ้าหน้าที่ที่เข้มงวดแต่ยุติธรรม คุณเกษียณไปท่ามกลางความเคารพของคนในทีม กองเพลิงแห่งแรงใจจะไม่มีวันดับตราบใดที่มีคนพร้อมจะสู้กับมัน', zh: '✅ 坚忍的专业精神。你教给他这项职业的纪律。他成了一名严厉但公正的长官。你在全队成员的尊重中退休。只要有人愿意战斗，火就永远不会熄灭。' }, stats: { competence: 60, ethics: 40, leadership: 80, innovation: 10 } }
        ]
    },
    {
        id: 'fir_041',
        text: {
            en: '👶 The Locked Nursery: You are in a smoke-filled apartment. The nursery door is locked from the inside. You can hear a baby crying. The smoke is at knee level and turning black. You didn\'t bring the heavy irons, only a halligan bar.',
            th: '👶 ห้องเด็กที่ถูกล็อค: คุณอยู่ในอพาร์ทเมนต์ที่มีควันเต็มไปหมด ประตูห้องเด็กถูกล็อคจากข้างใน คุณได้ยินเสียงเด็กทารกร้องไห้ ควันสูงระดับเข่าและเริ่มเปลี่ยนเป็นสีดำ คุณไม่ได้เอาเครื่องมือเจาะประตูหนักๆ มา มีแค่ชะแลง Halligan เท่านั้น',
            zh: '👶 被锁的育婴室：你身处一间浓烟密布的公寓。育婴室的门从里面锁上了。你能听到婴儿的哭声。烟雾已降至膝盖高度并开始变黑。你没带重型破拆工具，只带了一把哈利根铁撬。'
        },
        options: [
            { id: 'A', text: { en: '🔨 Halligan Kick: "Use the adz end of the halligan to gap the door, then kick it near the lock!"', th: '🔨 ใช้ชะแลงกระแทก: "ใช้ปลายแบนของ Halligan เสียบช่องประตูแล้วเตะแรงๆ ตรงใกล้ที่ล็อค!"', zh: '🔨 哈利根强攻：“用哈利根铁撬的扁平端插进门缝，然后在锁具附近用力踢门！”' }, consequence: { en: '✅ Successful Breach. The wood frame was old. It gave way on the first try. You grabbed the baby and crawled out under the smoke. Your speed and tool knowledge saved a life. Every second counts in a fire.', th: '✅ พังเข้าไปสำเร็จ วงกบไม้ค่อนข้างเก่า มันหลุดออกตั้งแต่ครั้งแรก คุณคว้าเด็กแล้วคลานออกมาใต้ควัน ความเร็วและความรู้เรื่องเครื่องมือของคุณช่วยชีวิตคนไว้ได้ ทุกวินาทีมีค่าในกองไฟ', zh: '✅ 成功破门。木质门框很旧，第一次尝试就开了。你抱起婴儿，在烟雾下方爬了出去。你的速度和对工具的了解挽救了一个生命。火灾中分秒必争。' }, stats: { competence: 50, ethics: 40, leadership: 30, innovation: 10 } },
            { id: 'B', text: { en: '🪓 Axe the Center: "I\'ll swing the halligan like a sledgehammer into the center of the door to break the panel!"', th: '🪓 ทุบกลางประตู: "ฉันจะเหวี่ยง Halligan เหมือนค้อนปอนด์ใส่กลางประตูเพื่อทำลายแผ่นไม้!"', zh: 'B 猛击门中：“我要像用大锤一样把哈利根撬棍轮向门中心，砸断门板！”' }, consequence: { en: '⚠️ Delayed Entry. Door panels are often reinforced. You just made a hole too small to fit through, and the vibration upset the door frame, making it harder to pry later. You got the baby, but it took three times as long and they required oxygen therapy for smoke inhalation.', th: '⚠️ เข้าได้ล่าช้า แผ่นประตูมักจะหนา คุณแค่เจาะรูที่เล็กเกินกว่าจะผ่านได้ และแรงสั่นสะเทือนทำใหวงกบประตูบิดจนงัดยากขึ้น คุณช่วยเด็กได้แต่ใช้เวลานานขึ้น 3 เท่า และเด็กต้องรับออกซิเจนจากการสำลักควัน', zh: '⚠️ 延迟进入。门板通常都加固过。你只弄出了一个钻不过去的小洞，而且震动弄歪了门框，导致随后更难撬开。你救出了婴儿，但花了三倍的时间，由于吸入烟雾，孩子需要接受氧疗。' }, stats: { competence: 20, ethics: 30, leadership: 10, innovation: 0 } },
            { id: 'C', text: { en: '💨 Use the Flashlight: "I\'ll smash the door handle off with the butt of my heavy flashlight!"', th: '💨 ใช้ไฟฉายทุบ: "ฉันจะทุบที่จับประตูให้หลุดด้วยท้ายไฟฉายกระบอกหนัก!"', zh: 'C 使用手电筒：“我要用重型手电筒的底部把门把手砸掉！”' }, consequence: { en: '❌ Tool Damage. Your flashlight broke, and the handle stayed on the door. You are now in a dark, smoke-filled room without a light source. You had to retreat to find your partner, wasting precious minutes. Never use a light as a hammer.', th: '❌ อุปกรณ์เสียหาย ไฟฉายของคุณพัง แต่ที่จับประตูยังอยู่ที่เดิม ตอนนี้คุณอยู่ในห้องมืดที่เต็มไปด้วยควันโดยไม่มีแสงสว่าง คุณต้องถอยออกมาตามหาคู่หู เสียเวลาไปอย่างเปล่าประโยชน์ ห้ามใช้ไฟฉายแทนค้อนเด็ดขาด', zh: '❌ 工具损坏。你的手电筒碎了，柄部还留在门上。你现在处于黑暗、浓烟密布的房间里，且失去了光源。你不得不撤回寻找搭档，浪费了宝贵的分钟。绝不要把电筒当锤子使。' }, stats: { competence: 10, ethics: 20, leadership: -20, innovation: 0 } },
            { id: 'D', text: { en: '🏢 External Access: "It\'s too thick in here! I\'m going back out to use the ladder to enter through the nursery window!"', th: 'D เข้าจากภายนอก: "ข้างในนี้ควันหนาเกินไป! ฉันจะออกไปข้างนอกเพื่อใช้บันไดปีนเข้าทางหน้าต่างห้องเด็ก!"', zh: 'D 外部进入：“这里烟太浓了！我回外面去，用梯子从育婴室窗户进入！”' }, consequence: { en: '💀 Abandonment. By the time you exited the apartment, ran to the truck, setup the ladder, and climbed up, the flashover had occurred. The baby did not survive. You failed to realize that moving through a structure is usually faster than resetting for external entry.', th: '💀 การทอดทิ้ง กว่าคุณจะออกจากห้อง วิ่งไปที่รถ ติดตั้งบันได และปีนขึ้นไป ก็เกิดแวบเปลี่ยน (Flashover) ไปแล้ว เด็กไม่รอดชีวิต คุณลืมไปว่าการฝ่าเข้าไปในตึกมักจะเร็วกว่าการถอยไปเริ่มใหม่จากภายนอก', zh: '💀 遗弃。等你从公寓撤出、跑回卡车、架好梯子并爬上去时，爆燃已经发生了。婴儿未能生还。你没意识到，通常直接穿过建筑内部要比重新组织外部进入快得多。' }, stats: { competence: 10, ethics: 10, leadership: -50, innovation: 0 } }
        ]
    },

    {
        id: 'fir_042',
        text: {
            en: '🚛 The Garbage Burn: A garbage truck is on fire in a residential alley. The driver says he saw a laptop battery start smoking before the whole load ignited. The fire is deep inside the hydraulic crusher. Hydraulic fluid could leak and explode at any moment.',
            th: '🚛 ไฟไหม้รถขยะ: รถขยะเกิดไฟไหม้ในซอยที่พักอาศัย คนขับบอกเขาเห็นแบตเตอรี่แล็ปท็อปเริ่มมีควันก่อนจะลามไปทั่ว ไฟอยู่ลึกเข้าไปในเครื่องบดไฮดรอลิก น้ำมันไฮดรอลิกอาจรั่วและระเบิดได้ทุกเมื่อ',
            zh: '🚛 垃圾车起火：一辆垃圾车在住宅区小巷起火。司机说在整车垃圾起火前，他看见一块笔记本电脑电池在冒烟。火源位于液压粉碎机深处。液压油随时可能泄漏并引发爆炸。'
        },
        options: [
            { id: 'A', text: { en: '🛡️ Dump the Load: "Dump the garbage on the street immediately! We can fight it spread out rather than inside the metal box!"', th: '🛡️ เทขยะทิ้ง: "เทขยะลงบนถนนเดี๋ยวนี้! เราดับไฟข้างนอกที่มันกระจายตัวได้ดีกว่าดับในกล่องเหล็ก!"', zh: 'A 倾倒垃圾：“立即把垃圾倒在街上！散开来灭火比在金属箱里容易得多！”' }, consequence: { en: '✅ Fast Suppression. It made a huge mess, but it worked. You prevented the truck from exploding and were able to extinguish the burning trash quickly. The sanitation department thanked you for saving their $300,000 truck.', th: '✅ ดับไฟได้รวดเร็ว มันอาจจะดูเลอะเทอะมากแต่ได้ผล คุณป้องกันไม่ให้รถระเบิดและดับขยะที่ไหม้อยูได้อย่างรวดเร็ว กรมความสะอาดขอบคุณที่คุณช่วยรถราคา 10 ล้านของเขาไว้ได้', zh: '✅ 快速扑灭。虽然场面很乱，但很奏效。你防止了卡车爆炸，并能迅速扑灭燃烧的垃圾。环卫部门感谢你保住了他们价值30万美元的卡车。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 20 } },
            { id: 'B', text: { en: '💦 Flood the Crusher: "No! Leave the load inside. Stick the nozzle in the cracks and flood the whole truck with water!"', th: '💦 ฉีดน้ำถล่มเครื่องบด: "ไม่! เก็บขยะไว้ข้างในนั่นแหละ เสียบหัวฉีดเข้าไปตามรอยแตกแล้วฉีดน้ำให้ท่วมรถ!"', zh: 'B 淹没粉碎机：“不！把垃圾留在里面。把水枪头塞进缝隙，用水淹没整辆车！”' }, consequence: { en: '😱 Hydraulic Rupture. The weight of the water combined with the heat caused a hydraulic line to burst. A 2,000-psi jet of burning oil shot out, severely burning a bystander. You also created a massive environmental cleanup problem from the slurry.', th: '😱 สายไฮดรอลิกระเบิด น้ำหนักของน้ำรวมกับความร้อนทำให้สายน้ำมันไฮดรอลิกแตก น้ำมันร้อนที่พุ่งออกมาด้วยแรงดัน 2,000 psi เผาไหม้คนแถวนั้นอย่างรุนแรง และคุณยังสร้างภาระในการขจัดคราบน้ำมันและขยะที่ปนเปื้อนน้ำมหาศาล', zh: '😱 液压爆裂。水的重量加上高温导致液压管线爆裂。一股2000 psi的燃烧油喷流射出，严重灼伤了一名旁观者。你还因为那些稀泥带来了巨大的环境清理难题。' }, stats: { competence: 20, ethics: 10, leadership: 10, innovation: 0 } },
            { id: 'C', text: { en: '💨 Use Dry Chemical: "Power tools and batteries. Use the big dry chem extinguishers from the rigs instead of water!"', th: '💨 ใช้ผงเคมีแห้ง: "เป็นพวกเครื่องใช้ไฟฟ้าและแบตเตอรี่ ใช้ถังเคมีแห้งขนาดใหญ่จากรถแทนที่จะใช้น้ำ!"', zh: 'C 使用干粉：“那是动力工具和电池。使用消防车上的大型干粉灭火器，别用水！”' }, consequence: { en: '⚠️ Ineffective. Dry chemical couldn\'t reach the deep-seated fire in the packed trash. The fire continued to grow until you finally had to use water anyway. You wasted 5 minutes and 10 extinguishers.', th: '⚠️ ไม่ได้ผล ผงเคมีแห้งเข้าไปไม่ถึงจุดที่ไฟไหม้ในกองขยะที่อัดแน่น ไฟยังคงลามต่อจนสุดท้ายคุณก็ต้องใช้น้ำอยู่ดี คุณเสียเวลาไป 5 นาทีและเปลืองถังดับเพลิงไป 10 ถัง', zh: '⚠️ 无效。干粉无法触及紧实垃圾深处的火源。火势继续蔓延，直到你最终还是不得不动用水。你白白浪费了5分钟和10个灭火器。' }, stats: { competence: 25, ethics: 20, leadership: 10, innovation: 0 } },
            { id: 'D', text: { en: '🧱 Foam and Seal: "Seal the back as best we can and pump it full of high-expansion foam to smother it!"', th: 'D อัดโฟมปิดตาย: "ปิดท้ายรถให้สนิทที่สุดแล้วอัดโฟมขยายตัวสูงเข้าไปให้เต็มเพื่อให้มันขาดอากาศ!"', zh: 'D 泡沫密封：“尽力密封后部，注满高倍数泡沫来闷熄火源！”' }, consequence: { en: '✅ Creative Engineering. The foam filled the voids between the trash bags and suppressed the oxygen. The fire went out without a drop of water touching the street. A very clean and professional save.', th: '✅ วิศวกรรมเชิงสร้างสรรค์ โฟมเข้าไปเติมเต็มช่องว่างระหว่างถุงขยะและกดออกซิเจนไว้ ไฟดับลงโดยไม่มีน้ำหยดลงถนนสักหยด เป็นการช่วยชีวิตที่สะอาดและมืออาชีพมาก', zh: '✅ 极具创意的工程方案。泡沫填满了垃圾袋之间的空隙并隔绝了氧气。没往街上滴一滴水火就灭了。非常干净且专业的营救。' }, stats: { competence: 45, ethics: 30, leadership: 30, innovation: 60 } }
        ]
    },

    {
        id: 'fir_043',
        text: {
            en: '🚔 The Chief\'s Nephew: A rookie firefighter—who happens to be the Fire Chief\'s nephew—committed a serious safety violation that could have killed someone. He is asking you to "leave it out of the report" so he can pass probation.',
            th: '🚔 หลานชายหัวหน้า: พนักงานใหม่—ซึ่งบังเอิญเป็นหลานชายของหัวหน้าใหญ่—ทำผิดระเบียบความปลอดภัยร้ายแรงที่เกือบจะทำคนตาย เขาขอร้องให้คุณ "ไม่ต้องเขียนลงในรายงาน" เพื่อให้เขาผ่านช่วงทดลองงาน',
            zh: '🚔 局长的外甥：一名新晋消防员——恰巧是消防局局长的外甥——犯下了严重的安全违规行为，险些导致人员伤亡。他请求你“在报告中别提这件事”，好让他通过试用期。'
        },
        options: [
            { id: 'A', text: { en: '📝 Write the Truth: "Safety comes first. I\'m reporting it exactly as it happened. Accountability saves lives."', th: '📝 เขียนความจริง: "ความปลอดภัยต้องมาก่อน ฉันจะรายงานตามที่เกิดขึ้นจริง ความรับผิดชอบช่วยรักษาชีวิตคนได้"', zh: '📝 书写真相：“安全第一。我会如实汇报发生的情况。问责制能拯救生命。”' }, consequence: { en: '✅ Integrity Pillar. The rookie was washed out of the program, and the Chief was initially angry, but later thanked you for preventing a future disaster. Your reputation for honesty makes you the prime candidate for Captain.', th: '✅ เสาหลักแห่งความซื่อสัตย์ พนักงานใหม่ถูกถอนชื่อออก ตอนแรกหัวหน้าโกรธมากแต่ต่อมาเขาก็มาขอบคุณที่คุณช่วยป้องกันหายนะที่อาจเกิดขึ้นในอนาคต ชื่อเสียงเรื่องความซื่อสัตย์ทำให้คุณเป็นตัวเก็งในการเลื่อนตำแหน่งเป็นผู้กอง', zh: '✅ 正直支柱。那个新手被开除了。局长最初很生气，但后来感谢你预防了未来的灾难。你诚实的声誉使你成为队长的首选人选。' }, stats: { competence: 40, ethics: 90, leadership: 60, innovation: 0 } },
            { id: 'B', text: { en: '🤝 Private Mentoring: "I\'ll leave it out this time, but you are training with me every weekend until you master this. One more mistake and you\'re gone."', th: '🤝 สอนส่วนตัว: "ครั้งนี้ฉันจะยังไม่เขียนลงไป แต่คุณต้องมาฝึกกับฉันทุกวันหยุดจนกว่าจะแม่น ถ้าพลาดอีกครั้งเดียวคือจบ"', zh: 'B 私下指导：“这次我不写进去，但每个周末你都要跟着我训练，直到掌握为止。再犯一次错你就走人。”' }, consequence: { en: '⚠️ Mixed Results. He became a great firefighter thanks to your training, but other crew members found out about the cover-up. You lost the trust of your team, and morale suffered because of the perceived favoritism.', th: '⚠️ ผลลัพธ์กึ่งกลาง เขากลายเป็นพนักงานดับเพลิงที่เก่งเพราะการฝึกของคุณ แต่ลูกทีมคนอื่นดันรู้เรื่องการปกปิดนี้ คุณสูญเสียความเชื่อมั่นจากทีม และขวัญกำลังใจก็แย่ลงเพราะมองว่าเป็นการเล่นพรรคเล่นพวก', zh: '⚠️ 结果毁誉参半。得益于你的训练，他成了一名优秀的消防员，但其他队员发现了这件事。你失去了团队的信任，士气也因为这种显而易见的不公正待遇而受挫。' }, stats: { competence: 30, ethics: 20, leadership: -40, innovation: 20 } },
            { id: 'C', text: { en: '🤷 Pass the Buck: "I\'m not signing the report. Let the Lieutenant decide what to do with him."', th: '🤷 โยนความรับผิดชอบ: "ฉันจะไม่เซ็นชื่อในรายงานนี้ ให้ผู้หมวดเป็นคนตัดสินใจเองว่าจะทำยังไงกับเขา"', zh: 'C 推卸责任：“我不在报告上签字。让中尉决定怎么处理他。”' }, consequence: { en: '❌ Leadership Fail. You avoided the conflict but showed that you can\'t handle tough decisions. The Lieutenant wrote a scathing review of YOUR lack of command presence. You were passed over for promotion.', th: '❌ ล้มเหลวในความเป็นผู้นำ คุณเลี่ยงปัญหาแต่แสดงให้เห็นว่าคุณรับมือกับการตัดสินใจที่ยากลำบากไม่ได้ ผู้หมวดเขียนวิจารณ์คุณอย่างรุนแรงเรื่องการขาดภาวะผู้นำ คุณพลาดการเลื่อนตำแหน่ง', zh: '❌ 领导力失败。你规避了冲突，但也表现出你无法处理艰难的抉择。中尉对你缺乏指挥魄力写下了严厉的评价。你错失了晋升机会。' }, stats: { competence: 10, ethics: 30, leadership: -60, innovation: 0 } },
            { id: 'D', text: { en: '📞 Call the Chief Privately: "Sir, your nephew messed up. I\'m handle it internally, but I wanted you to know as a courtesy."', th: 'D โทรหาหัวหน้าส่วนตัว: "ท่านครับ หลานท่านพลาดงานนี้ ผมจะจัดการภายในเองแต่ผมอยากเรียนให้ท่านทราบเพื่อเป็นมารยาท"', zh: 'D 私下给局长打电话：“局长，您外甥把事情搞砸了。我会内部处理，但出于礼貌我想让您知晓。”' }, consequence: { en: '💀 Political Suicide. The Chief saw this as an attempt at blackmail or "brown-nosing." He ordered a formal investigation into both of you. You are now the "rat" of the station, and nobody wants to work with you.', th: '💀 ฆ่าตัวตายทางการเมือง หัวหน้ามองว่านี่คือการแบล็กเมล์หรือการเลียแข้งเลียขา เขาสั่งให้สอบสวนทั้งคู่เป็นทางการ ตอนนี้คุณกลายเป็น "สายลับ" ในสายตาทุกคนในสถานี และไม่มีใครอยากร่วมงานกับคุณ', zh: '💀 政治自杀。局长认为这是在敲诈或“拍马屁”。他下令对你们两人展开正式调查。你现在成了消防站里的“内奸”，没人愿意和你一起工作。' }, stats: { competence: 20, ethics: 10, leadership: -50, innovation: 10 } }
        ]
    },

    {
        id: 'fir_044',
        text: {
            en: '⚡ The Substation Tsunami: A coastal electrical substation has been flooded by a large wave. The 50,000-volt transformers are partially submerged and arc-flashing spectacularly. A nearby residential area is losing power, and some houses are catching fire from the electrical surges.',
            th: '⚡ สึนามิลงสถานีไฟฟ้า: สถานีไฟฟ้าชายฝั่งถูกคลื่นยักษ์ซัดจนน้ำท่วม หม้อแปลงแรงดัน 50,000 โวลต์จมน้ำอยู่บางส่วนและเกิดการลุกไหม้ของไฟฟ้า (Arc-flash) อย่างน่ากลัว ย่านพักอาศัยแถวนั้นไฟดับ และบ้านบางหลังกำลังไฟไหม้จากการกระชากของไฟฟ้า',
            zh: '⚡ 变电站海啸：沿海的一座变电站被巨浪淹没。5万伏的变压器部分没入水中，正爆发出惊人的电弧火花。附近住宅区断电，一些房屋因电压浪涌而起火。'
        },
        options: [
            { id: 'A', text: { en: '🚫 Do Not Enter: "Water + 50kV = Death. We protect the exposures only. Stay 500 feet back until the grid is confirmed dead!"', th: '🚫 ห้ามเข้า: "น้ำ + 50kV = ตาย คุ้มกันพื้นที่รอบๆ อย่างเดียว อยู่ห่างออกมา 500 ฟุตจนกว่าจะยืนยันว่าตัดไฟแล้ว!"', zh: 'A 严禁进入：“水 + 5万伏 = 死亡。我们仅保护周边。在确认电网断电前，保持500英尺距离！”' }, consequence: { en: '✅ Professional Restraint. You saved your team. Entering standing water near high-voltage gear is suicide. You deployed your pumps to stop the house fires from the outside. You are a safe and reliable officer.', th: '✅ การยับยั้งชั่งใจอย่างมืออาชีพ คุณช่วยทีมไว้ได้ การเดินเข้าน้ำที่ท่วมใกล้เครื่องใช้ไฟฟ้าแรงดันสูงคือการฆ่าตัวตาย คุณใช้ปั๊มน้ำดับไฟที่บ้านจากภายนอกแทน คุณเป็นเจ้าหน้าที่ที่ปลอดภัยและพึ่งพาได้', zh: '✅ 专业克制。你救了小队。进入高压设备附近的积水中等同于自杀。你部署水泵从外部扑灭民房火灾。你是一名安全可靠的长官。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 0 } },
            { id: 'B', text: { en: '🚤 Boat Rescue: "Load the Zodiac boat! We can float over the water and use the dry chem on those transformers!"', th: '🚤 กู้ภัยด้วยเรือ: "เตรียมเรือยาง Zodiac! เราลอยไปเหนือน้ำแล้วใช้ผงเคมีแห้งดับหม้อแปลงพวกนั้นได้!"', zh: 'B 小艇救援：“装载橡皮艇！我们可以漂在水面上，对那些变压器使用干粉！”' }, consequence: { en: '💀 Electrocution. Water is not the only conductor. The high-voltage arc jumped to the aluminum motor of your boat, electrocuting your entire crew instantly. You failed to realize that 50kV can jump huge gaps through ionized air.', th: '💀 ไฟดูด น้ำไม่ใช่ตัวนำอย่างเดียว แรงอาร์กของไฟแรงสูงกระโดดเข้าหาเครื่องยนต์อลูมิเนียมของเรือ และดูดลูกทีมตายหมด คุณไม่รู้ว่าไฟ 50kV สามารถกระโดดข้ามช่องว่างใหญ่ๆ ผ่านอากาศที่แตกตัวเป็นไอออนได้', zh: '💀 触电身亡。水并非唯一的导体。高压电弧跳向小艇的铝质发动机，瞬间导致全船人员触电。你没能意识到5万伏电压可以通过电离空气跨越巨大的间隙。' }, stats: { competence: 10, ethics: 20, leadership: -40, innovation: 30 } },
            { id: 'C', text: { en: '💧 Use Distilled Water: "If we use ultra-purified water, it won\'t conduct! Spray them from the helicopter!"', th: '💧 ใช้น้ำกลั่น: "ถ้าเราใช้น้ำบริสุทธิ์สูง มันจะไม่นำไฟฟ้า! ฉีดพ่นลงมาจากเฮลิคอปเตอร์สิ!"', zh: 'C 使用蒸馏水：“如果用超纯水，它就不会导电了！从直升机上喷洒！”' }, consequence: { en: '❌ Scientific Myth. As soon as the distilled water leaves the nozzle and touches the smoke/salt-air, it picks up ions and becomes highly conductive. One drop touched the transformer and the arc traveled back up the stream to the heli. A disaster.', th: '❌ ความเชื่อทางวิทยาศาสตร์ที่ผิด ทันทีที่น้ำกลั่นออกจากหัวฉีดและสัมผัสควันหรืออากาศเค็ม มันจะเก็บไอออนและนำไฟฟ้าได้ดีเยี่ยม แค่หยดเดียวโดนหม้อแปลง แรงอาร์กวิ่งย้อนสายน้ำกลับไปหาเฮลิคอปเตอร์ หายนะโดยสมบูรณ์', zh: '❌ 科学误区。蒸馏水一旦离开喷头并接触到烟雾或盐分空气，就会吸收离子并变得高度导电。一滴水触碰到变压器，电弧便顺着水流直上直升机。这是一场灾难。' }, stats: { competence: 15, ethics: 10, leadership: 10, innovation: 50 } },
            { id: 'D', text: { en: '🧱 Create a Berm: "Use the bulldozer to push sand into the water. Drain the area around the transformers so we can safely approach."', th: 'D สร้างแนวคันดิน: "ใช้รถแทรกเตอร์ดันทรายลงไปในน้ำ ระบายน้ำรอบๆ หม้อแปลงออก เราจะได้เข้าไปได้อย่างปลอดภัย"', zh: 'D 筑堤隔离：“开推土机把沙子推入水中。排干变压器周围的水，这样我们就能安全靠近。”' }, consequence: { en: '✨ Engineering Solution. It worked! By diverting the seawater, the transformers cooled down and the arcing stopped. You regained access and allowed the power company to safely pull the main breakers. Innovative and effective.', th: '✨ ทางออกเชิงวิศวกรรม ได้ผล! การเบี่ยงทางน้ำทะเลทำให้หม้อแปลงเย็นลงและการอาร์กหยุดลง คุณเข้าถึงพื้นที่ได้และช่วยให้บริษัทไฟฟ้าสับเบรกเกอร์หลักได้อย่างปลอดภัย นวัตกรรมที่ยอดเยี่ยม', zh: '✨ 工程解决方案。奏效了！通过分流海水，变压器降温且电弧停止。你重新获得了进入权限，并让电力公司得以安全拉开主断路器。既创新又有效。' }, stats: { competence: 40, ethics: 30, leadership: 40, innovation: 80 } }
        ]
    },

    {
        id: 'fir_045',
        text: {
            en: '✈️ The General Aviation Crash: A small private plane has crashed into a house in the suburbs. The cockpit is embedded in the kitchen. Fuel (AvGas) is pouring into the basement through the floor. The pilot is unconscious but breathing. The house residents are screaming from the second floor.',
            th: '✈️ เครื่องบินเล็กตก: เครื่องบินส่วนตัวขนาดเล็กตกใส่บ้านในย่านชานเมือง ห้องนักบินฝังอยู่ในห้องครัว น้ำมันเครื่องบิน (AvGas) กำลังไหลลงห้องใต้ดิน เหยื่อที่เป็นนักบินหมดสติแต่ยังหายใจอยู่ ผู้อยู่อาศัยในบ้านกำลังกรีดร้องเสียงดังจากชั้นสอง',
            zh: '✈️ 小型飞机坠毁：一架小型私人飞机坠入郊区的一栋住宅。驾驶舱嵌入了厨房。航空汽油正顺着地板流进地下室。飞行员昏迷但尚有呼吸。屋内的居民在二楼尖叫。'
        },
        options: [
            { id: 'A', text: { en: '🛡️ Foam and Rescue: "Blanket the kitchen with AFFF foam immediately! Team 2, get the residents out via the windows. I\'m pulling the pilot out now!"', th: '🛡️ ฉีดโฟมและช่วยเหลือ: "ฉีดโฟม AFFF คลุมห้องครัวทันที! ทีม 2 นำคนในบ้านออกมาทางหน้าต่าง ฉันจะไปลากนักบินออกมาเดี๋ยวนี้!"', zh: 'A 泡沫与营救：“立即用AFFF泡沫覆盖厨房！二组，通过窗户救出居民。我现在就把飞行员拉出来！”' }, consequence: { en: '✅ Perfect Rescue. You addressed the fuel hazard first. By evacuating the residents through the windows, you avoided the "fuel-soaked" kitchen entirely. You saved all four people. Your knowledge of airplane fuel (AvGas) flashpoints saved the day.', th: '✅ การช่วยเหลือที่สมบูรณ์แบบ คุณจัดการอันตรายจากน้ำมันก่อน การอพยพคนออกทางหน้าต่างทำให้เลี่ยงห้องครัวที่ชุ่มน้ำมันได้ทั้งหมด คุณช่วยชีวิตคนได้ทั้ง 4 คน ความรู้เรื่องจุดวูบไฟของน้ำมันเครื่องบินช่วยให้งานรุ่ง', zh: '✅ 完美的营救。你首先处理了燃油风险。通过窗户疏散居民，你完全避开了被燃油浸透的厨房。你救下了全部四个人。你对航空汽油闪点的了解挽救了局面。' }, stats: { competence: 50, ethics: 40, leadership: 40, innovation: 20 } },
            { id: 'B', text: { en: '🏃 Priority Pilot: "Save the pilot! We need to cut the fuselage before the fuel ignites! Residents can wait, they are safe for now."', th: '🏃 ช่วยนักบินก่อน: "ช่วยนักบิน! เราต้องตัดลำตัวเครื่องก่อนน้ำมันจะติดไฟ! คนในบ้านรอก่อนได้ ตอนนี้เขายังปลอดภัย"', zh: 'B 飞行员优先：“先救飞行员！我们要在燃油起火前切开机身！居民可以等等，他们现在是安全的。”' }, consequence: { en: '😱 Tactical Mistake. While you were cutting the pilot out, a spark from the saw ignited the AvGas fumes. The fire shot up the stairs and trapped the residents. You saved the pilot but lost a family of three. You should have evacuated the residents first.', th: '😱 ความผิดพลาดทางยุทธวิธี ขณะที่คุณกำลังตัดช่วยนักบิน ประกายไฟจากเลื่อยก็จุดติดไอระเหยน้ำมัน ไฟพุ่งขึ้นบันไดไปขังคนในบ้านไว้ คุณช่วยนักบินได้แต่เสียคนในบ้านไป 3 คน คุณควรพาคนในบ้านออกมาเป็นอันดับแรก', zh: 'B 战术错误。在你切开机身救援飞行员时，锯子产生的火花引燃了航空汽油蒸汽。大火顺着楼梯向上窜，困住了居民。你救了飞行员，却失去了一家三口。你本该先疏散居民。' }, stats: { competence: 20, ethics: 20, leadership: 10, innovation: 0 } },
            { id: 'C', text: { en: '💦 Massive Water Stream: "Dump the master stream into the kitchen! Dilute the fuel and wash it into the sewer!"', th: '💦 ฉีดน้ำมหาศาล: "ระดมหัวฉีดหลักอัดเข้าห้องครัว! เจือจางน้ำมันแล้วล้างมันลงท่อระบายน้ำไปเลย!"', zh: 'C 巨量水流：“向厨房灌注主水流！稀释燃油并将其冲进下水道！”' }, consequence: { en: '💀 Explosion. AvGas floats on water. By dumping more water, you just spread the burning fuel across the entire first floor. It also flooded the basement where the pilot was trapped. You caused the very disaster you were trying to prevent.', th: '💀 ระเบิด น้ำมันเครื่องบินลอยเหนือน้ำ การฉีดน้ำเพิ่มแค่ช่วยให้น้ำมันที่ไหม้อยู่กระจายไปทั่วชั้นหนึ่ง และยังไปท่วมห้องใต้ดินที่นักบินติดอยู่ด้วย คุณกลายเป็นคนสร้างหายนะที่พยายามจะป้องกัน', zh: '💀 爆炸。航空汽油漂浮在水面上。通过倾倒更多的水，你反而把燃烧的燃油扩散到了整个一层。此外，燃油还淹没了飞行员被困的地下室。你亲手制造了你试图预防的灾难。' }, stats: { competence: 10, ethics: 20, leadership: -40, innovation: 0 } },
            { id: 'D', text: { en: '🛡️ Neutralize the Battery: "Find the aircraft battery! Cut the master switch before we do anything else. No sparks!"', th: 'D ตัดระบบไฟ: "หาแบตเตอรี่เครื่องบิน! ตัดสวิตช์หลักก่อนทำอย่างอื่น ห้ามมีประกายไฟเด็ดขาด!"', zh: 'D 断开电池连接：“找到飞机电池！在做任何其他事情之前切断主开关。严禁火花！”' }, consequence: { en: '✅ Tactical Safety. A simple move that prevented any electrical fire. With the power dead, you worked with less fear of a sudden ignite. It bought you the time needed to perform a systematic rescue. Professional ARFF training showing through.', th: '✅ ความปลอดภัยทางยุทธวิธี การตัดสินใจง่ายๆ ที่ป้องกันไฟจากไฟฟ้าลัดวงจร เมื่อไม่มีไฟคุณก็ทำงานได้โดยไม่ต้องกลัวการติดไฟกะทันหัน มันช่วยให้คุณมีเวลาช่วยชีวิตอย่างเป็นระบบ ทักษะ ARFF มืออาชีพแสดงออกมาให้เห็น', zh: '✅ 战术安全。这一简单的举动防止了任何电气火灾。随着电源切断，你在工作时减少了对突发着火的恐惧。这为你赢得了进行系统营救所需的时间。展现出了专业的机场消防救援（ARFF）训练水平。' }, stats: { competence: 40, ethics: 30, leadership: 30, innovation: 40 } }
        ]
    },

    {
        id: 'fir_046',
        text: {
            en: '🏗️ The Escalator Entrapment: A child\'s leg is caught in the teeth of a heavy-duty mall escalator. The emergency stop was hit, but the metal "comb" is digging deep into the bone. The escalator mechanics are 30 minutes away.',
            th: '🏗️ แขนขาติดบันไดเลื่อน: ขาลูกของเด็กคนหนึ่งติดอยู่ในซี่กรงของบันไดเลื่อนหอสรรพสินค้าขนาดใหญ่ มีคนกดหยุดฉุกเฉินแล้วแต่ "ซี่หวี" โลหะกำลังเจาะลึกเข้าไปในกระดูก ช่างซ่อมบันไดเลื่อนต้องใช้เวลาอีก 30 นาทีกว่าจะมาถึง',
            zh: '🏗️ 自动扶梯受困：一个孩子的腿被卷进商场重型扶梯的梳齿板里。虽然已经按下了紧急停止钮，但金属“梳齿”已深陷骨头。扶梯维修工要在30分钟后才能到达。'
        },
        options: [
            { id: 'A', text: { en: '🪓 Breach with Hydraulics: "Get the mini-spreader! Pop that step up just 2 inches so we can slide the leg out!"', th: '🪓 ใช้เครื่องมือไฮดรอลิกเจาะ: "เอาเครื่องถ่างจิ๋วมา! งัดขั้นบันไดขึ้นมาแค่ 2 นิ้วเราจะได้ดึงขาออกมาได้!"', zh: 'A 液压破拆：“拿微型扩张器来！把台阶撬起两英寸，我们就把腿抽出来！”' }, consequence: { en: '✅ Precision Rescue. The mini-spreader was the perfect tool. You created just enough space to free the child without causing more tissue damage. They saved the leg. You are a master of technical rescue.', th: '✅ การช่วยชีวิตที่แม่นยำ เครื่องถ่างจิ๋วคือเครื่องมือที่เพอร์เฟกต์ คุณสร้างช่องว่างได้พอดีพอที่จะดึงเด็กออกมาโดยไม่ทำลายเนื้อเยื่อเพิ่ม หมอช่วยรักษาขาไว้ได้ คุณคือมาสเตอร์ด้านการกู้ภัยทางเทคนิค', zh: '✅ 精准营救。微型扩张器是完美的工具。你创造了足够的空间救出孩子，且没有造成更多的组织损伤。他们保住了那条腿。你是技术救援大师。' }, stats: { competence: 50, ethics: 40, leadership: 30, innovation: 40 } },
            { id: 'B', text: { en: '🛠️ Reverse the Motor: "I found the manual override! I\'ll turn the motor backward to spit the leg out!"', th: '🛠️ ย้อนกลับมอเตอร์: "ฉันเจอระบบปรับแต่งเองแล้ว! ฉันจะหมุนมอเตอร์ย้อนกลับเพื่อคลายขาออกมา!"', zh: 'B 电机反转：“我找到了手动覆盖装置！我要让电机反向转动，把腿退出来！”' }, consequence: { en: '💀 Amputation. Escalator gears are designed for one-way movement. Reversing it caused the "comb" to snap together like a trap, severing the child\'s foot. Never attempt to reverse heavy industrial machinery with a person inside. A horrific error.', th: '💀 ขาขาด! ฟันเฟืองบันไดเลื่อนถูกออกแบบมาให้หมุนทางเดียว การหมุนย้อนกลับทำให้ "ซี่หวี" ดีดเข้าหากันเหมือนกับดักและตัดเท้าเด็กขาด ห้ามหมุนย้อนกลับเครื่องจักรหนักที่มีคนติดอยู่เด็ดขาด ความผิดพลาดที่น่าสยดสยอง', zh: '💀 截肢。扶梯齿轮设计为单向运动。反向运行导致“梳齿”像捕鼠器一样咬合在一起，切断了孩子的脚。绝不要试图在有人受困时反转重型工业机械。这是个可怕的错误。' }, stats: { competence: 10, ethics: 10, leadership: -40, innovation: 30 } },
            { id: 'C', text: { en: '🧊 Ice and Lube: "Pour liquid soap and ice on the leg. Shrink the swelling and slide them out without prying."', th: '🧊 น้ำแข็งและสารหล่อลื่น: "เทสบู่เหลวและน้ำแข็งลงที่ขา ลดอาการบวมแล้วสไลด์ออกมาโดยไม่ต้องงัด"', zh: 'C 冰敷润滑：“在腿上涂液体肥皂，再敷上冰。减轻肿胀，不用撬就能把腿滑出来。”' }, consequence: { en: '⚖️ Patient and Slow. It took 15 minutes, but the leg slid out with only minor lacerations. No heavy tools needed. You prioritized the patient\'s trauma over "speedy rescue." The parents are immensely grateful.', th: '⚖️ อดทนและค่อยเป็นค่อยไป ใช้เวลา 15 นาทีแต่ขาก็สไลด์ออกมาได้โดยมีแผลฉีกขาดเพียงเล็กน้อย ไม่ต้องใช้เครื่องมือหนัก คุณจัดลำดับความสำคัญให้ความเจ็บปวดของผู้ป่วยมาก่อนความเร็ว พ่อแม่ซาบซึ้งใจมาก', zh: '⚖️ 耐心稳健。花了15分钟，但腿部仅受轻微割伤便成功滑出。不需要重型工具。你将病人的创伤控制置于“急速营救”之上。家长对此感激不尽。' }, stats: { competence: 40, ethics: 40, leadership: 30, innovation: 50 } },
            { id: 'D', text: { en: '🪚 Cut the Rail: "Get the circular saw! Cut the adjacent metal steps to give us room to work."', th: 'D ตัดราว: "เอาเลื่อยวงเดือนมา! ตัดขั้นบันไดเหล็กข้างๆ เราจะได้มีพื้นที่ทำงาน"', zh: 'D 切断踏板：“拿圆锯来！切开相邻的金属台阶，为我们腾出工作空间。”' }, consequence: { en: '😱 Fire Danger. The sparks from the saw ignited the grease inside the escalator. You started a fire directly underneath the trapped child. You turned a technical rescue into a fire emergency. Total confusion on the scene.', th: '😱 อันตรายจากไฟ ประกายไฟจากเลื่อยจุดติดจาระบีข้างในบันไดเลื่อน คุณเริ่มไฟไหม้ข้างใต้ตัวเด็กที่ติดอยู่พอดี คุณเปลี่ยนจากการช่วยชีวิตทางเทคนิคให้กลายเป็นเหตุไฟไหม้ฉุกเฉิน ที่เกิดเหตุวุ่นวายไปหมด', zh: '😱 火灾危险。锯子产生的火花点燃了扶梯内部的润滑油。你在受困孩子身体正下方引发了火灾。你把一起技术救援变成了火灾紧急情况。现场陷入一片混乱。' }, stats: { competence: 15, ethics: 10, leadership: -30, innovation: 0 } }
        ]
    },

    {
        id: 'fir_047',
        text: {
            en: '🗼 The Wind Turbine: A technician is hanging by his safety harness 300 feet in the air from a wind turbine. He has "Harness Hang Syndrome" (blood pooling in legs) and will lose consciousness in 10 minutes. Your high-angle team is on the ground.',
            th: '🗼 กังหันลม: ช่างเทคนิคห้อยต้อยแต่งอยู่บนสายรัดนิรภัยกลางอากาศ 300 ฟุตจากกังหันลม เขามีอาการ "Harness Hang Syndrome" (เลือดกองที่ขา) และจะหมดสติใน 10 นาที ทีมกู้ภัยในที่สูงของคุณอยู่ด้านล่าง',
            zh: '🗼 风力发电机：一名技术人员被安全吊带挂在300英尺的高空风力发电机上。他正遭受“吊带悬挂综合症”（血液在腿部淤积），并将在10分钟内失去意识。你的高空搜救小组正在地面。'
        },
        options: [
            { id: 'A', text: { en: '🧗 Technical Climb: "Gear up! We\'re doing a pick-off. I\'m climbing the ladder inside and rappelling down to him!"', th: '🧗 ปีนทางเทคนิค: "เตรียมตัว! เราจะทำเคส Pick-off ฉันจะปีนบันไดข้างในแล้วโรยตัวลงไปหาเขา!"', zh: 'A 技术攀爬：“全副武装！我们要进行空中接力营救。我从内部爬梯上去，然后降落到他身边！”' }, consequence: { en: '✅ Expert High-Angle. You reached him in 8 minutes, attached a secondary line, and lowered him to the ground. You saved his life just before he blacked out. Your training in high-angle rescue paid off perfectly.', th: '✅ การกู้ภัยในที่สูงระดับผู้เชี่ยวชาญ คุณไปถึงตัวเขาใน 8 นาที ต่อสายสำรองและหย่อนเขาลงพื้นดิน คุณช่วยชีวิตเขาได้ทันก่อนจะหมดสติ การฝึกฝนกู้ภัยในที่สูงของคุณให้ผลลัพธ์ที่สมบูรณ์แบบ', zh: '✅ 专业高空作业。你在8分钟内到达他身边，系上副绳，并将他降至地面。就在他昏迷前一刻，你救了他的命。你在高空救援方面的训练得到了完美的体现。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 10 } },
            { id: 'B', text: { en: '🚁 Helicopter Lift: "Request a Coast Guard helicopter immediately. We can\'t climb 300 feet fast enough!"', th: '🚁 ใช้เฮลิคอปเตอร์: "ขอเฮลิคอปเตอร์ยามฝั่งด่วน! เราปีนขึ้นไป 300 ฟุตไม่ทันแน่!"', zh: 'B 直升机吊升：“立即请求海岸警卫队直升机支援。我们爬300英尺没这么快！”' }, consequence: { en: '⚠️ Delayed Response. The helicopter took 15 minutes to arrive. By the time they reached him, he was unconscious and suffered permanent nerve damage in his legs. You should have relied on your own team\'s speed.', th: '⚠️ การตอบสนองที่ล่าช้า เฮลิคอปเตอร์ต้องใช้เวลา 15 นาทีกว่าจะมาถึง กว่าจะไปถึงตัวเขา เขาก็หมดสติและเกิดความเสียหายถาวรที่ประสาทขา คุณควรเชื่อมั่นในความเร็วของทีมตัวเองมากกว่า', zh: '⚠️ 延迟响应。直升机花了15分钟才到达。当他们接触到他时，他已失去意识，且腿部遭受了永久性神经损伤。你本该依赖自己团队的速度。' }, stats: { competence: 30, ethics: 20, leadership: 10, innovation: 0 } },
            { id: 'C', text: { en: '🏹 Bow and Arrow: "Shoot a pilot line over the turbine blade and pull up a hauling system!"', th: '🏹 ธนูและลูกศร: "ยิงสายนำข้ามใบพัดกังหันแล้วดึงระบบยกของขึ้นไป!"', zh: 'C 弓弩抛绳：“对着风机叶片上方发射引导绳，并拉起一套滑轮牵引系统！”' }, consequence: { en: '❌ Tactical Fail. The wind was too high. The line got tangled in the rotating hub, causing an electrical short that sparked a fire in the turbine. You turned a rescue into a fire and put the victim in even more danger.', th: '❌ ล้มเหลวทางยุทธวิธี ลมแรงเกินไป สายไปพันเข้ากับแกนหมุนทำให้ไฟฟ้าลัดวงจรจนเกิดไฟไหม้ในกังหัน คุณเปลี่ยนจากการช่วยชีวิตให้กลายเป็นไฟไหม้และทำให้เหยื่อตกอยู่ในอันตรายยิ่งขึ้น', zh: '❌ 战术失败。风力太大。绳子缠绕在旋转的轴毂上，引发短路导致发电机起火。你把救援演变成了火灾，让受害者陷入了更大的危险。' }, stats: { competence: 15, ethics: 10, leadership: 10, innovation: 60 } },
            { id: 'D', text: { en: '🏗️ Use a Man-Basket: "Is there a construction crane nearby? Use a man-basket to lift two rescuers to the nacelle."', th: 'D ใช้ตะกร้าเครน: "มีเครนก่อสร้างแถวนี้ไหม? ใช้ตะกร้ายกพนักงานกู้ภัยสองคนขึ้นไปที่ตัวกังหัน"', zh: 'D 使用载人吊篮：“附近有施工起重机吗？用载人吊篮把两名搜救员升到机舱位置。”' }, consequence: { en: '⚖️ Industrial Cooperation. You found a crane at a nearby site. It took 9 minutes to setup, but you were able to reach the technician safely and perform medical care while lowering him. A very safe, stable technical win.', th: '⚖️ ความร่วมมือทางอุตสาหกรรม คุณเจอเครนที่ไซต์ก่อสร้างใกล้ๆ ใช้เวลา 9 นาทีเพื่อเตรียมการ แต่คุณเข้าถึงช่างเทคนิคได้อย่างปลอดภัยและปฐมพยาบาลได้ระหว่างหย่อนเขาลงมา เป็นชัยชนะทางเทคนิคที่ปลอดภัยและมั่นคงมาก', zh: '⚖️ 跨行业协作。你在附近的工地发现了一台起重机。架设花了9分钟，但你得以安全接触到技术人员，并在降落过程中进行了医疗护理。一次非常安全、稳定的技术胜利。' }, stats: { competence: 40, ethics: 30, leadership: 40, innovation: 40 } }
        ]
    },

    {
        id: 'fir_048',
        text: {
            en: '🏟️ The Stadium Ammonia Leak: An ammonia refrigerant line has burst in the basement of a professional sports stadium during a game with 50,000 spectators. The gas is rising through the ventilation system. You can see a white cloud forming on the field.',
            th: '🏟️ แอมโมเนียรั่วในในสนามกีฬา: สายน้ำยาแอมโมเนียระเบิดในห้องใต้ดินของสนามกีฬาอาชีพในขณะที่มีคนดู 50,000 คน ก๊าซกำลังลอยขึ้นผ่านระบบระบายอากาศ คุณเห็นเมฆสีขาวเริ่มก่อตัวบนสนาม',
            zh: '🏟️ 体育场氨气泄漏：在一场有5万名观众的比赛期间，体育场地下室的一条氨制冷管线爆裂。气体正顺着通风系统上升。你能看见球场上正形成一团白烟。'
        },
        options: [
            { id: 'A', text: { en: '🚨 Immediate Evacuation: "Pull the fire alarm! Get everyone out now! This is a mass-casualty event if we stay!"', th: '🚨 อพยพทันที: "กดสัญญาณเตือนไฟไหม้! นำทุกคนออกไปเดี๋ยวนี้! ถ้าอยู่อาจมีคนเจ็บตายหมู่!"', zh: 'A 立即疏散：“拉响火警！现在就让所有人撤离！如果不走，这就是场大规模伤亡事件！”' }, consequence: { en: '😱 Panic Trample. The sudden alarm caused a massive panic. 15 people were crushed to death in the stampede to the exits. The ammonia was eventually contained, but the "rescue" caused more deaths than the gas would have. You failed to manage the crowd psychology.', th: '😱 การเหยียบกันตายที่น่ากลัว สัญญาณเตือนที่กะทันหันทำให้เกิดความตื่นตระหนกครั้งใหญ่ มีคน 15 คนถูกเหยียบตายขณะแย่งกันออกทางออก แอมโมเนียถูกควบคุมได้ในที่สุด แต่การ "ช่วยชีวิต" ของคุณทำให้มีคนตายมากกว่าก๊าซเสียอีก คุณล้มเหลวในการจัดการเด็จจิตวิทยาฝูงชน', zh: '😱 惊慌踩踏。突如其来的警报引起了巨大的恐慌。在跑向出口的推搡中，有15人被踩踏致死。氨气最终被控制住了，但这场“营救”导致的死亡人数比气体本身可能的还要多。你未能管理好人群心理。' }, stats: { competence: 20, ethics: 10, leadership: -40, innovation: 0 } },
            { id: 'B', text: { en: '💨 Reverse the Ventilation: "Don\'t alarm the crowd yet. Get to the control room! Reverse the fans to blow the gas OUT of the building!"', th: '💨 ย้อนกลับระบบระบายอากาศ: "อย่าเพิ่งทำให้คนตื่นตระหนก ไปที่ห้องควบคุม! ย้อนพัดลมเพื่อเป่าก๊าซออกไปนอกตัวตึก!"', zh: 'B 反转通风系统：“先不要惊动观众。去控制室！反转风机，把气体吹出大楼！”' }, consequence: { en: '✅ Strategic Brilliance. By reversing the airflow, you kept the ammonia in the basement and vented it out the service tunnels. Most spectators didn\'t even know there was an emergency. You prevented a disaster through calm, technical action.', th: '✅ อัจฉริยภาพเชิงกลยุทธ์ การหมุนทิศทางลมช่วยกักแอมโมเนียไว้ในห้องใต้ดินและระบายออกทางอุโมงค์เซอร์วิส คนดูส่วนใหญ่ไม่รู้ด้วยซ้ำว่ามีเหตุฉุกเฉิน คุณป้องกันหายนะได้ด้วยความใจเย็นและการปฏิบัติที่เป็นเทคนิค', zh: '✅ 战略才智。通过反转气流，你将氨气控制在了地下室，并从服务隧道排出。大多数观众甚至不知道发生了紧急情况。你通过冷静的技术行动预防了一场灾难。' }, stats: { competence: 50, ethics: 40, leadership: 40, innovation: 70 } },
            { id: 'C', text: { en: '🛡️ Fog Curtain: "Get inside with fog nozzles! We need to knock down the ammonia cloud on the field with water spray!"', th: '🛡️ ม่านน้ำหมอก: "เข้าไปข้างในด้วยหัวฉีดหมอก! เราต้องกดเมฆแอมโมเนียบนสนามด้วยละอองน้ำ!"', zh: 'C 水雾幕：“带上雾状喷头进去！我们需要用水雾压制球场上的氨气云！”' }, consequence: { en: '⚠️ Dangerous Success. Water absorbs ammonia, turning it into ammonium hydroxide (a liquid acid). You cleared the air but turned the playing field into a chemical burn hazard. Players were injured by the runoff. You solved one problem but created another.', th: '⚠️ ความสำเร็จที่อันตราย น้ำจะดูดซับแอมโมเนียและเปลี่ยนเป็นแอมโมเนียมไฮดรอกไซด์ (กรดเหลว) คุณทำให้อากาศสะอาดแต่ทำให้ในสนามกลายเป็นพื้นที่เสี่ยงสารเคมีลวก นักกีฬาได้รับบาดเจ็บจากน้ำปนเปื้อน คุณแก้ปัญหาหนึ่งแต่สร้างอีกปัญหาหนึ่ง', zh: '⚠️ 危险的成功。水吸收氨气后会变成氢氧化氨（一种液体酸）。你净化了空气，但把球场变成了化学灼伤危险区。运动员因流出的液体而受伤。你解决了一个问题，却制造了另一个。' }, stats: { competence: 35, ethics: 20, leadership: 30, innovation: 20 } },
            { id: 'D', text: { en: '🧪 Patch the Leak: "Team 1, get into Level A suits! We\'re going into the basement to close the main valve manually!"', th: 'D อุดจุดรั่ว: "ทีม 1 ใส่ชุด Level A! เราจะลงไปในห้องใต้ดินเพื่อปิดวาล์วหลักด้วยมือ!"', zh: 'D 修补泄漏：“一组，穿上A级防护服！我们要去地下室手动关闭主阀门！”' }, consequence: { en: '✅ Textbook Hazmat. You addressed the source of the problem. While it was high-risk for your team, it was the only way to stop the gas flow completely. You performed a perfect "Hot Zone" entry and saved the day.', th: '✅ ตามระเบียบ Hazmat คุณจัดการที่ต้นตอของปัญหา แม้จะเสี่ยงสูงสำหรับทีมของคุณ แต่มันคือวิธีเดียวที่จะหยุดก๊าซได้ถาวร คุณเข้าสู่ "Hot Zone" ได้อย่างสมบูรณ์แบบและช่วยให้สถานการณ์คลี่คลาย', zh: '✅ 教科书级的危化品处置。你从源头解决了问题。虽然对你的团队来说风险很大，但这是彻底停止气体泄漏的唯一方法。你完成了一次完美的“热区”进入，化险为夷。' }, stats: { competence: 50, ethics: 30, leadership: 40, innovation: 10 } }
        ]
    },

    {
        id: 'fir_049',
        text: {
            en: '🤝 The Mutual Aid Clash: You are the Incident Commander at a large factory fire. A volunteer fire department from the next county arrives. Their chief is older and is refusing to take orders from you because you are "just a city boy." He is about to send his men into an unsafe building.',
            th: '🤝 ความขัดแย้งของหน่วยสนับสนุน: คุณเป็นผู้บัญชาการเหตุการณ์ในเหตุไฟไหม้โรงงานขนาดใหญ่ หน่วยดับเพลิงอาสาสมัครจากอำเภอข้างๆ มาถึง หัวหน้าของเขาแก่กว่าและปฏิเสธที่จะรับคำสั่งจากคุณเพราะคุณเป็นแค่ "เด็กในเมือง" เขากำลังจะส่งพนักงานของเขาเข้าไปในอาคารที่ไม่ปลอดภัย',
            zh: '🤝 互助冲突：你是一起大型工厂火灾的现场指挥员。来自相邻县的一支志愿消防队到达了。他们的队长年纪较大，拒绝听从你的命令，因为你“只是个城里娃”。他正准备派他的人进入一栋不安全的建筑。'
        },
        options: [
            { id: 'A', text: { en: '🛡️ Command Authority: "Chief, look at me. I am the IC. If you enter that building, I will have your department\'s charter revoked. Stay back or leave the scene!"', th: '🛡️ อำนาจการสั่งการ: "หัวหน้า มองผมนะ ผมคือผู้บัญชาการเหตุการณ์ ถ้าคุณเข้าตึกนั้น ผมจะสั่งเพิกถอนใบอนุญาตหน่วยงานของคุณ ถอยไปหรือออกจากพื้นที่ไปเลย!"', zh: 'A 维持指挥权威：“队长，看着我。我是现场指挥。如果你进入那栋建筑，我会吊销你们队的执照。退后，或者离开现场！”' }, consequence: { en: '✅ Strict Leadership. He was furious but he backed down. Minutes later, the roof collapsed exactly where his men would have been. You saved their lives through sheer force of will. The state board later upheld your authority.', th: '✅ ความเป็นผู้นำที่เข้มงวด เขาโกรธมากแต่ก็ยอมถอย ไม่กี่นาทีต่อมา หลังคาก็ถล่มลงมาตรงจุดที่ลูกน้องเขาจะเข้าไปพอดี คุณช่วยชีวิตพวกเขาไว้ได้ด้วยความเด็ดขาด คณะกรรมการรัฐรับรองอำนาจการสั่งการของคุณในภายหลัง', zh: '✅ 严厉的领导力。他很愤怒，但还是退缩了。几分钟后，屋顶在他的人原本会待的地方发生了崩塌。你凭着坚强的意志救了他们的命。州委员会随后维持了你的指挥威权。' }, stats: { competence: 40, ethics: 40, leadership: 80, innovation: 0 } },
            { id: 'B', text: { en: '🤝 Collaborative Persuasion: "Chief, I respect your experience. But look at that truss—it\'s failing. I need your team to protect the perimeter instead. Please."', th: '🤝 โน้มน้าวด้วยความร่วมมือ: "หัวหน้า ผมเคารพประสบการณ์ของคุณนะ แต่ดูขื่อบ้านนั่นสิ มันกำลังจะพังแล้ว ผมต้องการให้ทีมของคุณช่วยคุมพื้นที่รอบนอกแทน ได้โปรดเถอะ"', zh: 'B 合作式说服：“队长，我尊重您的经验。但看看那根桁架——它快撑不住了。我需要您的队伍去负责周边保护。拜托了。”' }, consequence: { en: '✨ Diplomatic Win. You appealed to his ego and his mission to protect his men. He agreed and moved his team. You gained a powerful ally and prevented a tragedy without a shouting match. A true master of people.', th: '✨ ชนะด้วยทูตสัมพันธ์ คุณเข้าถึงอีโก้และภารกิจในการปกป้องลูกน้องของเขา เขายอมตกลงและย้ายทีม คุณได้พันธมิตรที่แข็งแกร่งและป้องกันโศกนาฏกรรมได้โดยไม่ต้องเถียงกัน คุณคือมาสเตอร์ด้านการจัดการคนอย่างแท้จริง', zh: '✨ 外交式胜利。你打动了他的自尊心，呼应了他保护下属的使命。他同意了并撤走队伍。你在没吵架的情况下赢得了一个强大的盟友并预防了悲剧发生。真正的驭人大师。' }, stats: { competence: 40, ethics: 40, leadership: 60, innovation: 40 } },
            { id: 'C', text: { en: '🤷 Let Them Go: "Fine, it\'s your funeral. If you want to go in, I won\'t stop you. But my men stay out."', th: '🤷 ปล่อยเขาไป: "ก็ได้ อยากตายก็เชิญ ถ้าคุณอยากเข้าผมก็ไม่ห้าม แต่ลูกน้องผมจะอยู่ข้างนอก"', zh: 'C 随他们去：“好，自寻死路。如果你想进去，我不拦着。但我的人得留在外面。”' }, consequence: { en: '💀 Moral Failure. You are the IC, you are responsible for everyone on the scene. Three volunteer firefighters died when the roof collapsed. You were stripped of your rank and face years of lawsuits for negligence. A commander never lets a subordinate commit suicide.', th: '💀 ความล้มเหลวทางศีลธรรม คุณคือผู้บัญชาการเหตุการณ์ คุณต้องรับผิดชอบทุกคนในพื้นที่ อาสาสมัคร 3 คนตายเมื่อหลังคาถล่ม คุณถูกปลดจากตำแหน่งและโดนฟ้องร้องฐานละเลยการปฏิบัติหน้าที่ไปหลายปี ผู้บัญชาการต้องไม่ปล่อยให้ลูกน้องไปตายเด็ดขาด', zh: '💀 道德失败。你是现场指挥员，你要对现场的每一个人负责。屋顶崩塌时有三名志愿消防员遇难。你被剥夺了军衔，并因玩忽职守面临长年的诉讼。指挥官绝不能坐视下属自杀。' }, stats: { competence: 10, ethics: 10, leadership: -90, innovation: 0 } },
            { id: 'D', text: { en: '📻 Radio Silence: "I\'m ordering all channels to ignore the volunteer department. They are not part of our plan."', th: 'D ปิดวิทยุ: "ผมสั่งให้ทุกช่องสัญญาณไม่ต้องตอบรับหน่วยอาสาสมัคร พวกเขาไม่ได้อยู่ในแผนการของเรา"', zh: 'D 无线电静默：“我命令所有频道都忽略那支志愿消防队。他们不属于我们的计划。”' }, consequence: { en: '❌ Operational Chaos. By cutting communication, you made it impossible to warn them of danger. Two different units almost sprayed each other with high-pressure water. The scene became a total disaster. Communication is the heart of firefighting.', th: '❌ ความวุ่นวายในการปฏิบัติงาน การตัดการสื่อสารทำให้คุณเตือนอันตรายเขาไม่ได้ หน่วยงานที่ต่างกันสองหน่วยเกือบฉีดน้ำใส่กันเองจนบาดเจ็บ พื้นที่นั้นกลายเป็นหายนะโดสมบูรณ์ การสื่อสารคือหัวใจของการดับไฟ', zh: '❌ 行动混乱。通过切断通讯，你导致无法向他们发出危险警告。两个不同的单位险些用高压水枪互相喷射。现场变成了一塌糊涂。沟通是消防工作的核心。' }, stats: { competence: 15, ethics: 20, leadership: -60, innovation: 0 } }
        ]
    },

    {
        id: 'fir_050',
        text: {
            en: '🎖️ The Final Alarm: After 30 years of service, you are walking out of the station for the last time. Your gear is clean, the trucks are ready for the next crew, and the town is safe. A young probie stops you at the door and asks"What’s the most important thing I need to know to survive this job?"',
            th: '🎖️ ระฆังสุดท้าย: หลังจากทำงานมา 30 ปี คุณกำลังเดินออกจากสถานีเป็นครั้งสุดท้าย อุปกรณ์ของคุณสะอาด รถพร้อมสำหรับทีมต่อไป และเมืองก็ปลอดภัย เด็กใหม่อาสาสมัครหยุดคุณที่หน้าประดูแล้วถามว่า "สิ่งสำคัญที่สุดที่ผมต้องรู้เพื่อจะมีชีวิตรอดในงานนี้คืออะไรครับ?"',
            zh: '🎖️ 最后的警报：服役30年后，你最后一次步出消防站。你的装备擦拭如新，消防车也为下一组队员整装待发，城镇一片安详。一名刚过试用期的新人在门口拦住你，问道：“要在这一行生存下去，我必须知道的最重要的事是什么？”'
        },
        options: [
            { id: 'A', text: { en: '🧠 The Mind: "Trust your training, but never stop learning. The day you think you know it all is the day you get someone killed."', th: '🧠 สติปัญญา: "เชื่อมั่นในการฝึกฝน แต่อย่าหยุดเรียนรู้ วันที่คุณคิดว่ารู้หมดแล้วคือวันที่คุณจะทำคนตาย"', zh: '🧠 思想：“相信你的训练，但永远不要停止学习。当你自以为无所不知的那天，就是你害死别人的那天。”' }, consequence: { en: '✅ The Mentor Legacy. You pass on the wisdom of constant improvement. The young firefighter becomes a legend in his own right, always chasing new safety tech. You leave a legacy of intelligence and safety.', th: '✅ มรดกแห่งครูฝึก คุณส่งต่อปัญญาแห่งการพัฒนาตนเองอย่างต่อเนื่อง พนักงานใหม่คนนั้นกลายเป็นตำนานในแบบของเขา คอยตามหาเทคโนโลยีความปลอดภัยใหม่ๆ เสมอ คุณทิ้งมรดกแห่งสติปัญญาและความปลอดภัยไว้เบื้องหลัง', zh: '✅ 导师的传承。你传授了不断进取的智慧。那名年轻消防员成了他那一辈的传奇，始终追踪最新的安全技术。你留下了一份充满智慧与安全的遗产。' }, stats: { competence: 80, ethics: 50, leadership: 60, innovation: 40 } },
            { id: 'B', text: { en: '❤️ The Heart: "Take care of your team and they will take care of you. We go home together, or we don\'t go home at all."', th: '❤️ หัวใจ: "ดูแลทีมของคุณ แล้วพวกเขาจะดูแลคุณ เราจะกลับบ้านด้วยกัน ไม่เช่นนั้นก็ไม่กลับเลยสักคน"', zh: '❤️ 灵魂：“照顾好你的团队，他们也会照顾好你。我们要么一起回家，要么一个也别回。”' }, consequence: { en: '✅ The Brother Legacy. You reinforce the bond of brotherhood/sisterhood that defines the service. Your station becomes the tightest unit in the state, with zero injuries for a decade. You are remembered as the "Heart of the House."', th: '✅ มรดกแห่งพี่น้อง คุณย้ำเน้นสายสัมพันธ์ที่นิยามงานบริการนี้ สถานีของคุณกลายเป็นหน่วยที่เหนียวแน่นที่สุดในรัฐ และไม่มีใครได้รับบาดเจ็บเลยตลอดสิบปี คุณถูกจดจำในฐานะ "หัวใจของสถานี"', zh: '✅ 兄弟般的传承。你强化了定义这项职业的兄弟/姐妹情谊。你的消防站成了全州最团结的单位，十年间保持零伤亡记录。你被人们铭记为“消防站之魂”。' }, stats: { competence: 40, ethics: 80, leadership: 80, innovation: 10 } },
            { id: 'C', text: { en: '🛠️ The Tools: "Be a master of your equipment. A tool is an extension of your body. If it fails, you fail."', th: '🛠️ เครื่องมือ: "จงเป็นนายของอุปกรณ์ เครื่องมือคือส่วนต่อขยายของร่างกายคุณ ถ้ามันพลาด คุณก็พลาด"', zh: '🛠️ 工具：“要精通你的装备。工具是你身体的延伸。如果工具失效了，你也玩完了。”' }, consequence: { en: '✅ The Master Legacy. You leave behind a culture of extreme technical proficiency. The mechanics of the department name a tool maintenance award after you. You ensured that every life lost was due to fate, not equipment failure.', th: '✅ มรดกแห่งยอดฝีมือ คุณทิ้งวัฒนธรรมความเชี่ยวชาญทางเทคนิคขั้นสูงไว้ แผนกซ่อมบำรุงตั้งชื่อรางวัลการดูแลเครื่องมือตามชื่อคุณ คุณทำให้แน่ใจว่าชีวิตที่เสียไปคือเรื่องของโชคชะตา ไม่ใช่ความผิดพลาดของอุปกรณ์', zh: '✅ 大师的传承。你留下了一种极端推崇技术精湛度的文化。部门的维修组以你的名字命名了一个工具保养奖。你确保了每一个生命的逝去都是因为天命，而非装备故障。' }, stats: { competence: 90, ethics: 30, leadership: 40, innovation: 20 } },
            { id: 'D', text: { en: '🛡️ The Mission: "Remember who we work for. The citizens are our masters. Serving them is the highest honor in the world."', th: 'D ภารกิจ: "จำไว้ว่าเราทำงานให้ใคร ประชาชนคือนายของเรา การรับใช้พวกเขาคือเกียรติยศที่สูงที่สุดในโลก"', zh: 'D 使命：“记住我们在为谁工作。市民是我们的主人。为他们服务是世界上至高无上的荣誉。”' }, consequence: { en: '✅ The Saint Legacy. You define the service as pure sacrifice. You are honored with a statue in front of the city hall. You inspired generations of young people to join the fire service for the right reasons.', th: '✅ มรดกแห่งนักบุญ คุณนิยามงานนี้ว่าคือการเสียสละอย่างแท้จริง คุณได้รับเกียรติมีรูปปั้นตั้งหน้าศาลาว่าการ คุณเป็นแรงบันดาลใจให้เยาวชนรุ่นต่อๆ ไปเข้าร่วมงานดับเพลิงด้วยเหตุผลที่ถูกต้อง', zh: '✅ 圣徒的传承。你将这项职业定义为纯粹的奉献。市政厅前为你树立了一座雕像。你激励了一代又一代年轻人为了正确的理由加入消防事业。' }, stats: { competence: 50, ethics: 90, leadership: 70, innovation: 0 } }
        ]
    }
];
